/* 平成25年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h25.committeeSessions.push(...[{"id":"h25-20130311-3","meetingId":"h25-c-budget","date":"2013年3月11日","dateIso":"2013-03-11","committee":"予算特別委員会","time":"午前１０時００分～午後５時５８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を167件抜き出しています。","topics":[{"id":"topic-01","title":"平成２５年度品川区一般会計予算","agenda":"平成２５年度品川区一般会計予算","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"今日も１日よろしくお願いいたします。３月１１日になりました。質問に入らせていただきます。２８３ページです。今回、マイスター店等支援事業の中で、生鮮三品の支援をしていくというようなことが示されておりますが、どのような形でこの生鮮三品、いわゆるこの生鮮三品を選ばれた理由と、どのような形で支援されていくのかということについてご説明をお願いいたします。","respondent":"米田商業・観光課長","answer":"こちらにつきましては、期間を決めまして、生鮮三品店応援キャンペーンということで、現時点の計画では、生鮮三品店のレジ袋等にかえて、保冷バッグを配布し、生鮮三品店の利用向上、それから。","id":"exchange-001"},{"speaker":"渡部委員","kind":"質問・要望","question":"ぜひそのような保冷バッグをつくっていただくのであれば、何度か使える、例えば品川区のマークが入っていたりしてもつまらないので、何か宣伝になるようなもの、５日と２０日は区報の日とか、何か目立つようなこれを持って歩いていただくと、また、何か書いてあると見えるようなものにしてほしいという思いがあるのですが、ただただ保冷バッグ。","respondent":"米田商業・観光課長","answer":"繰り返し使えて、いわゆる生鮮三品のお買い物に役に立つというようなことで、ある程度何回か繰り返して使えるものを予定していますが、通常お持ちになって、二度と持ち歩きたくないようなことがないように。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"今ちょっと申しました品川技術ブランドＰＲ事業、２８５ページの中で、メードイン品川ＰＲ事業についてお伺いしたいのですが、これが平成２１年ぐらいから始まったのでしたか、年々始まっていまして、今回、予算が大きく伸びております。メードイン品川ＰＲ事業について、昨年度までの展開と、また今年度から大きく変わるような何か展開がありましたら教えていただけますでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"今年度につきましては、これまで新製品、新技術、あるいは環境対策支援事業、そういった事業で助成案件となりました１５３件の中から審査をいたしまして４件を選びまして、今年度、さまざまなＰＲを行ったというものです。","id":"exchange-003"},{"speaker":"渡部委員","kind":"質問・要望","question":"それで、ちょっとページは飛びますけれども、先ほど、企画財政課長の説明の中で、品川ビジネスクラブのほうへもこれから法人出捐金ですとか入ってくるという中で、いよいよ平成２７年、平成２８年でしたか、品川ビジネスクラブのセンターができるのに向けて足場がつくられてきていると思いますが、このいわゆるものづくり産業における品川全体のにぎわいというのですか、企業力というのでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"今年度からもそうですけれども、今言われました品川の技術力をＰＲしていくということで、専門展示会のほうに出展しています。これがかなり好評でして、参加する企業もいますし、また、訪れた方からも品川の技術力についてかなり認識を深めていただいています。","id":"exchange-004"},{"speaker":"渡部委員","kind":"質問・要望","question":"今、課長からご答弁いただきました。本当にそうですね。何か相談があった場合、親身になって乗っていただくのと同時に、保証協会等ともあわせて金融機関に対しても、今までどおりやってほしいという旨のアクションというのは出し続けていただきたいと思います。一つ、最後にお伺いします。課長、率直に品川の経済は今どうなっていると思うでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"さまざまありまして、なかなか難しいところでありますけれども、中小企業を見ていますと、やはり二分極化しているのではないかというふうに思います。","id":"exchange-005"},{"speaker":"阿久津委員","kind":"質問","question":"私からは、２６５ページ、衛生費から、カラス・外来種対策事業、同じく衛生費から、２５７ページ、母子歯科衛生事業、そして時間があれば、２７９ページ、産業経済費から観光アクションプラン推進事業についてお伺いします。１番目のカラス・外来種対策事業、予算も少ない非常に小さな事業ではありますけれども、ちょっと私も思い入れがあるものですから質問します。","respondent":"野呂瀬環境課長","answer":"ハクビシン・アライグマ対策のことについてです。区内の状況から先に説明いたしますと、昨年度、１７件、区民の方からお問い合わせ等がありました。１７件のうち被害に遭ったというのは、大体天井裏に住みついているのではないかとか、そういうような情報です。","id":"exchange-006"},{"speaker":"阿久津委員","kind":"質問","question":"それも区のほうに申し上げたのですけれども、そのときは調査していただけなかったということもありますが、今回、どうなったら調査をしていただけるのか、そこのところをお伺いしたいと思います。予算、そのときに１件につき５万円以上かかるというふうに言われましたけれども、今回、機械的に予算がついていると思うのですが、これで足りるのかというところをお聞きしたいと思います。","respondent":"野呂瀬環境課長","answer":"場合によっては、それを捕獲ということですと、それは当然委員が今おっしゃったとおり、専門業者というか、都知事の許可を得ている業者でないとできませんので、連携をとりながらやっていくということになると思います。","id":"exchange-007"},{"speaker":"阿久津委員","kind":"質問・要望","question":"子どもの歯科健診について伺います。それでお聞きしたいのですけれども、この主催が歯科医師会になっていて、後援が品川区となっておりますが、これは１００％のボランティア事業なのでしょうか。もし委託であるとするならば、その予算の中に、２５７ページの母子歯科衛生事業というところに計上がありますけれども、これの中から出していると、こういうふうに考えてよろしいのでしょうか。","respondent":"江部健康課長","answer":"ここにある予算につきましては、保健センターで行っております２歳、３歳の歯科健診相談事業、それから、歯科予防ということで、各歯科医師会に委託しておりまして、６月から８月までに、３歳児に対してフッ素塗布事業ということで委託しておりますもの、それから、区内の公立。","id":"exchange-008"},{"speaker":"阿久津委員","kind":"質問・要望","question":"この事業の目的の一つとして、歯の状態が年のわりに異常に悪い場合には、児童虐待の疑いで発見ができるということも出ておりまして、希望者となった場合に、そういう児童虐待をしているような疑いのある親だと、なかなか連れていかないということもありますでしょうし、健診の場合だと、必ずだれが来て、来なかったと思うものですから、この辺のことを考えると、今後この谷間である４歳児、５歳児。","respondent":"江部健康課長","answer":"中野区の５歳という話も、私も新聞で読みまして、新しく始めるという認識があるという程度です。","id":"exchange-009"},{"speaker":"阿久津委員","kind":"質問・要望","question":"今、園のほうを回っていただいているというお話もありました。続きまして、２７９ページ、産業経済費、観光アクションプラン推進事業についてお伺いいたします。日本に来たらどこに行きたいのか、どこに行くのか、何を見たいのか、品川区においてこのような将来を見据えた外国人の観光客、あとは一般の観光客も含めたニーズ調査、こういったものは今行われているのでしょうか。","respondent":"米田商業・観光課長","answer":"現在のところ、区として単独で調査というものは特に行っておりませんが、モニターツアー等を行った際には、ご意見等をお伺いしながら事業を進めている、そのようにやってあります。","id":"exchange-010"},{"speaker":"阿久津委員","kind":"質問","question":"そういう中で、今日お伺いしたかったのは、観光アクションプランに関連してですけれども、歳入のところで伊藤委員からも質問がありました。そのときの伊藤委員の答弁では、しかるべき時期が来たらと、そういうお話がありましたけれども、これについてのご見解を伺って終わりにしたいと思います。","respondent":"米田商業・観光課長","answer":"いわゆるご指摘のありました新駅の関係、それから品川駅のリニア等を含めた開発の関係、あるいはアジアヘッドクォーター特区でいわゆる臨海部のほうにお客様がたくさん来る、こういう状況を常にとらまえて。","id":"exchange-011"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"２５１ページの予防接種費のうち任意予防接種と、同じ２５１ページの感染症予防費に関連して風疹対策についてお伺いいたします。感染症予防費に関連して、さらに流行が拡大している風疹対策についてお伺いいたします。昨年、決算特別委員会でも風疹流行についてお尋ねいたしました。本年に入ってからの品川区の風疹の流行状況はいかがでしょうか。","respondent":"伊津野保健予防課長","answer":"今年になりまして既に３９名の発生の届けがあります。例年でしたら１例か２例ですので、かなりの大流行だというふうに考えております。","id":"exchange-012"},{"speaker":"鈴木（博）委員","kind":"質問","question":"決算特別委員会の繰り返しになりますが、今年の風疹患者の年齢、性別、あるいはその原因としてどのようなことが考えられるのでしょうか。","respondent":"伊津野保健予防課長","answer":"今年の今回の流行の特徴としまして、２０代から４０代の男性が７割を占めております。この原因としましては、予防接種の制度の転換期に当たりまして、もともと予防接種を受けていないか、あるいは予防接種を受ける機会があっても接種率が低かったということが考えられます。","id":"exchange-013"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今年の流行の特徴というのは、今、ご答弁にありましたように、男性患者が多く、特に３０代を最多に２０代、４０代が続いているということ。この世代の男性は風疹のワクチンを受けていないということがあります。風疹は三日はしかといわれるように、麻疹に比べて症状が軽く済むことが多いのに、なぜ今、その流行が問題になっているのでしょうか。","respondent":"伊津野保健予防課長","answer":"妊婦が妊娠初期に感染しますと、白内障、先天性の心疾患、心臓の病気、あるいは難聴になる、このような障害が起きることが問題であります。","id":"exchange-014"},{"speaker":"鈴木（博）委員","kind":"質問","question":"特に２０から２４週ぐらいまではリスクが高いと言われています。平成１５年から平成１６年に、中国地方、これは日本の中国ですが、中国地方で風疹が小流行したときも、先天性風疹症候群の赤ちゃんが１０名産まれました。特にこの小児の課題である先天性風疹症候群の発生に対する施策として、品川区ではどのような取組みがなされているのでしょうか。具体的な対策のご説明をお願いいたします。","respondent":"伊津野保健予防課長","answer":"ＭＲワクチンの未接種者に対しましても、個別勧奨の通知を１月末に送っており、さらに学校に対してポスター掲示とかでさらに啓発の徹底をお願いしているところであります。","id":"exchange-015"},{"speaker":"鈴木（博）委員","kind":"質問","question":"よくわかりました。そして、風疹ワクチン単独よりは麻疹の予防を兼ねたＭＲワクチンを勧めています。そこでお聞きしますが、２５１ページの任意予防接種のところに、ＭＲ（任意）とありますが、このＭＲのワクチン、これは定期接種で行われているものですが、任意接種に入っている理由をご説明ください。","respondent":"伊津野保健予防課長","answer":"ＭＲの定期接種でありますが、これは１歳あるいは小学校就学前の１年間、現在は中学校１年、高校３年という形で、１年単位で行っております。それは定期接種として行っておりますが、万一打ち漏れた場合に次の年も任意接種として受けられるような制度であります。","id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"麻疹制圧のためにはこれは非常に意義深い制度だと思われますが、これは品川区独自の施策なのでしょうか。それとも、例えば補助金などが使われているのでしょうか。それと、あと例えば、この施策を今回の風疹の流行の対策として適用するということができないのでしょうか。","respondent":"伊津野保健予防課長","answer":"これは東京都の医療包括補助という形で、２分の１の補助を受けて実施している施策であります。現在のところ、１８歳未満という制限がありますので、今回の流行の中心であります２０代から４０代の男性に対して行うことは現時点では不可能であります。","id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今回の風疹大流行の７割は首都圏でありまして、当然、東京都としても何らかの対策が行われるものと思われます。東京都の包括補助というものが、今回の流行に関して緊急対応するような機動性のある対応というのは、検討とか、実際できないものなのでしょうか。","respondent":"伊津野保健予防課長","answer":"実は、子宮頸がんワクチンが開始される場合も、現在、国で行っております促進事業に先立って東京都の包括事業が始まっております。このように機動的な対応というものはとれるものだと考えています。","id":"exchange-018"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最後に、これから産まれてくる小さな品川区民を先天性の障害から守ることは、単に感染症対策のみならず、区の子育て支援とか、障害者対策にもかかわる重要な問題だと強く感じるところでありますが、款をまたがりますが、この観点から区のお考え、お立場をお伺いしたいと思います。","respondent":"伊津野保健予防課長","answer":"款をちょっとまたがってしまう回答ですが、今回の大流行というのも、品川区だけで流行しいるわけではありませんので、東京都全体としても何らかの対策が行われるものだと考えています。そういう場合は、至急対応し、検討していきたいと考えています。","id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"質問","question":"よろしくご検討お願いいたします。次に、本年の４月１日から定期接種になると思われる、定期接種になることになっている３ワクチンのうち子宮頸がん予防ワクチンについてお伺いいたします。４月１日から定期接種におそらくなるだろうということになっております子宮頸がん予防ワクチン、これはサーバリックスとガーダシルと２種類のワクチンがあるのですが、これについて簡単にご説明をお願いいたします。","respondent":"伊津野保健予防課長","answer":"今、お名前が挙げられました、まず平成２１年１２月に発売が開始されましたサーバリックスという子宮頸がんの原因となりますＨＰＶ１６、１８という二つのタイプに有効なワクチンと、その後、後発ですが、平成２３年８月に発売開始されましたガーダシルという同じくＨＰＶ１６。","id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そこで質問いたします。予算説明によれば、品川区では定期接種化がおくれたとしても、本年の４月１日から、子宮頸がん予防ワクチンの接種費用を任意接種として全額補助、助成を行う予定だったとお聞きしました。定期接種化の動きもあったはずですが、あえてこの時期に全額助成に踏み切った理由についてお伺いしたいと思います。","respondent":"伊津野保健予防課長","answer":"予算要求時には定期化の時期がはっきり決まっておりませんでしたので、平成２５年度の年度途中から行われる、定期化される可能性もありました。その混乱を避けるという意味もありますし、一刻も早く接種率を上げたいということがありました。","id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"私も議会でたびたび要望してきましたけれども、全額助成の実現というのはすばらしいニュースだと思って非常にうれしかったです。ところが、今回の定期接種化を控えて、一部の全国紙が杉並区の副反応と考えられる事例について現在報道しております。そもそも子宮頸がんワクチンの安全性というのは、どのように評価されたのでしょうか。","respondent":"伊津野保健予防課長","answer":"ＷＨＯはじめ多くの機関でも、公衆衛生的施策として強く推奨されているものでありました。","id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"昨年の１０月に「平成２４年度第４回薬事・食品衛生審議会医薬品等安全対策部会安全対策調査会及び第２回子宮頸がん等ワクチン予防接種後副反応検討会及び第１回不活化ポリオワクチン予防接種後副反応検討会」、非常に長い会が開催されましたが、その中の副反応の報告は、サーバリックス、ガーダシルについてはいかがだったのでしょうか。","respondent":"伊津野保健予防課長","answer":"この報告によりますと、サーバリックスは７００万回の接種に対しまして、重篤な副反応が８５例、ガーダシルは１００万回の接種に関しまして、１１例の重篤な副反応があったとされております。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この件で思い出しますのは、ちょうど一昨年の今ごろ、Ｈｉｂのワクチンと小児用肺炎球菌ワクチンで子どもが亡くなったというセンセーショナルな報道がなされまして、厚生労働省が一昨年の３月４日、Ｈｉｂと肺炎球菌のワクチンを一時中止しました。子宮頸がんワクチンは、今現在、全世界でどのぐらいの国が何人ぐらい接種を受けているのでしょうか。","respondent":"伊津野保健予防課長","answer":"ともに１００カ国以上で数千万人単位の人が接種されております。","id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"質問","question":"したがって、年間９,０００人の女性が発病し、２,７００人の方が死亡している子宮頸がんをワクチンで防ぐのか、それとも先ほどお話があったように、紛れ込みを除くと、大体７００万回に２０から３０ぐらいの割合で起こる重い副反応のリスクを重く考えるのか、これはよく考えてみなければいけません。定期接種された場合、子宮頸がんワクチンの勧奨は現在は変わるのでしょうか。","respondent":"伊津野保健予防課長","answer":"今回、定期化された場合は、区民には接種義務、努力義務という形で努力しなければいけないという課題が課せられますので、十分な情報提供を行うとともに、積極的な勧奨をしていきたいと考えています。","id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"質問","question":"定期接種化された場合、そのメリットとして、上記の健康被害が起きた場合でも、予防接種法の健康被害救済制度で、任意接種に比べて非常に有利な補償が受けられると思いますが、その点いかがでしょうか。一言でお願いします。","respondent":"伊津野保健予防課長","answer":"現在でも民間の保険会社を使いまして、定期接種と同じようなレベルの補償を行っておりますが、今後は国の補償になりますので、より安心な補償になるというふうに考えております。","id":"exchange-026"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ワクチンを実際に接種している医療人として、この問題は今後も深く考えていきたいと、その思いを新たにしております。すべての施策の遂行には、評価されるよい点とともに、悪い点も必ず出てきます。よい点はさらに推進し、悪い点は改善していく柔軟な視点を常に持たなければならないと思います。今後も子どもの健康と幸せのために、さらなる施策の推進、その検証を希望して今回の質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"木村委員","kind":"質問","question":"質問に先立ちまして、２年前に起きました東日本大震災、多くの方々が尊い命を亡くされました。私からは、２６５ページの環境対策費の環境保全事業６,５７６万円についての質問をいたします。しかし、地方自治体としてしっかりと目標を定めて努力しなければいけませんが、本区としての目標は、２５％に設定していると思いますけれども、それでよろしいのかどうかお答えください。","respondent":"野呂瀬環境課長","answer":"それにつきましては、２５％というのは当然無理だということですけれども、今、品川区の計画では、それに向かって計画が一つは進んで、地域推進計画ということで進んでおりますけれども、当然それを視野に入れながらですけれども、一番大事なのは、日々の生活の中で削減していく。","id":"exchange-028"},{"speaker":"木村委員","kind":"意見","question":"この太陽光発電システム設置のことですけれども、その助成、１,２０４万円余からですけれども、まだ平成２４年度中ですけれども、現在まで何件ぐらい実行しているのか。そして、平成２４年度までは前期と後期に分かれていましたけれども、平成２５年度からはシステムや助成金額が変わると言われていますが、どのように変更されますか。お願いいたします。","respondent":"野呂瀬環境課長","answer":"今年度の算出ですけれども、補助金につきましては、計上していますものは、先ほど申しましたとおり、１キロ当たり、今年度まで１０万円だったものを３万円にして、計上的には１００件ということで、９万円の１００件で９００万円分を太陽光の助成として計上しています。","id":"exchange-029"},{"speaker":"木村委員","kind":"質問","question":"先日の本会議の２日目ですけれども、稲川委員のほうからの質問の中で、この屋根貸しという言葉が出ました。しかし、区長の施政方針で、太陽光発電設備について、新たに中小企業センターや区有施設への設置に努めてまいりますとありますが、本当に公立小・中学校の屋根や屋上に設置をするお考えはないということでしょうか。本区のお考えを再度お聞きいたします。","respondent":"野呂瀬環境課長","answer":"新たにまた区の施設に設置するのも、これも太陽光発電の普及に努めているところで、区独自で区の施設に設置して、その学校の中でやっていくような、屋根貸しはしないですけれども、太陽光発電はできる限り、可能な限り設置に努めていく、こういう姿勢です。","id":"exchange-030"},{"speaker":"木村委員","kind":"質問","question":"今日もほかの委員から質問がございました。先日の委員会でも外来種とはどのような生き物でしょうかという質問がありまして、私もハクビシンとアライグマと聞きまして大変驚きました。あるとすれば、年間何件ぐらいあるのか。そして、公園、神社仏閣、学校、民有地等にある樹木に巣をつくるということを言われますけれども、すべてこれは環境課のほうで担当するのでしょうか。これも最後にお答えください。","respondent":"野呂瀬環境課長","answer":"すべて環境課か、環境課が窓口になりまして、環境課でやっているのは民有地に限ってということで、例えば公園だとか学校だとか、そういうものにつきましては、関係の所管と連携をとりながらやりますけれども、あくまでも民有地については環境課の所管でやっているです。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"２８５ページのものづくり活性化事業費について、品川区内のものづくり支援について伺いたいと思います。仕事が減り、単価が下がり、材料費は上がり、どこで話を伺っても、先の見通しが立たない。年度末の決算期に倒産をするか毎年考えている。改めてこういう危機感をどこまで把握しているのかということと、こうしたところへの支援策については、どう考えているのか伺いたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"確かに厳しい工場が多いというのは認識しています。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"改めてこの危機感についてどう考えているのか伺いたいのと、それでは、どうするのかという支援策については、知恵を出し合うことが大事なのかというふうに思います。先日、この点で下町ボブスレーの報道を見ました。立ち上げは大田区の町工場の職人たち。それとこの大田区には大田区産業振興協会というものがありますが、品川区にはちょっと見当たらないですけれども、経過も含めて現状を伺いたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"しかし、公としての支援はなかなか難しい面もありますので、品川ビジネスクラブというものを昨年法人化しまして、そちらのほうでも支援を行っているということです。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"ビジネス創造コンテストも始まったばかりというところもありますが、今後の方向についても伺いたいと思います。大田区がボブスレーを仕掛けているわけですけれども、同じボブスレーにするかどうかは別にして、大事なのは目的だと思います。テーマについてはいろいろ自由でよろしいかと思いますけれども、改めてこうした事業について、どう取り組んでいくのか、伺いたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"ビジネス創造コンテストの方向性ですけれども、過去３回やりましたけれども、次年度、終わりにつきましては、この過去３年の実績をもとに新しいビジネス、あるいは商品を直接開発し、それを販売できるように、そのようなものを目指しているものです。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"町工場の運営もその奥さんのパートで実際、生活もするし、たまには材料費も入って運転資金にしたり、そういう厳しさがある。こうした町工場の実態と、品川ビジネスクラブの今後の方向性がうまくかみ合っていけるのか、また、かみ合うにはどういう支援が必要なのか、ぜひ下町ボブスレーなどのアイデアにも学びながら、品川の今後の方向をしっかりと進めていただきたいと思いますが、改めて伺いたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"まさに品川ビジネスクラブはそういった工場の人たちが集まっているクラブですので、そういった人たちの状況に合わせた事業展開を行っていきたいというふうに考えてあります。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問","question":"２６４ページの環境対策費に関連して、それから、先ほどありました２７９ページ、観光アクションプランに関連してまず質問したいと思います。先に、環境のほうでありますけれども、改めて今、品川区内では放射能の測定はしているのでしょうかということと、それから、しているのであるならば、その最新の結果はどうでしょうか。ちょうど東日本大震災から２年目でありますのでお伺いしたいと思います。","respondent":"野呂瀬環境課長","answer":"ずっと継続して、今、区内２箇所、荏原と品川の保健センターの敷地で、週１回ですけれども、これは区で購入した測定器を使って職員が測って、それを毎週１回、区のホームページにずっと継続して発表しています。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"提案","question":"そこで提案ですけれども、ちょうど今、ＰＭ２.５の話が相当出ていますよね。ですから、当然、品川区でもやれることは限られているとは思うのだけれども、おそらく東日本大震災の放射能の影響よりもこちらのＰＭ２.５のほうの影響が長く日本に来る可能性があると思われるので、それはさまざまな形で研究して対処していっていただきたいと思うのですが、ご答弁をお願いいたします。","respondent":"野呂瀬環境課長","answer":"したがいまして、区として独自の測定は行っておりません。ちなみに、東京都の測定器が都内に８０カ所ありますけれども、６２区市町村の８０カ所の中で区内には４カ所それが設置されております。","id":"exchange-037"},{"speaker":"伊藤委員","kind":"質問","question":"現状の動きは一定理解するところはありますけれども、やはりよく私たちは、区民に最も身近な自治体ということを言っているわけでありますから、そういう国、東京都の仕組みの中であっても、ある程度、こういうことに対しては品川区は積極的になるべきではないのかと思うのが素直な思いです。いかがでしょうか。","respondent":"野呂瀬環境課長","answer":"どちらにしましても、区として情報は的確に都のほうから来たら、それをできるだけ早く正確な情報を区民の方々にお知らせしていくという、この姿勢は前もそうですし、今も変わりはございません。","id":"exchange-038"},{"speaker":"伊藤委員","kind":"質問","question":"アクションプランについては、先ほどほかの委員からの質問がありました。戦略を進めていくという答弁を最後にいただきましたけれども、それを聞いて思い出したのは、高知県高知市だったでしょうか、あそこは坂本龍馬に徹底して観光行政をやっています。ですから、全国から多くの方々が来る市になっている。","respondent":"米田商業・観光課長","answer":"例えば、今年度におきましては、観光協会のほうで事業、特に舟運を生かした観光事業をやっていこうというようなことで、昨年度、観光協会で舟運事業に取り組んだ日数ですが、３日間だったのですけれども、今年度はさまざまな事業を展開しておりまして。","id":"exchange-039"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、ましてや全世界から羽田空港からお客さんを呼び込もうとするとなるならば、これはもっともっとさまざまな形で検討していかなければいけない。やっていただきたいですけれども、さらに進めていかないと、羽田空港からのお客さんを呼び込むことも含めて、この内容が具体化していかないと思うので、改めてご答弁をお願いいたします。","respondent":"米田商業・観光課長","answer":"観光協会等である程度特化してやっていくということでしたら、その辺のところも見据えることはあり得るのかと思いますけれども、行政といたしましては、やはり品川区全域を広く見極めた施策の推進、これは行っていくべきではないかというふうに考えているところです。","id":"exchange-040"},{"speaker":"伊藤委員","kind":"質問","question":"だけれども、それをむしろ発展させていくためにはどうしたらいいかということの観点の指摘でありますので、しかるべき時期とおっしゃっていました、しかるべき時期にこのことを総合的に検討してくださいますように改めてお願いしておきますので、よろしくお願いいたします。ですから、この施策を推進するに当たって、優秀な人材をどう確保して、品川区としてどう対処していくのかお聞かせください。","respondent":"福島ものづくり・経営支援課長","answer":"彼らは技術力も持っていますし、また経営力を持っている方がいらっしゃいます。そういった人材を活用しながら進めてまいりたいというふうに考えている次第です。","id":"exchange-041"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、私たちとしては、この事業を推進するに当たっては、ぜひともそういう人材をしっかり、今の人材がどうということではなくて、的確なアドバイスをしていただいて、多くの企業がこの制度を活用して一人立ちをして、区内で新たな企業活動を展開していってもらいたいと願う思いから指摘をするわけですので、そのカタリストの方々の、失礼になるような言い方をしなければいけませんけれども。","respondent":"福島ものづくり・経営支援課長","answer":"ＮＰＯのほうでそういった支援をしているＮＰＯもありますので、そういったＮＰＯという組織力、そういうものも活用しながら優秀な人材を集め、支援体制を確立していきたいというふうに考えてあります。","id":"exchange-042"},{"speaker":"塚本委員","kind":"確認","question":"私からは、２５３ページの成人歯科健診、それから２７９ページの若者就業支援事業、もし時間があれば２８１ページの商店街活性化事業費についてお伺いしたいと思います。あわせて、ある意味確認ですけれども、こういった高齢者の方々や障害者の方々にとって、歯の治療というのが、ご自身の健康にとってどういう関係にあるかということもお伺いしたいと思います。","respondent":"江部健康課長","answer":"今委員ご指摘の歯科の障害者、認知症の方の口腔という部分につきましては、歯の健康は全身の健康の入り口であるとよく言われますので、重要なことであるということ、それから、なかなか一般の方や健常者よりも歯の健康状態が維持されにくいという認識は持っております。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"感染症についても、感染症にかかっている、エイズとかにかかっている方の歯科診療、そういったものについても、普通の状況の歯科医師ではなかなかできないというふうに伺っておりますが、この辺についてはどのようなご認識をお持ちでしょうか。","respondent":"江部健康課長","answer":"訪問歯科につきましては、車で出かけるわけですけれども、歯科医、それから歯科衛生士とセットになりまして、それなりに歯を削ったり、そういった治療もできる体制で訪問歯科診療は今やっていただいている現状にあり、感染症等の対策についても。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"品川区といたしましても、こういった障害者の方とか、なかなか普通の歯科診療では治療し切れないような重度の障害を持っている方とか、感染症の方、こういった方々への歯科診療の設備、センター、こういったものを準備をしていく、用意をしていく必要があるのではないかと、このように思いますけれども、どのようにお考えでしょうか。","respondent":"江部健康課長","answer":"歯科医師であったり、歯科衛生士、それからケアスタッフ等々につきまして、さまざまな場、福祉カレッジ等でも研修をやっているというふうに聞いておりますし、やはり対応のノウハウ、それから必要な器具などの準備によって。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひ、これは歯科医師会、品川区に二つありますけれども、この歯科医師会等との話し合いなどもしながら進めていっていただきたいというふうに思いますけれども、現在、現状で区とこの歯科医師会等とでこういった認知症高齢者、また障害者に対する歯科診療について、何らかしらの話し合い、こういったものは行われておりますでしょうか。お伺いしたいと思います。","respondent":"江部健康課長","answer":"先ほどの繰り返しですが、まず平成２４年度、障害歯科事業が始まったということにつきましては、この間、二度ほど打ち合わせ会を持ち、どうしたらその事業の実績、数を上げていけるかという部分で、どういう事業なのかということの周知を工夫していくことは必要だろうということ。","id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"ただ就職を間に入ってあっせんをするというだけではなくて、就職してからも、それが就労し続けられるようにと、こういう支援も視野に入れているというところは非常に大事なことであるというふうに私も着目いたしておりますけれども、この就労し続けるというところについて、区としてどういった支援、考え方、これを持っておられるかお伺いしたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"就職後も支援を続けるということで、何か仕事についての悩みですとか、あるいは問題、職場での課題なんかがありました方とか、そういったことにつきましてもキャリアカウンセリングを個別に行ってまいりますので、そういった中で解決していきたいというふうに考えている次第です。","id":"exchange-047"},{"speaker":"塚本委員","kind":"質問","question":"こういったことで特に発達障害とかは、民生費の議論でもありましたけれども、本人が自覚をして、自分はそういう人間だからこういうことに気をつけなくてはいけないというようなことを自覚をしていれば、まだいろいろな話も進みやすいと思いますけれども、本人はそういうことが気づいていなかったりした場合は。","respondent":"福島ものづくり・経営支援課長","answer":"今、委員から出ました発達障害につきましては、本当に発達障害ということであれば、関係機関のほうと連携しながら進めていくということで、直接就業センターのほうで発達障害者に対して何かを行っていくというようなことは今のところ考えていないところです。","id":"exchange-048"},{"speaker":"塚本委員","kind":"質問","question":"その人材の確保は非常に重要だと思いますので、よろしくお願いしたいと思います。ちょっとこれはどうでしょうか、必要に応じて考えていく必要があるかと思いますけれども、最後にお伺いしたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"現在の場所にはやはり無理だと思いますので、中小企業センターの中でどこか考えたいというふうに思っております。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、品川区としても真剣に取り組んでいかなければいけないだろうという項目だと考えていますので、尊重しながらいろいろといい方法を今後考えていただきたいというふうに要望したいと思います。次に、マイスター店です。これは各店がやるべきことであって、なぜ区がやらなければならないのか、それをして活性化とはどういう意味だろうというふうに思いますが、その考え方についてお聞きします。","respondent":"米田商業・観光課長","answer":"生鮮三品のいわゆる保冷バッグについてですけれども、先ほど、別の委員の方からのお話でもお答えいたしましたが、品川区として、いわゆる生鮮三品店を支援していくというような位置づけをきちんと打ち出していくというような意味合いで、この事業を実施しているものです。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"その店舗店舗がその地域の中でどういう形で特徴を出していくのか、むしろそういう選ばれたお店が自分たちはこういうところに特徴があるのですよということがあるならば、それを伸ばしてあげる支援が一番いいだろうと思っています。それに対して競合するという場合もありますよね。なので、そういう競合してしまうという場合をどういうふうに考えていくのかということもあわせてお聞きします。","respondent":"米田商業・観光課長","answer":"全体の中で配達サービスに取り組んでいきたいというような商店ばかりではありませんで、そこのところの商店街全体としてやっていくというようなことの意識づけといいますか、流れを持っていくというようなことについては、非常に今後の課題であるかと考えていますので、ただ、今。","id":"exchange-051"},{"speaker":"西本委員","kind":"質問・要望","question":"これはやはり絞った形で、ターゲットをしっかりと定めた形で支援をするという、自立をやはりしていただきたい。それについてどう考えられるか。それから、商店街活性化と組織力強化支援とありますけれども、この組織力とは何でしょうか。それと、商店街という考え方と、小規模商店街という考え方、これの違いという、それから、どういう効果を期待してこれらの事業があるのかを教えてください。","respondent":"米田商業・観光課長","answer":"にぎわい事業というものにつきましては、例えばイベント事業というものは、いわゆる年に１回の大きなお祭りというようなことでやってありますが、にぎわい事業ということでは、年に６回以上繰り返して継続的な商店街の販促セールとかの支援を行ってくださいというようなことで。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"さまざまな施策、十分わかっております。しかしながら、これらを本当に効果的になっているのかということについては、検証をしっかりとしていただいて、税金ですので、有効的に活用していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"向委員","kind":"質問","question":"よろしくお願いします。私からは、ページで言うと、２５４ページ、２５５ページの妊婦健康診査全般と、あと、時間があれば、マタニティーマークとか、そのあたりについてもお尋ねしたいと思います。妊婦健康診査についてですけれども、今、全体で１４回、区の助成の分と、あと、国からの助成ですか、トータルで１４回ということになっているかと思います。","respondent":"江部健康課長","answer":"妊娠届、母子手帳交付数ですけれども、平成２３年度で３,９３０件です。うち電子申請については２００件程度です。","id":"exchange-054"},{"speaker":"向委員","kind":"質問・要望","question":"一つ確認させていただきたいのが、電子申請、そのうち１割までまだ行っていないみたいですけれども、それなりに数があるかとは思いますが、電子申請した場合には、母子手帳などはどのようにお母さん方の手元に届くのか、確認ということでお願いします。初回大体助成枠としては８,４６０円ということでよろしいですか。","respondent":"江部健康課長","answer":"この点につきまして、どうしてこういうルールになっているかと申しますと、妊婦健診のあり方につきまして、東京都でどのように取り組むかという検討会が平成１９年に行われまして、妊婦健康診査公費負担のあり方に関する検討会ということで、これは２３区。","id":"exchange-055"},{"speaker":"向委員","kind":"質問・要望","question":"先ほどお話したように、最近では初回にもう妊婦の負担の軽減から、まとめて血液検査とか、どっとされることが多いと。なので、妊娠することは決して病気ではないけれども、健康を維持していく必要性は、それはもう否定できない事実ですし、それはもうきちんと区としても対応していただきたい、東京都、日本全国対応はしていただきたいと思いますので、このあたりについてもどのようにお考えか教えてください。","respondent":"江部健康課長","answer":"検討会ですが、いつもあるというものではなく、平成１９年のときに、これから先の東京都内での妊婦検診のあり方をどうしようかということを考えるために設置された一時的な会だというふうに認識しておりますので、今現在あるというふうには思っておりません。","id":"exchange-056"},{"speaker":"向委員","kind":"質問・要望","question":"私が聞いたところ、今年の幹事区は荒川区ということですから、あり方検討会、まだ続いているというような話も聞いているのですが、ちょっとそれはまた改めて確認させてください。これはまた別の機会にでもお尋ねします。それについて、啓発をある程度行っていただいてはいると思うのですが、区としてそういった嫌がらせがあるとか、そういったお話をお母さん方から聞かれているでしょうか。","respondent":"坂上品川保健センター所長","answer":"今、委員の言われた嫌がらせということは、区のほうには特に入っておりません。","id":"exchange-057"},{"speaker":"沢田委員","kind":"質問・要望","question":"２５３ページ、健康診査費、それから２５９ページの不妊治療助成事業、それから２８３ページの共同装飾灯維持管理費補助についてお伺いさせていただきたいと思います。","respondent":"江部健康課長","answer":"これにつきましては、なかなか意識の薄い世代ではありますので、ポイントを捕まえて生活改善はしていただくように健康福祉事業部全体で取り組んでいっているところでありますし、これからも工夫してまいりたいと思います。","id":"exchange-058"},{"speaker":"沢田委員","kind":"質問・要望","question":"それとちょっと話がそれてしまいますが、品川区も職員の健康診断ということで、年に１回やっておりますが、私もその健康診断に参加させていただいていますけれども、報道で健康診断で来る健診車の胃の検診のバリウムのところで、医師がそのところにいないのではないかという報道がされていましたけれども、品川区に来ている健康診断の車に医師は一緒に同乗されているのか確認をさせていただきたいと思います。","respondent":"堀越人事課長","answer":"健康診断、職員の健康診断がありますが、医師につきまして、庁内のほうに来ていただいて、健康診断について監督をしていただいているという、そういうような状況にあります。","id":"exchange-059"},{"speaker":"沢田委員","kind":"質問","question":"本当に健康ということでもう１点聞きたいのですけれども、心の健康づくりということでやっていますけれども、ゲートキーパー研修とか、品川区はいろいろ自殺対策も進めているところではありますが、現状でどういった相談等が来て、またゲートキーパーの研修とはちょっと別ですけれども、区のほうにこういった自殺に関する相談とか、そういったことは来ているのかということと、それから。","respondent":"福島荏原保健センター所長","answer":"そのことについてはいろいろ理由を聞いて、お話を聞いてあげて、その人にどういう具合にしたらいいかということを考えて対処しておるところであります。","id":"exchange-060"},{"speaker":"沢田委員","kind":"質問","question":"なかなか個人情報の問題等があって難しいとは思いますけれども、そういった区内の病院とか、そういったところとの連携というのはあるのでしょうか。","respondent":"福島荏原保健センター所長","answer":"自殺を予防するには、そういういろいろな機関との連携が必要だと思います。そういう意味も兼ねて、品川区では、品川区両医師会との連携を深めるために連絡会議というのを毎年持っているという状況です。","id":"exchange-061"},{"speaker":"沢田委員","kind":"質問・要望","question":"２５９ページの不妊治療費の助成について、お伺いします。今後のこの見通しというか、これからもおそらく増えていくであろう不妊治療について、予算の面でも限度があるかと思いますけれども、今後どのようにお考えになられているのか、平成２５年度もきっと多いということだと思いますが、その辺のところの見通しをお聞かせください。","respondent":"江部健康課長","answer":"今のところでこういう方針だということを平成２６年度以降申し上げることはできませんけれども、流れが変わっていると、傾向は変わっているという認識は持っておりますので、引き続き、分析をしつつ、今後どうしたらいいかは考えていきたいと思います。","id":"exchange-062"},{"speaker":"沢田委員","kind":"質問","question":"この品川区が行っている一般不妊治療について、昨年度でも前年度でも構いませんけれども、この件数のうちで、これで１回で子どもが、不妊治療の助成を受けて１回の助成でできるということはなかなか多くないと話は聞きますけれども、２回以上こういった助成を申請されているという組数は、昨年度でもわかっている数の中で構いません、どれぐらいあるでしょうか。","respondent":"江部健康課長","answer":"１回でというよりも、あくまでも複数回の方がほとんどでございまして、平成２３年度ですと、申請者４６９名に対しまして、妊娠組数が１０８件、四、五組に１組の割合で妊娠に到達しているです。あくまでも一度ではなく、二度、三度という複数回での申請内容になっております。","id":"exchange-063"},{"speaker":"沢田委員","kind":"意見","question":"なかなかそういった形で１回ではできにくいということもあると思いますけれども、中には一般の不妊治療で子どもができる確率は１０％以下と、そういう話もあります。今後、一般不妊治療が増えていく中で、新たに限られた予算の中で特定不妊治療への助成ということも考えられるのではないかと思いますけれども、そのあたりはどういった考えでありますか、その辺のところをお聞かせください。","respondent":"江部健康課長","answer":"その特定不妊の方の上乗せも、確かにその特定不妊の方にとってはプラスではありますけれども、費用対効果の問題もありますので、今後考えします。","id":"exchange-064"},{"speaker":"沢田委員","kind":"質問・要望","question":"ちょっと時間がないですが、共同装飾灯維持管理費補助ということで、２８３ページのところになりますけれども、品川区は商店街の振興等で装飾等に大変電気代等も補助をしているかと思いますけれども、この装飾灯の電気代に関して、いろいろと固定で契約している商店街と、東京電力との契約の中でそれぞれ個々に定額でやっている商店街と、それから、メーターをつけてはかっている商店街がありますけれども。","respondent":"米田商業・観光課長","answer":"電気の契約につきましては、あくまでも個々の商店街がどういうような形でやっているかということですので、その中で、例えば節電の工夫なりで変えていくというようなことは、個々の商店街が行っていただくべきだろうと考えています。","id":"exchange-065"},{"speaker":"沢田委員","kind":"質問","question":"時間がなくなってしまったので質問ができなかったのですが、電気代がそれぞれ東電の関係で、急に値上げがされたり、そういったことで不安定な状況になっていますので、その辺が統一的な補助ができればということで質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"山元委員","kind":"質問・要望","question":"初めに、本日、東日本大震災から２年がたちました。ページ数が２４９ページの各種助成金の中の公衆浴場、そして時間がありましたら、２５１ページの予防接種費を１点お聞きしたいと考えています。その前もやはり同じぐらいで若干の差が、誤差といいますかあるのですけれども、今回この平成２５年度の３,１３９万円余の予算ですが、どのような基準で立てられたのかを教えていただきたいと思います。","respondent":"江部健康課長","answer":"設備の改修、ボイラーですとか、そういったものを改修するというものにつきましての金額と、それからあと、借入をされている方への利子の補助を合計して３,０００万円という組み立てになっております。","id":"exchange-067"},{"speaker":"山元委員","kind":"質問","question":"三つのところからこういうふうに予算立てをしたということでありましたけれども、実際この品川区内には３１軒、お風呂屋さんがあるということでありますけれども、実際、具体的に、先ほどいろいろお話がありましたけれども、いろいろ直しながら、またお金を借りながらいろいろ経営を進めているのだと思いますけれども、この３１軒の経営していくというか、継続していく状況といいますか、どういう状況なのか。","respondent":"江部健康課長","answer":"少しずつ設備を変えているというところについては、部分改修ということなので、今後、大規模な建替えをするのかどうかという判断に迫られるのではないかという認識を持っております。","id":"exchange-068"},{"speaker":"山元委員","kind":"質問・要望","question":"その結果、お年を召した方は電車に乗って遠いところまで行ったりとか、また、ある方は、１カ月近くお風呂へ入っていないというお話も聞いて、大変これは問題であると思います。実際、この現状、区としてはどのように、まずこのゼロといいますか、ないことをご存じなのか、そしてまた、区としてこの対応策といいますか、どのように思っていらっしゃるのかも教えていただきたいと思います。","respondent":"江部健康課長","answer":"確かに浴場の存続というのは、入浴による清潔の保持という点では重要なことであるということは認識しておりますが、なかなか金額的なものでかなり一つの浴場の維持というのは大きいので、例えば出会いの湯事業による活性化、その他。","id":"exchange-069"},{"speaker":"山元委員","kind":"質問","question":"何かとっても消極的で、お風呂のない人はかわいそうだという感じがするのですが、実は必死になって探しました。お風呂のない人たちは困ってしまいますので、区役所のそばにあるお風呂屋さんですけれども、利用、今、お風呂代は４５０円ですか、それはそれとして、送迎代として一人であれば５０円払えば自宅まで迎えに来てくれるという、そういうお風呂屋さんがありました。","respondent":"江部健康課長","answer":"今の送迎の件は初めてお聞きしました。ということで、今後調べします。","id":"exchange-070"},{"speaker":"山元委員","kind":"質問・要望","question":"ぜひすぐそばの宮城湯のお風呂屋さんですので、入っていただきたいと思います。しかし、本当に今、現状、この３１軒のところが皆さん抱えているのは、跡取り問題とか、そういう借金のことだと思いますけれども、実際、この問題に対して区が寄り添って対応というか、いろいろ援助してあげないといけないのではないかと思いますが、区はどのように思っていらっしゃるか、具体的に何かあれば教えてください。","respondent":"江部健康課長","answer":"具体的な決め手というのは持ち合わせておりませんが、私ども、浴場組合の皆様方とは、この補助金の関係と、あともう１本、出会いの湯事業を運営する関係での連絡会を毎年やっております。","id":"exchange-071"},{"speaker":"山元委員","kind":"質問・要望","question":"やはりお風呂屋さんには背景に富士山がつきものですけれども、あの絵を例えばモニターというか、ニュース板にするとか、何かいろいろなことを考えるといいますか、ニュースとかが流れるとか、スペースの利用とか、そういうことを考えると、継続できる道ができるのではないかと思いますので、そういう意味では、自分たちだけではなく、いろいろな意見を取り入れていただいて、いろいろな意見を聞きながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"２８３ページの商店街支援で、装飾灯の電気代補助についてお伺いしたいと思います。そして、今、商店街の中でこの装飾灯をＬＥＤ化している商店街は、全体で幾つあるのかということと、そのＬＥＤ化するに当たっての補助金の仕組みがどういうふうになっているのかについてもお聞かせください。","respondent":"米田商業・観光課長","answer":"東京都環境対応型商店街活性化事業という制度もございまして、こちらは電球のみならず、いわゆる躯体ごと取り替えるというようなことですが、こちらにつきましては、東京都のほうで３分の２以内の補助、それから、区のほうで６分の１の補助。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういう形で、私は区としても上乗せをして、ぜひＬＥＤ化を進めていただきたいと思いますけれども、いかがでしょうか。それともう一つは、装飾灯の電気代補助というのが、常に緊急経済対策ということで、今年も継続しますみたいな形でやっていますけれども、ぜひともこれを恒久的な制度ということで変えていただきたいと思うのですが、この点についてもお聞かせください。","respondent":"米田商業・観光課長","answer":"今後も商店街の状況等を見極めつつ、施策のほうを考えてまいりたいと考えています。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"東電の値上げ分の補助の増額という点についてはいかがでしょうかということと、私は、ＬＥＤはどんどん区として積極的にすべての商店街がＬＥＤ化できるぐらいの、そういう姿勢で進めていただきたい、これが電気を節約することにもつながりますし、手間の問題でもすごく有効なので、ぜひそれは進めていただきたいと思います。","respondent":"野呂瀬環境課長","answer":"それと、新築の割合ですけれども、先ほどお示ししたとおり、今年度、全体で申請が８９件ありました。新築がどれくらいあったかというのは、ちょっと把握できないのであれですけれども、当然、太陽光ということであれば、ほとんどその中で太陽光を申請した方と同じぐらいです。","id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、原発事故から２年たって、マスコミでも言われているように、事故の原因すらわかっていない、１５万人もの方が自宅に戻れない、子どもを安心して育てられない、核のごみの処理ができない、こんな中で、やはり自然エネルギーをとんどん増やしていくという、こういう立場で太陽光発電はぜひとも増額をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"藤原委員","kind":"質問","question":"２５７ページ、乳児健康診査、２８３ページ、商店街全般について、２８７ページ、品川先端産業支援プロジェクト。商店街から伺いますが、改めてお伺いします。さまざまな施策を商店街に向けていますが、一般の区民にとっての商店街支援というのは、どのようなメリットがあるのでしょうか。","respondent":"米田商業・観光課長","answer":"あわせまして、日中、子どもたちを見守る機能があったりですとか、あるいは、町の安全・安心、災害のときに帰宅困難者の方を温かく受け入れて、それなりのもてなしをしたりとかというようなことでは、ほかにもいろいろあろうかと思いますが。","id":"exchange-077"},{"speaker":"藤原委員","kind":"質問","question":"それで、区民委員会で羽田空港に視察に行ったときに、改めて私が羽田空港の観光の窓口の方に、品川区の特徴はどういうものですかと、どういうふうに答えますかと言いましたときに、品川区は商店街ですと、担当課長もこの言葉を覚えていらっしゃると思います。それは今までこの中で出ていますけれども、都市観光の一つではないかと私は思っているのですけれども、まずその辺についてはどう思いますか。","respondent":"米田商業・観光課長","answer":"そういった意味では、東京を代表する商店街、また元気な町というのが品川の一つの売りではないかということを考えておりまして、これは観光についても大いにつなげていきたいと、このように考えてあります。","id":"exchange-078"},{"speaker":"藤原委員","kind":"質問","question":"まさにそのとおりで、商店街に対して、やはり施策を通して応援していかないといけないと私も思っておりますけれども、そんな中で、生鮮三品の話が出ていますけれども、コンビニです、いわゆるコンビニで、マイバスケットとか、あと、ナチュラルローソンとか、あと、セブンイレブン等でいわゆる生鮮を扱うようになったではないですか。","respondent":"米田商業・観光課長","answer":"その辺について、やはり差別化をして、地元の方々から支持される取組みというのは、各商店のほうも大事だろうと考えていますし、品川区としてもそれを支援してまいりたいと考えています。","id":"exchange-079"},{"speaker":"藤原委員","kind":"質問","question":"今後とも商店街支援、さまざまな支援があると思いますが、よろしくお願いします。次、すくすく赤ちゃん訪問事業ですけれども、４カ月健診から始まって、１歳６カ月、３歳と健診がありますよね。ここに来られない方への対応とか、あと調査はどのようにしているでしょうか。","respondent":"坂上品川保健センター所長","answer":"その後、２回でいらっしゃらないときには、アンケートを送らせていただいておりまして、その後、もう一度、二、三カ月待っても来られない方には、お電話させていただいておりまして、その後、また訪問などもしています。","id":"exchange-080"},{"speaker":"藤原委員","kind":"質問","question":"学校に入るときの調査がマスコミなどで取り上げられましたよね。一方では、ネグレクト等の虐待の問題が心配されていると思いますけれども、これらの健診で把握できなかった子どもに関して、区としてどういうふうに把握をしていくおつもりなのか教えてください。","respondent":"坂上品川保健センター所長","answer":"ただ、そういう方は４カ月健診のときにお会いできるので、大抵の方はお会いできるので、そこでまたお話を聞かせていただいておりますが、４カ月健診にもいらっしゃらない方に関しましては、子育て支援課のほうで把握しているということで、こちらから報告書を上げております。","id":"exchange-081"},{"speaker":"藤原委員","kind":"質問","question":"完全に網羅できているという感覚でいたいと思いますので、今後ともよろしくお願いいたします。最後に、品川先端産業支援プロジェクトですが、大崎駅の東口の再開発に合わせて進められていると思っているのですが、この項目が次第に事業の項目の歳出の数が増えていますよね。その辺について、今後の展望をお伺いします。","respondent":"福島ものづくり・経営支援課長","answer":"この品川ビジネスクラブをどういうふうに進めていくか、また、先ほど出ました大崎の再開発とどうしていくか、その辺については今後検討していくということで考えております。","id":"exchange-082"},{"speaker":"大倉委員","kind":"確認","question":"よろしくお願いします。私からは、２５１ページ、感染症予防費に関連して、ここに入ると思いますが、ＨＩＶ即日検査について、あと、ページ、２７９ページ、若者就業支援事業についてお伺いします。そこで、今回このプレス発表資料のほうにも書いてありますが、６月の土曜日にやるということですが、なぜ土曜日になったのかお知らせください。１２月１日に世界エイズデーというのがあります。","respondent":"伊津野保健予防課長、福島ものづくり・経営支援課長","answer":"６月に実施するということで、１２月ではないのかということですが、試行ということなので、次年度に向けてその効果を検証したいということで、１２月よりは６月でやっていきたいという形で検討しております。離職率を把握するためのアンケートですが、特にそのようなアンケートは今のところ予定はしていないのですが、ただ、来年度、中小企業ニーズ調査を行いますので、そのニーズ調査の中で若者の離職率。","id":"exchange-083"},{"speaker":"大倉委員","kind":"意見","question":"はＨＩＶのほうですが、土曜日にやるのは平日来られない方がということでしたが、厚生労働省の発表している新規のＨＩＶ感染者数が二、三十代が多いということですが、ここからすると、やはり土曜日に２０代、３０代、働いている方はなかなか受けられないのではないかというところがあるので、こういった部分で言うと、例えば日曜日とかにはできないのかという率直な疑問が沸いてくるのですが。","respondent":"伊津野保健予防課長、福島ものづくり・経営支援課長","answer":"検査の日ですが、一応今、土曜日という形にしておりますが、今後、日曜日ということも検討していきたいと考えています。同期会ですけれども、今回この若者就業支援事業の一つとして行われます若者就業体験事業、こちらのほうでは、３０人から４０人の若者を集めて就労させますので、そういった方々につきましては。","id":"exchange-084"},{"speaker":"大倉委員","kind":"質問・要望","question":"受けやすいＨＩＶ検査、即日検査については受けやすい環境づくりをぜひとも徹底してやっていただければと思います。５０名というキャパがあるようですが、そういった部分では、予約なしでぜひ、いきなり来てもできるというほうが、やってみようかという気にはなるかと思うので、それはぜひ、難しいかもしれませんが検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"本多委員","kind":"確認","question":"やはり相談者のプライバシーを考えれば、中小企業センターの１階というのは、すごい人が往来して、エレベーターに乗る人、階段を上がる人、１階に用がある人も、必ずあそこをほとんどの方が通るので、プライバシーの確保はどうかということを投げかけたのですが、１階に設置をされて、今度またスペースを拡大というような答弁が先ほどあったので。","respondent":"福島ものづくり・経営支援課長","answer":"スペースの拡大ですけれども、こちらは新たに若者就活相談コーナーというのを中小企業センターのどこかにつくろうということで、今、検討しています。","id":"exchange-086"},{"speaker":"本多委員","kind":"質問・要望","question":"質問に入ります。そうした教訓を活かして、生垣助成ということで、もう本当に２０年近く取り組んでいただいていると思いますが、その辺の区内の状況を全体として教えていただきたいと思います。事務事業概要で平成１９年度から平成２３年度の５年間の実績は、６、６、６、２、７ということで、それはわかっていますので、これまでの取組みの効果というか、その辺についてお聞かせいただきたいと思います。","respondent":"多並公園課長","answer":"それにつきましては、来年度から地元の方々とお話をしながら、１地区を指定し、進めていきたいと、そのように考えているところです。","id":"exchange-087"},{"speaker":"本多委員","kind":"質問・要望","question":"防災緑化のほうは、１地区指定して進めていくということで、スピーディーに進めていっていただきたいと思いますが、この生垣緑化とあわせて、今までは助成ということで促すというか、自主的にやってくださいというようなところでやってきて、あまり実績がここ数年伸びていないので、この辺は助成をするのはいいのですが、自主的に促すというよりかは、危険箇所を発見して。","respondent":"多並公園課長","answer":"この点を踏まえまして、来年度につきましては、１地区指定させていただいた地区の中で、ただ助成金をやるのではなくて、支援委託ということで、地域の皆さんでワークショップといった形で一緒に町歩き等、地元で見て、どのような形がいいかということも含めまして。","id":"exchange-088"},{"speaker":"本多委員","kind":"質問・要望","question":"パソコンなどはメーカーやパソコン３Ｒ推進協会へ、ここまでは従来どおりだと思いますが、この１６品目に含まれなかったもの、縦横高さ３０センチ超えるもの、この辺の扱いについては、国のほうの動向ですとか、その辺の扱いというのでしょうか、最初、国は９６の中から１６品目を選んだと思いますが、１６品目については、今年からやるということでわかるのですが。","respondent":"太田品川区清掃事務所長","answer":"粗大ごみの中から、旧東品川清掃作業所で積替えをいたします。その中で小型家電で何品目かを同時に仕分けをして、抽出をして、これを他の１６品目と同時に認定事業者のほうへ引き渡していこうというふうに考えているところです。","id":"exchange-089"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、回収ボックスの盗難防止対策ですとか、携帯電話の記録された個人情報ですとか、その辺について教えていただきたいと思います。運営スタッフが受付を行うことで、その個人情報の保護と持ち去り防止というふうに書かれているのですが、その辺を詳しく教えていただきたいと思います。","respondent":"太田品川区清掃事務所長","answer":"拠点回収につきましては、受付ということで３人、それから量の多い拠点回収場所については４人、受付員が配置をしています。その上で、盗難防止、それから個人情報の保護ということで、回収ボックスをそこの場所へ置く予定です。","id":"exchange-090"},{"speaker":"本多委員","kind":"質問・要望","question":"その携帯電話の個人情報などですが、運ぶ対応はわかりました。安心なのですが、それで、携帯電話を最後にパンチングというのですか、情報データを全部壊すような、そこまでのことをもう一度、こうして個人情報がきちんと抹消されますよという、そこだけ教えていただきたいのです。","respondent":"太田品川区清掃事務所長","answer":"それから次に、資源化センターに行って、私どもで携帯、分類をして、最終的に認定事業者のほうで物理破壊をする、基盤をとった後にメモリ等を破壊すると、こういうことが認定事業者、小型家電リサイクル法の中で認定される事業者については。","id":"exchange-091"},{"speaker":"本多委員","kind":"質問・要望","question":"２７３ページの東京二十三区清掃一部事務組合分担金等ですが、毎年予算の審議のたびに数字を見ていくと、いつもごみ量が減っているのに、その負担金が増えている年があって、なぜだろうと思う年もあったのですが、平成２４年度が１６億円余に対して、今回は平成２５年度の予算は１４億円余ということで、２億円ぐらい下がっているということで、いろいろな工夫がされているのかと思いますが。","respondent":"太田品川区清掃事務所長","answer":"ただ、８社から今度は逆に４社へし尿会社が減ってありますので、各区で契約するというのがなかなか難しいということで、ちょうど私どもは西側です、杉並区、目黒区、大田区等を中心とした７区で協議をして、杉並区と協定を結んで、杉並区で契約をする。","id":"exchange-092"},{"speaker":"浅野委員","kind":"質問","question":"これは以前の話です。胃がんについてですけれども、平成２３年度は５,００９人が検診を受けて、率として３.７％、平成２４年度の予測はどうなっているかお伺いします。平成２５年につきましては、６,０００件の予算でちょっと下がっておりますが、この平成２４年度に送付した検診クーポン券の件数と、検診された件数の見込み、そして、検診率の見込み、これについてお伺いします。","respondent":"江部健康課長","answer":"胃がん検診と肺がん検診について、平成２５年度、どの程度の見込みをしたのかということにつきましては、胃がん検診については３.９％、肺がん検診については、横並びの数字ですが５.７％を見込みました。","id":"exchange-093"},{"speaker":"浅野委員","kind":"質問","question":"平成２４年度の見込みをお伺いしたかったのですけれども、後で答えてください。これは聞いているのは、このクーポンと言ったのは、これは区のほうが言っていまして、クーポンというのは、はっきり言って、この人は受けられるよということでリスク検診については送ったものですから、私もそういう使い方をさせていただいたものであります。","respondent":"江部健康課長","answer":"平成２４年度につきまして、見込み件数、胃がん検診が４,５００件、肺がん検診は６,０００件です。それから、リスク検診につきましては、対象者数、５０歳から５歳刻みで７５歳まで、総数２万３,７２１名、うち受診者が１２月末で１,９７１名、率にして８.３％です。","id":"exchange-094"},{"speaker":"浅野委員","kind":"質問・要望","question":"この５歳刻みというのを、例えば２歳とか３歳ぐらいに細かく分けていくとか、もしかしたら全体をそのまま対象年齢で検診できるようにしていっても私はいいのかと思っているのですけれども、このように自治体によっては年齢を決めずに、このピロリ菌検診をやっている、リスク検診をやっているところもあるかと思いますので、今後の取り組みについて教えてください。","respondent":"江部健康課長","answer":"平成２４年度の７月ごろでしょうか、スタートいたしまして、確かに年度末に差しかかりまして、受け漏れた方、平成２５年はどうするのという話がありますが、受診券にも、あと１年受けられますということで、２カ年を今想定しておりまして、来年度についても同じような形で。","id":"exchange-095"},{"speaker":"浅野委員","kind":"質問","question":"最近、報道されているところによりますと、このピロリ菌の除菌についても、２月２１日から保険適用になったというふうに聞いております。私が一番気にしているのは、費用の負担ですけれども、この小型家電の回収については、運ぶ運賃と処理費がかかるかと思いますけれども、これは自治体がそのまま全部負担をされるのか、それとも引き取り側が負うのか、こちらについて教えてください。","respondent":"太田品川区清掃事務所長","answer":"その売却費用の中で、今、委員がご指摘いただいた収集運搬費用等を負担するということになってあります。したがって、基本的には区が費用負担をするということはございません。ただ、区内の拠点回収を回る収集運搬費用は区が負担をする、これは当然のことだと思います。","id":"exchange-096"},{"speaker":"浅野委員","kind":"質問・要望","question":"こちらのほうも以前ペットボトルかなんかが価格が下がって、なかなか厳しくて、逆有償というのでしょうか、そういう状況になりかねないような話があったのですけれども、これは何とかこのようなリスクが発生するようなところはぜひとも避けていただきたいと思うわけでありますけれども、例えば、この回収業者ですとか、認定事業者、認定事業者はまだ決まっていなくて、４月以降発表されるということですが。","respondent":"太田品川区清掃事務所長","answer":"この事業者については一定の要件がございまして、都道府県３県以上の範囲を担うとか、あるいは、認定事業者およびその委託を受けた者の資本、財政基盤、施設規模、能力というものがございまして、おそらくそんなに多くの事業者。","id":"exchange-097"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうは、ページ、２６５ページ、環境対策費の中の大気汚染調査というのを重点的に、１,１９５万５,０００円、これは午前中にちょっとあったと思いますけれども、都内８０カ所、区内におきましては約４カ所にポイントがあるということですけれども、実際の問題として、この辺のところの、その４カ所のほうの、一般的な区民からの感覚でよろしいですか、専門的に深く入り込んでいってしまうと。","respondent":"野呂瀬環境課長、福島ものづくり・経営支援課長","answer":"そのデータというのは、それを日々東京都のホームページ等で公開していると、そのホームページ等で公開しているのを区のホームページにも載せて、わかりやすく説明している、そういうことです。ベトナムの件ですけれども、委員おっしゃいましたように、タイのほうで３年間行ってまいりました。そちらの事業では、無事順調に進んでおりまして、次の展開へという声、中小企業の皆様方からそういう声を聞いております。","id":"exchange-098"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、その思いについて、もう一言いただきたいというのと、あと、これは最先端で進んでいるほうですからよろしいですけれども、よく出てくる２８１ページ、中小企業支援費という、これはあくまでもお金は借入ですので、これは個別で何と聞いていいのかちょっと、表現といたしましては、前企画部長ですか、というように聞いたほうがいいのか、ちょっと款から外れてしまうかもわかりませんけれども。","respondent":"野呂瀬環境課長、福島ものづくり・経営支援課長、福田会計管理者","answer":"ＰＭ２.５以外の大気ということで、申しわけございません、窒素酸化物とか、ＰＭ２.５以外は区でも独自で測定しております。お金、入金の問題ですが、こちらはいかに事業計画を健全なものにして、資金繰りをどうするかですとか。したがいまして、行政としてそれに対して何らかのものを言うというのは、なかなか難しいだろうというふうに考えております。","id":"exchange-099"},{"speaker":"原委員","kind":"質問","question":"全体的になぜお金の話を出したかと申しますと、キャリアカウンセリングですとか、あと、ビジネス・カタリストですか、この辺というのも非常に大事です。否定はいたしませんけれども、全体的にはどうしても評論みたいな形になってしまって、現実に末端の企業からしてみると、その辺の資金面というのは非常に大事ですので、その辺をご理解いただいて、区の行政も協力していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"稲川委員","kind":"質問","question":"私から、２７９ページの観光アクションプラン推進事業に関連してお伺いしていきます。そこで改めて品川区が考えるというのでしょうか、推進する、プレス発表資料の５０ページにも書いてありますけれども、都市型観光の推進と書かれているので、また今後どういった推進になっていくのかということをお答えください。","respondent":"米田商業・観光課長","answer":"そういった中では、これまでも羽田空港の国際化対応事業ということで、品川区の水辺を活かした取組みですとか、あるいは、外国の方から日本、いわゆる品川の魅力についての観光情報案内誌等、それから、ホームページの多言語化等々に取り組んできたところです。","id":"exchange-101"},{"speaker":"稲川委員","kind":"提案","question":"例えば、新潟県、長野県、山梨県が結構多いということは聞いたり、きちんとその組織もあるやにも聞いておりますけれども、そういった中で、要するに、県人会ですよね、しっかりとした活動をされているので、そういった県とか、そういったところからも協力を仰いで、観光の行き来、交流、そういうものも必要ではないかと思いますが、その辺はいかがでしょうか。","respondent":"米田商業・観光課長","answer":"来年度も引き続き、被災地の方への観光を通じた被災地の支援ということと、それから、区内商業の活性化と合わせましたこの応援ツアーを実施してまいりたいというふうに考えてあります。","id":"exchange-102"},{"speaker":"稲川委員","kind":"質問・要望","question":"最近、私も建設委員会の視察で、ＪＲ貨物の貨客併用という貨物と湘南新宿ラインというのでしょうか、茅ヶ崎からずっと来て八潮まで貨物線に乗ってきたのですが、これについて、どうお考えであるかということと、それであと、これは本会議で質問いたしましたけれども、大井のコンテナターミナルに客船が入って、大型クルーズ船が入ってくる、それについて。","respondent":"米田商業・観光課長","answer":"これについて、いろいろな観点があると思いますが、乗り込まれている方の品川区への招き入れと、それから、それを見学する方へのいわゆるサービスというようなことの両面から捉えて、今後も検討を図ってまいりたい、このように考えてあります。","id":"exchange-103"},{"speaker":"稲川委員","kind":"質問・要望","question":"何か質問しようと思っていたことまでお答えいただいたような気がするので、ぜひそこは力を入れて、東京都の港湾局のホームページでは、もうずっと、クルージングも募集しているぐらいです。人の流れがすごく変わってくるので、そういったサイン掲示板というのですか、羽田空港はこちらですよとかという、設置が必要だと思いますが、それをいかがお考えか教えてください。","respondent":"米田商業・観光課長","answer":"そういった人の流れ、国際化も踏まえた人の流れをとらまえつつ、中延のホームのご指摘もありましたけれども、そこで必要性があるというようなことであれば、またそれは検討の俎上に乗ってくるのではないかというふうに考えているところです。","id":"exchange-104"},{"speaker":"金野委員","kind":"提案","question":"いよいよこの３ワクチンが定期接種化ということで進んでまいりましたけれども、私もこれを待ちに待った一人でありまして、平成２０年の第３回定例会で、Ｈｉｂワクチン等々、お母様からいただいたご相談で提案をさせていただいてから、全国に広がって、こうやって定期接種という運びで大変うれしく思っておりますので、この定期接種がいよいよというところですけれども、国のスケジュール。","respondent":"伊津野保健予防課長、野呂瀬環境課長、江部健康課長","answer":"まさに今、国会のほうで審議されていることでありまして、はっきりとした日時は申し上げられませんが、まずは４月１日実施という形で動いております。ちなみに、保育園、学校等に周知も、今も区のホームページにアップしたのと同時に、関係所管、関係あるところには連携して情報提供しておりますので。母親の年齢につきましては、別の角度での人口動態統計で、母親の第一子出産年齢の比率というのがございまして、今現在。","id":"exchange-105"},{"speaker":"金野委員","kind":"確認","question":"そこで、その中であえて、先ほどもお聞きされておりましたけれども、子宮頸がんワクチン、こちらを来年度は全額無料ということでスタートしてくださる、これは本当に大変にうれしいことでありますけれども、先ほどのご説明ですと、都の包括補助金、これが使えるということで、今までも使えたのではないかという理解をしておったのですけれども、今回入って使えるようになったので使うということなのか。","respondent":"伊津野保健予防課長、野呂瀬環境課長、坂上品川保健センター所長","answer":"先ほど、子宮頸がんにつきまして包括補助と言いましたのは、現在行っております国による促進事業、それが始まる前に。だから、ＰＭ２.５はこれに準じていくのか、それはこれから決まっていくところでしょうけれども、当然そういうふうな形になれば。ホームページのほうで、若い女性の方へということで、痩せ過ぎてはいませんかとか、喫煙についての情報を提供しています。","id":"exchange-106"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"成人歯科健診ですけれども、数字のところを教えていただきたいのですが、平成２４年度の健診の対象者と受診者数、それから、健診をする診療所やクリニックがあると思いますけれども、この健診１件に当たり、区からどれぐらい支払われるのかというのと、あと、指定医療機関はあるのかどうか、あれば幾つぐらいあるのか教えてください。","respondent":"江部健康課長","answer":"成人歯科健診は４０歳以上から７０歳までの方について実施しているものです。平成２５年度につきましては、受診者見込みが、昨年度、１,８５０件から、やや４０歳以上の方が増えておりますので、５５０件を増として２,４００件としたものです。","id":"exchange-107"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私は以前からこの成人歯科健診の対象者を、年齢を、もっと前から若いうちからと求めてきているのですけれども、体のほうの健康診査が３５歳からということで新規計上されています。歯周病も成人病の一つだと思いますけれども、これを一緒にもっと若い年代から、４０歳前から、また、健診機会を失っている年代から広げていただきたいと思うのですけれども、いかがでしょうか。","respondent":"江部健康課長","answer":"歯科につきましては、今のところまだそこまでの情報を把握し、検討しているものではございませんので、今後ということで考えております。","id":"exchange-108"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、もっと早いうちから予防という観点で進めていただきたいと思うのです。注目すべきが若年層の歯茎の腫れ、１５歳から２４歳で６６.１７％ということで、歯周病の出現をあらわす歯周ポケット、これが２５歳から３４歳でぐっと深くなり始めるのです。ですので、この予防、この品川区としての予防の啓発、こういったものをどのように位置づけているのか教えていただきたいと思います。","respondent":"江部健康課長","answer":"委員の説明にございましたとおり、やはり４０歳を過ぎますと、さまざまな歯の疾患も増えてくるということで、私ども、４０歳からということでやっているところです。","id":"exchange-109"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"平成２３年度を見ましても、３万３,０００人ぐらいが健診の対象者だったと思います。それで、２７９ページの次の就業支援費のほうに移りたいと思いますけれども、就業体験のほうですけれども、委託の公募をもうされていますけれども、もう委託先は決まったのでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"若者就業体験事業の委託ですが、こちらは２月６日、区のホームページ等を利用しまして事業者を公募し、２０日に締切り、７社の応募がございました。一次選考はしましたけれども、面接審査を３月１５日に行う予定でおります。","id":"exchange-110"},{"speaker":"石田（ち）委員","kind":"質問","question":"ここは人材派遣会社だというふうにお聞きしたのですけれども、それとは別に、セミナーとか、キャリアカウンセリングとかを行う、サポートするところは、１０月ぐらいから始めるということで、これから公募をされていくということですけれども、働き続けるために、先ほどもほかの委員からありましたけれども、働き続けるための意識を高めたり、研修していくということは私も本当に大事だと思いますけれども。","respondent":"福島ものづくり・経営支援課長","answer":"もう一つです若者就業支援事業です。こちらはプレス発表のとおり、１０月を予定しています。こちら、公募につきましては、来年度、平成２５年度になってからじっくり考えていきたいというふうに思っております。","id":"exchange-111"},{"speaker":"石田（ち）委員","kind":"提案","question":"かといって、普通の就業のほうでは、もうちょっと支援が欲しいという、この狭間に陥ってしまう若者に対して、私たちもずっと支援をというふうにお願いしてきておりますけれども、このジョブコーチというものも一緒に就業支援のところで、若者就業支援のところで一本化というか、そこに行けばできるというふうにしていただきたいというふうにちょっと提案したいのですけれども、いかがでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"そういったことにつきましては、今後の課題というふうに考えておりますので、今回につきましては、就職につける若者の支援をするということで考えております。","id":"exchange-112"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、そういったところの支援もこの就業支援でぜひやっていただきたいと思うのと、きめ細かな対応を、求人者の立場に立ってやっていただきたいというふうに思います。すごく働かせ方の条件が悪質過ぎるというところ、そういったところは今までの就業センターのところでは、告発があったりとか、ここはブラック企業だからもう求人はしないとかというふうにはされているのでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"特にブラック企業についてうちのほうにお問い合わせがあるということはございません。ただ、ハローワークのほうでどのように使っているのか、その辺のところは、今後、ハローワークのほうに聞いてみたいと思います。","id":"exchange-113"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今のところないということですが、このジョブコーチのところは、引き続き検討していただきたいと思います。やはり多くの若者が就業し続けるということが貧困から抜け出し、生活保護からも抜け出していくということにつながっていきますので、ぜひその辺の支援を改めて強く求めたいと思います。いかがでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"ジョブコーチも含めましたいわゆる障害に近い方への支援につきましては、今後、あるいはかなり先の課題だというふうに考えておりますので、とりあえずは今回行います若者就業支援について力を入れていきたいというふうに思っております。","id":"exchange-114"},{"speaker":"石田（秀）委員","kind":"提案","question":"環境対策費全体で教えていただきたいのですが、いろいろ環境の問題は、総務費でも私は、例えば改築とか、いろいろ施設でも何でも、例えば高齢者施設、子育て施設、それから学校も含めていろいろありますけれども、答弁でも各所管としっかり連携して、いろいろな部分で、環境に優しいとか、そういう部分も含めて、各所管と連携をしてやっていきますというようなお話をしていたので。","respondent":"江部健康課長、太田品川区清掃事務所長、野呂瀬環境課長","answer":"健康センターにかかわる経費は、委託料のほか、工事請負費等々で。２点目のし尿の関係ですけれども、先ほどもご答弁したとおり、杉並区を含む関係７区の中で協議をして。ただ、それは各施設の中でもそれはいろいろ事情がありますので、できるだけそういう形で環境に配慮したものを使っていくなり、立てていくなり。","id":"exchange-115"},{"speaker":"石田（秀）委員","kind":"質問","question":"区民会館は。それが５００万円あったのか、１,０００万円あったのかというのがわからなくなるような書き方は、この指定管理でせっかく収入見込みが上がっているのであれば、私はそういう書き方をするべきだと思いますけれども、そこら辺のところを教えてください。今、あそこが民間に委託されているのかどうかわからないけれども、あそこでそれでは、どれだけし尿処理をしているの。","respondent":"江部健康課長、柏原行財政改革担当課長、本城企画財政課長、太田品川区清掃事務所長、野呂瀬環境課長","answer":"歳入につきましては、指定管理がお金も入ってきたものと経費を差し引いて事業者努力で利益を生もうということなので。今、健康課長が申しましたように、１３０万円未満の小さな工事、小破修繕的なものというのを指定管理者のほうに任せて。実際にかかったものの分だけ具体的に算定いたしまして、その部分を財調上上乗せする形で補てんすると、そのような形です。しかしながら、この間、し尿収集量の減に伴いまして、清掃一部事務組合については、業務委託を実施しています。業務委託６名で実施をしています。","id":"exchange-116"},{"speaker":"石田（秀）委員","kind":"提案","question":"健康センターはわかりましたが、ぜひその書き方の中で、私が思うのは、せっかく収入見込み、指定管理者も頑張って上がっているのだから、そこら辺は頑張っているとわかるように、ぜひ予算書も工夫してほしいと思います。そのかわりメニューを出すときに、環境課が、この前も言いましたけれども、例えば漆喰がインフルエンザのＡ型ウイルスを９９％吸収するとか、こういう情報があるではないですか。","respondent":"太田品川区清掃事務所長、野呂瀬環境課長","answer":"現実的には、ご指摘のとおり、し尿の収集量は減ってきてあります。そうした中で清掃一部事務組合についても、いろいろな工夫をして効率的な行政執行に努めてきているところです。委員言われた区が率先して環境保全に努めていく、これは環境計画でも決まっておるところですので、今おっしゃったように、必要な情報は環境課がアンテナを張って、それを関係部署と共有しながら今後の施策に努めていきたい。","id":"exchange-117"},{"speaker":"井上委員","kind":"質問","question":"私からは、産業経済費の２７９ページ、就業支援事業についてお伺いいたします。就業センターが中小企業センター内に移行して成果を上げていることは評価をしておりますが、実際に求人をされた方のうち、就労に結びついた方の人数、割合をお伺いいたします。事務事業概要に平成２３年度のほうの資料がありますので、ちょっと平成２４年度をいただいて比較をしたいと思うのでお願いします。","respondent":"福島ものづくり・経営支援課長","answer":"就業センターですけれども、平成２４年３月から始めまして、２月までの数字です。紹介しました件数が９,１４４件、実際に就職に結びついた数が６８８件です。","id":"exchange-118"},{"speaker":"井上委員","kind":"質問","question":"求人募集件数は、サポしながわのほうは幾つだったでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"求職者として登録されていますのが、２,０４０人です。","id":"exchange-119"},{"speaker":"井上委員","kind":"質問","question":"大分効果があったということですけれども、さらに就業センターの特徴として、新しく生活保護受給者、住宅手当受給者および母子家庭等への就業支援事業との連携を強めるということがホームページに掲載されています。それで、特に生活保護受給者には、就労自立支援相談員とハローワークの就業支援ナビゲーターが協力をし、就業支援に当たられたということですけれども、就業者人数と就職率を教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"先ほど言いました紹介人数のうち、生保の方が９７８名、実際に就職された方が６３名です。","id":"exchange-120"},{"speaker":"井上委員","kind":"質問","question":"９７８名のうち６３名ということで、頑張っていただいたかというふうに思いますけれども、でも、今、社会状況として、就業先が見つからないということが、若者でも中年の方でも厳しいという状況がある中で、ハンディのある生活保護受給者や障害のある方がさらに厳しい状況にあるというふうに思いますけれども、区はこの辺をどのように認識されていらっしゃるでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"確かにいわゆる一般の方に比べまして、生保受給者ですとか、障害のお持ちの方は就職につくのが大変難しいということは認識しています。そちらにつきましては、区としましては、手厚い支援をしているです。","id":"exchange-121"},{"speaker":"井上委員","kind":"質問","question":"そこで、仕事というふうな形で就労だけにこだわるのではなくて、外に出ていく用事があるという生活を経験してもらうということが就業支援につながるというふうに思いますが、いかがでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"いわゆる中間就労みたいな形だと思いますけれども、そういった必要性もあるかとは思います。実際にＮＰＯ等でそういう活動をされている団体があるということは認識しています。","id":"exchange-122"},{"speaker":"井上委員","kind":"質問","question":"その中間就労というのが大変重要だというふうに思っています。こういった事業を生活保護受給者の方とか、障害者団体や障害をお持ちの方に委託するような仕組みを構築することができないかというふうに思いますが、いかがでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"そうしますと、私としましては、シルバー人材センターを支援している課ですので、そちらのほうの仕事が減ってしまうということもありますので、その辺も含めて検討したいというふうに考えております。","id":"exchange-123"},{"speaker":"井上委員","kind":"質問","question":"何か今の答弁を聞いていたら、自分たちの所管をするところを守りたいというような答弁に聞こえたのですけれども、私はどこということを問題にしているのではなくて、区が発注をする事業なのだから、区が判断をすることは十分にできるだろうと、そこで、就労機会のない、またそこの中間就労というところにそういう仕組みをつくったらどうですかというふうにお聞きしました。","respondent":"柏原行財政改革担当課長","answer":"例えば、障害者の部分であれば、現実に今、動いているところがあったりだとか、いろいろそういったものがありますので、その必要必要に応じて検討していくということが必要ではないかと思っています。","id":"exchange-124"},{"speaker":"井上委員","kind":"質問・要望","question":"外部発注には、専門的な知識、能力、あるいは量、動いてもらわなければいけないというところで、当然専門性が問われる事業については、おっしゃるとおり、検討していただくことはいいと思いますが、そういった部分で福祉の視点、それは福祉というよりも、普通に働く機会を平等につくるということは、当然区が行ってよいものというふうに思いますので。","respondent":"柏原行財政改革担当課長","answer":"そういったところの実際やっているところの動きであるとか、そういったところを踏まえながら、例えば、高齢者の部分についてはどういった形がいいのかという、そういう部門といいますか。","id":"exchange-125"},{"speaker":"井上委員","kind":"質問","question":"私は、障害者の方にお話を伺いましたら、車いすを利用される方で、ふれあい作業所とか、そういったところにはいらっしゃらない。そういった方たちは、大門まで就労支援のハローワークに行かなければいけないのですね。ですから、障害を持つ方が作業所に行かない人たちがどこに仕事を探しに行くのかと。検討していただくようにお願いをしたいというふうに思います。","respondent":"福島ものづくり・経営支援課長","answer":"財団として最低では３００万円が必要になりますので、それを出しました。今回、品川区としましても、事業を一緒に推進していくということもありますので、あるいは、品川区から補助をするということもありますので、今回、１,０００万円を出捐するというものです。","id":"exchange-126"},{"speaker":"井上委員","kind":"質問","question":"こういった出捐金というものを出すときに、根拠条例もしくは要綱があるというふうに思うのですが、その名称を教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"こちら、平成２５年度新規ですので、新たに要綱を定めていくよう検討しています。","id":"exchange-127"},{"speaker":"井上委員","kind":"質問","question":"今はまだ要綱が定められていない、そのときにこういう、この款で言うと、１,０００万円はすごい大きな金額だというふうに思いますけれども、もうそういうものが想定されてあって、本来、予算書に載るのかというふうに、まだ決定はないにしても、当然あると思うのですけれども、その辺の仮称であっても構いませんので、どういうものなのか教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"実行されますのが４月１日付になりますので、そこに向けて、今、検討をしています。","id":"exchange-128"},{"speaker":"高橋委員","kind":"質問・要望","question":"２５７ページのすくすく赤ちゃん訪問事業について、他の委員からもありましたけれども、何点かお伺いしたいと思います。この事業について、私の認識がちょっとこんなのではないかと思うので、間違っていたらご指摘いただきたいと思います。１００％にもし満たないとすると、その理由はどんなことでありましょうか。留守の場合は、どれぐらい訪問されるのでしょうか。よろしくお願いします。","respondent":"坂上品川保健センター所長","answer":"そういう方に関しては、こちらのほうからもう一度お電話させていただき、それでも訪問が必要ないという方には、子育て支援課のほうにご相談させていただいて、そこから児童センターの方が民生委員の方と訪問されたりというふうになっております。","id":"exchange-129"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、来ないでくださいという方に関しては、違った方法があり、訪問していいですよという方の場合は、何度か行っても留守の場合があっても、それでも最終的には訪問されるという認識でよろしいですか。","respondent":"坂上品川保健センター所長","answer":"そこでもコンタクトがとれないというか、未受診者の方に関しては、先ほども言いましたけれども、子育て支援課のほうに連絡票ということで連絡しております。","id":"exchange-130"},{"speaker":"高橋委員","kind":"質問","question":"この数字について、妥当とお考えになるのか、この事業は大変重要なものだと私は思っています。平成２３年度の決算でも、こういった相談の中で虐待、疑いですけれども１１件ということが出ているということもあるので、１００％の訪問を、いろいろ大変なことはあると思いますが、目指していく必要があると思います。最初からこの８２％というのは、どのような状況なのでしょうか、ご所見を伺います。","respondent":"坂上品川保健センター所長","answer":"１００％を目指すのですが、里帰りやお子さんが入院されているという状況もありまして、必ずしも、その数字には届かないというのが私どもの認識です。","id":"exchange-131"},{"speaker":"高橋委員","kind":"質問","question":"ですから、産まれたお子さんに対して訪問されて最終的に７５.４％になってしまうわけですよね。それをフォローするためにいろいろな策を講じていただいて、４カ月健診でもという話がある。でも、４カ月健診については、１００％のところもありますけれども、１００％に満たないところもありますよね。品川区の乳児ほぼ全員に配られるのですから、かなりの額になるのではないかと思います。","respondent":"坂上品川保健センター所長、安井子育て支援課長","answer":"保健センターにおきましてブックスタートは、４カ月健診にいらっしゃった方全員にお渡ししております。児童センターはブックスタートパックということで、これは一つのセットになっているものなので、それに袋ごとお渡しするという形態で、持ち運びに関して、非常に助産師とか、結構重いというふうに言われておりまして。","id":"exchange-132"},{"speaker":"高橋委員","kind":"質問・要望","question":"ですから、事業自体すばらしいものなので、つまり、その趣旨を保護者の方、お子さんに、４カ月健診で渡しているとすれば、そこで受けとり方なのかもしれませんけれども、これはこういう状況で本来はお渡しするものですがというような形だと思うのです。ですから、最初の志は高かったのですが、月日がたつと、絵本をもしかしたら配るだけになっているかもしれません。","respondent":"坂上品川保健センター所長","answer":"今、委員のご指摘ありましたように、きちんと説明してお渡ししたいと考えています。今後、気をつけていきたいと考えています。","id":"exchange-133"},{"speaker":"高橋委員","kind":"質問・要望","question":"２５７ページ、健康センターの運営、先ほど、ほかの委員からもありましたが、指定管理者の運営委託で、運営の形態についてお尋ねをするので、利用料収入のところで款が歳入になってしまうのですけれども、もし問題があれば言っていただきたいと思います。インセンティブという考え方だと思いますが。","respondent":"江部健康課長","answer":"これは５年間の指定管理を決める当初から、一定額と申しますのは、１億５,４５０万１,０００円という額、これが努力目標の基準値で、それを超えた場合、例えば２,０００万円超えましたといった場合は、区が２０％、指定事業者側が８０％取り分になるです。","id":"exchange-134"},{"speaker":"高橋委員","kind":"確認","question":"そうすると、この４５６万円だと、その５倍ですから、２,０００万円ぐらいの超えた金額になるのですか。ということは、２対８で分配をするということの確認でよろしいですか。時間がないので、確認だけします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、２５５ページの猫の不妊・去勢手術費助成で、主に地域猫のほうだけについて伺いたいと思います。本会議でも取り上げさせていただきましたが、この予算書で６７０頭のうち、地域猫のほうは４８０頭というふうに聞いておりますが、平成２４年度、今年度が予算が３３０頭だったと思いますけれども、現在までの実績をまず教えていただきたいと思います。","respondent":"工藤生活衛生課長","answer":"地域猫の助成に関するお尋ねです。今年度の実績ですけれども、２月末日現在ということでお話しますと、飼い主のいない猫、トータルで４４６頭の助成をやっているところです。","id":"exchange-136"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、予算が３３０頭だったのですが、飼い主がいるほうの猫からの予算の流用でやっていらっしゃるということでよろしいかどうかということと、それから、飼い主がいるほうの猫については、平成４年から獣医師会のご協力を得て、獣医師会のほうからも助成が出てやっておりますけれども、この地域猫のほうは平成１７年からやっておりますが。","respondent":"工藤生活衛生課長","answer":"獣医師会とのかかわりですけれども、委員ご指摘のように、平成４年度から飼い猫に関しましては、獣医師会と委託契約ということで、不妊・去勢手術をお願いしていますが、飼い主のいない猫、平成１７年度から、こちらのほうの制度におきましては、獣医師会といいますよりも。","id":"exchange-137"},{"speaker":"武内委員","kind":"質問","question":"２万５,０００円から３万円ぐらい。中には、区内でも、これは獣医師会に入っていないところで、比較的安い値段でやってくれる方もいれば、まちまちだということで、それから、区外に行けば、ほとんど助成金と同じぐらいの金額でやっていただけるところがあるということで、区の助成は当てにせずにそっちに連れていってやっている方もいるという中で、区内でなければいけないという理由は何なのでしょうか。","respondent":"工藤生活衛生課長","answer":"そういった意味では、区内の事業者と指定するという部分は適切なことだというふうに思っているところです。","id":"exchange-138"},{"speaker":"武内委員","kind":"質問","question":"本当に地域の区内の事業者の方ということで、いろいろな形で、その意味はよくわかるのです。ただ、実際に区内の獣医師の方たちが、この地域猫の活動について、本当にご理解の理解度がまちまちだと思います。どういうご理解をいただいているというふうに、認識はどうなのですか。","respondent":"工藤生活衛生課長","answer":"区内獣医師会の皆様とは、毎年年度の初めに、私どもの事業につきましてのご説明等をしまして、情報交換をしています。そういった意味では、私どもの猫に対する不妊・去勢手術の助成につきましても、一定のご理解をいただいているところです。","id":"exchange-139"},{"speaker":"武内委員","kind":"質問・要望","question":"そういう中で苦労している中で、やはり負担というのが非常に大変だという中で、区も助成を出しているのであれば、効率的な助成で猫の数を減らしていくというのであれば、安い手術費用というところを目指していかなければ、あとは助成金を上げるということになってしまうと思うので、そこをどう考えていくかという中で、今後そういう獣医師会の方たちの協力とか。","respondent":"工藤生活衛生課長","answer":"私ども、やはり品川区と獣医師会の協働の一つとして、この事業は一定の意味があるというふうに考えておるところです。今後は、いろいろと実態としまして、やはり獣医師会の加盟していない動物病院、いわゆる手術料が若干安くなっているところがあります。","id":"exchange-140"},{"speaker":"須藤委員","kind":"質問","question":"２８７ページの品川ビジネスクラブ事業運営補助で、先ほど質問して、ＮＰＯ法人化するので出捐金１,０００万円というような話が出ておりましたけれども、その後、要綱というか、どういう目的で、今まで一般社団法人だったものをＮＰＯにしていこうというのかどうか、そのあたりで、今度はＮＰＯになってくると、理事長だとか、専務理事とか。","respondent":"福島ものづくり・経営支援課長","answer":"品川ビジネスクラブの今後ですけれども、品川周辺にさまざまな技術を持った企業がありますので、そういった方々の情報を収集、または発信しながら、さまざまな事業展開を行っていきたいというふうに考えている次第です。","id":"exchange-141"},{"speaker":"須藤委員","kind":"質問","question":"失礼しました。そうすると、法人になってきたら、それなりにしっかりした組織という形で、行政としても１,０００万円という数字を出しているわけなので、区から職員とか、そういう出向みたいな形ではだれか行くような仕組みをつくっているのでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"職員につきましては、特に出向というのは今のところは考えてはいませんけれども、今後そういったことも必要ではないかというようなことはあるのではないかと思います。","id":"exchange-142"},{"speaker":"須藤委員","kind":"質問","question":"東京都もいろいろ禁煙だ云々だと言っておりますけれども、５位から１２位に落っこちてしまったというような数字が出ているので、私も喫煙率のこの健康の相関関係を見てみたのだけれども、あんまり喫煙率と平均寿命とは相関関係がそんなにないと思いますけれども、そのあたりの関係と、それから同じように見てきていると、健診の受診率と、この平均寿命の相関関係があるかと思っていると。","respondent":"矢野品川区保健所長","answer":"受診率に関しましては、ちょっと受診率そのものが低いという部分もありますので、まだちょっと相関は、もうちょっと短いスパンで結果は出るのですが、全体的に低いというところなので、まだ相関が出ていないのではないかと考えております。","id":"exchange-143"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、今度、２５７ページの食からの子育て支援事業、２５９ページ、食育推進事業というものに関連してきますけれども、こういった、今お話したような四つの県が男女ともそういう数値を上げているよと、１０位以内に入っているよというのは、何かしらそこにあるものが成果の中に取り入れられているから、そういう結果があるのではないかと思っているのですけれども、この辺の食からの子育て支援事業。","respondent":"坂上品川保健センター所長","answer":"そのほかに保健センターといたしましては、特定給食施設の管理講習会ということで、昨年１１月には減塩についての講演会を、給食施設と、あと弁当惣菜店、昼食業者になりますが、そこに対して行いました。","id":"exchange-144"},{"speaker":"須藤委員","kind":"質問","question":"この食からの子育て支援事業もそうだし、食育推進事業も、我々区民のためにどういう食事であれば、どういう食生活、あるいは生活習慣でもいいと思いますけれども、そういうことをやることによって、健康な形で、いわゆる健康寿命を持っていけるよというような形に運んでいく必要があると思うのだけれども、そのあたりはどうでしょうか。","respondent":"坂上品川保健センター所長","answer":"食育に関しては、食育庁内連携会議というものをもたせていただいております。","id":"exchange-145"},{"speaker":"須藤委員","kind":"意見","question":"今、食についても、肥満の人が高脂肪の食をとっていると、脳の刺激が、受容体がなかなか満足しなくなってきてしまうとか、いろいろな研究がなされているので、そういうことを参考にしながら、区民のための健康増進というか、そういうものを図っていっていただければと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-146"},{"speaker":"南委員","kind":"質問・要望","question":"２６５ページの環境保全事業について伺います。２年前に起こった福島第一原発事故によって大量の放射性物質が放出されて、その影響は今でも続いています。子どもを内部被曝から守ることがとりわけ求められており、区は事業展開をしていますが、私はセシウムゼロを目指す立場で取り組むべきだと思いますが、区の認識を伺いたいと思います。","respondent":"野呂瀬環境課長","answer":"それは先ほど申したとおり、毎週毎週はかっているというのを区民の皆様にお伝えしながら、現在はそういう状況ですという状況はお伝えする、これは区の立場でそういうことをやっている。セシウムゼロを目指す云々につきましては、私からの答弁は控えします。","id":"exchange-147"},{"speaker":"南委員","kind":"質問","question":"今、品川の子どもを育てているお父さんやお母さんをはじめ、全国的にですけれども、子どもの内部被曝からどうやって守るかというところが、子育てについての最大の関心事の一つだというふうに思うのですよね。そういう点で見たときに、やはり今のような見解では非常に残念だというふうに思うのです。そういう事業をしておきながら、今のような見解でいいのでしょうか。もう一度伺いたいと思います。","respondent":"野呂瀬環境課長","answer":"それがここのところ６カ月ぐらいは、もう本当に１０件行かないかどうか、月々１０件行かないかどうかの貸出状況、これにつきましては、やはり心配だとして測っていらっしゃる方はそのまま継続して測っていらっしゃるのでしょうけれども、ほとんどの方は。","id":"exchange-148"},{"speaker":"南委員","kind":"質問・要望","question":"保育園給食に供している牛乳がありますけれども、数社あるそうですが、ここの中の１社がセシウムを検出しているという情報が去年度からずっと入って、それは社会的にもクローズアップされておりますけれども、その点について知っているかどうかと、それから、その対策をどうしているか、それについて伺いたいと思います。","respondent":"野呂瀬環境課長、立川保育課長","answer":"前段の何で少なくなっているかのご質問ですけれども、これは心配する放射線量ではないということをほとんどの区民の方がそういうふうに認識しているからだと思います。実際に最近の検出ですけれども、最近は、その５０分の１ぐらいのぎりぎりのところです、検出下限値のほんのちょっと上のところという水準まで実際の放射線量というのは落ちてきているというふうに認識しております。","id":"exchange-149"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、基準値が低いから、精密な機械で測っているから大丈夫だということにはならないというふうに思うのです。これについても見解があれば伺わせてください。それに当たって、まず４カ所に設置されたというこの間のご質問で明らかになったのですが、平成２４年度に八潮にも設置されるということであったのですが、八潮も含んでの４カ所ということでいいのかどうか、ちょっと確認をしたいと思います。","respondent":"江部健康課長、野呂瀬環境課長","answer":"認定者数の話、ちょっと前後して済みません。現在、２,５００名が認定されておりまして、すべてぜんそくということで２,５００人です。新規につきましては、３４７人、今年度の新規認定です。ですから、１日あたりの上下をどういうふうにするというのは、これは東京都のほうに、これから進めていくことだというふうに考えています。","id":"exchange-150"},{"speaker":"南委員","kind":"質問","question":"３カ所の測定器を、放射能の測定ができるような測定器の場所を少なくとも３カ所にしてほしいという、食材の測定ができるようにという、そこについての答弁をさっきお願いしたのですが、ぜひお願いします。したがって、こういう状況をしっかり調査して名乗りを上げて、測定できるように、測定局を品川区独自のものとしてつくるようにお願いしたいということと、先ほどの食材の測定の件についてお願いします。","respondent":"野呂瀬環境課長","answer":"食材につきましては、今現在、もう安全な値が出ているということで、今後進めていきたいと思います。それから、ＰＭ２.５につきましても、今後の東京都の動向、これを見ながら区民の皆様に正確な情報の周知を図っていきたい、このように考えているところです。","id":"exchange-151"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"よろしくお願いします。私からは、２７９ページ、就業支援費について、それと、２５７ページの赤ちゃんの健診に関連しての質問と、２５１ページ、感染症対策費、ＨＩＶ検査についてお伺いします。初めに、就業支援ですが、この就業支援の予算の中で、都の支出金が８,８００円余あると思いますが、どのようなものにつけられているのか、お聞かせいただきたいと思います。","respondent":"福島ものづくり・経営支援課長、坂上品川保健センター所長、安井子育て支援課長、伊津野保健予防課長","answer":"ＰＲですけれども、今、事業者を募集していますけれども、事業者の中では、全世帯へポスティングして周知を図るですとか。その後は、子育て支援課と連携してという形になります。周辺の近隣の家のほうから、子どもがいるようなことはありませんかというようなことで。場所につきましては、ちょっと経費の関係もありますので、なかなかお金をかけての場所を設定するのは難しいと思いますので。","id":"exchange-152"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ちょっと時間がないので、宮古市、富岡町への支援、これは被災地支援にもなると思いますので、区としてどうこうではなくて、そういったメニューをぜひ取り入れて、宮古市、富岡町とも相談をしながら、できたらそういったメニューも取り入れていただければと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"私は、２８１ページ、商店街活性化事業費についてお聞きしたいと思います。先ほど、課長から、商店、個店について、町にとって生活インフラとして欠かせないものだという説明がありました。これについて、どういうふうにお考えなのか。効果が弱いならば、活性化事業の見直しも必要ではないかと思うのですが、お聞かせください。","respondent":"米田商業・観光課長","answer":"そういった意味で、区といたしましては、厳しい環境に置かれておりますが、少しでも商店街の活性化に結びつくようなというようなことでの支援を継続しているものです。","id":"exchange-154"},{"speaker":"須貝委員","kind":"提案","question":"私はプレミアム商品券というよりは、ちょっとこれは提案ですが、区内の全世帯に１世帯当たり５００円分でもいいから、商品券を無料で配布したらどうですか。ほかの施策は削っても、直にお客さんが、区民が直接買いに行けるということをやらなければ、いくら商店街振興をやっても、それは人は一過性ですから、通ることはある、その商店街のいろいろな活性化に対して、その事業に対して、皆さん、行きますよ。","respondent":"米田商業・観光課長","answer":"いろいろご提案をいただきましたが、品川区といたしましては、今ある施策を継続して、見直すところは見直しというようなことで、プレミアム商品券も一つの活性化の施策として、来年度も行っていくというようなことで考えてありますので。","id":"exchange-155"},{"speaker":"須貝委員","kind":"質問","question":"でも、どうですか、商店。どんどん活性化しているのですか。違うでしょう。そういうことは真摯に受けとめなければいけないのではないですか。でも、大半の方にとっては関係ないですよね。やはりその方がお金を、皆さん今、所得が、収入が少ないのだから、少しでも還元して、そうしたら、５００円でも３００円でももらえば、ちょっと近くの店へ行ってみようかという気に、私は当然なると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-156"},{"speaker":"若林委員","kind":"質問・要望","question":"３点。そこで、検診を受けられる医療機関の数は今どういうふうになっているのかというのを確認させてください。３点目は、２５７ページの健やか親子学習などに関連して、栄養士のお仕事のご様子を伺っておきたいと思います。そこで、栄養士の仕事ぶりというのですか、また、区民にとって栄養士というのはどういう存在であるのか、こういうことをお聞きしておきたいと思います。","respondent":"福島ものづくり・経営支援課長、江部健康課長、川島大井保健センター所長","answer":"そういった資金面も含めて支援をしていきたいというふうに考えております。胃がんリスク検診についてのお尋ねで、１点目の実施機関の数は、区全体で１５７カ所です。保健センターにおける栄養士の活動について説明します。","id":"exchange-157"},{"speaker":"若林委員","kind":"質問・要望","question":"ですから、経営改善というのは融資をして終わりということでは当然なくて、逆に融資を受けた側が、そこからどう資金繰りも含めて立ち直っていくかということが大事ですので、そこら辺を流れを、融資後のもっと実績を上げるということについてご答弁をいただきたいと思います。胃がん検診のリスク検診のほうは、せっかくの保険適用がなされました。","respondent":"福島ものづくり・経営支援課長、江部健康課長","answer":"いわゆる円滑化法の終了も伴いまして、今後、さまざまな形で相談事業、あるいは経営支援が必要になろうかと思います。さまざまな形でＰＲしまして、そういった支援ができるような仕組みをつくっていきたいというふうに考えております。区としては、もっとわかりやすい受けてみたいと思わせるようなＰＲを区としてやってほしいという意見を逆に言われております。","id":"exchange-158"},{"speaker":"大沢委員","kind":"質問","question":"それと２８５ページのベトナム調査団です。最初に、ベトナム調査団についてお伺いいたしますけれども、７月から２月の間にこの調査団を組んでということで、概要には書いてありまして、タイでもありました。これは、どのような、成果物を上げて、例えば、調査に当たっての方針とか指針とかありましたら教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"そうした中で品川区内の中小企業が進出あるいは販路拡大を検討するに当たっての必要となる投資環境ですとか、そういったことの情報収集および最新の市場調査を、短時間ではありますけれども、効率的にできるように実施していきたいというふうに考えておるものです。","id":"exchange-159"},{"speaker":"大沢委員","kind":"質問","question":"今のご答弁で、短時間に効率的なと、これは非常に、どうなのでしょうか、短時間に効率的なと、よほどタイトなあれだと思ったら、そこまで短時間に効率的に、どこまでできるのか、ちょっと私は、優秀な方たちのお集まりで行かれるだろうからできるとは思いますけれども、短時間に効率的に行うというのは、どういうふうに行っていくのか教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"さらには、事前の学習といいますか、セミナー等も開きまして、事前に十分準備した上で向こうのほうへ訪問する、調査していくということを考えているものです。","id":"exchange-160"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、タイにビジネスセンターができました。ここらあたりは、まさにインドと中国、日本、韓国、こちらの国々に挟まれた重要なところで、車の車種によってはピックアップトラックみたいに税金の免除が受けられるという恩恵がある。そして、ベトナムにはジェトロの現地の事務所があるのかどうか教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"同じような形で、ベトナムでもそういうことができるのかもしれないということもありまして、今回、調査してまいりたいと思います。ジェトロにつきましては、ホーチミン市内に支援の施設、事務所があったというふうに記憶しております。","id":"exchange-161"},{"speaker":"大沢委員","kind":"質問・要望","question":"次に、２８３ページの空き店舗活用支援事業ですけれども、今、空き店舗、何が入るか、企業化されたある程度資本力のあるところが入る。とりわけフランチャイズチェーンなり、コンビニが入ってまいりますけれども、コンビニもフランチャイズチェーンに入りますけれども、ここの社会的な役割、要は、地域度というのはどのように考えていらっしゃるのか教えていただきたいです。","respondent":"米田商業・観光課長","answer":"そういう中で、チェーン店ではありますが、地域への貢献というものを商店街なりに加盟したり、あるいは地元での催し物に参加していただいたり、手伝ったりしていただくようなことで、地域に溶け込んでいただくということがある種重要なのだろうというふうに考えてあります。","id":"exchange-162"},{"speaker":"大沢委員","kind":"質問","question":"今、二つばかりフランチャイズチェーンの地域度ということを教えていただきました。ここのところをもう１回どういうふうに具体的に考えていかれるのか、それとも考えないでいたしたいと思うので終わってしまうのか、そこのところを。","respondent":"米田商業・観光課長","answer":"商店街のほうも、そういった役割を果たしていただけるチェーン店なり、歓迎して仲間で一緒にやっていっているという例も多数あろうかと思います。そういうようなことを見本に、今後とも横のつながりを深めていければというふうには考えてはあります。","id":"exchange-163"},{"speaker":"大沢委員","kind":"質問","question":"何が言いたかったか、ＣＳＲ、企業の社会的使命があるわけで、そこのところをどういうふうに、これは行政が仕掛けていかないと、なかなかまとまるものではない。収納率はやっていました。税金の収納率もやって、現に社会的なそこの一つの部分でも、収納の事務もやっているので上がってくると思いますけれども、そこのあたり、仕掛けることができないのですか。ちょっと教えてください。","respondent":"米田商業・観光課長","answer":"区といたしましては、いわゆる空き店舗対策事業等で、また別な観点からの年に１件、２件という数ではありますけれども、そういうような対応をしていく中で、また新たな構成員を増やしていく、商店街にない業態を増やしていくなり。","id":"exchange-164"},{"speaker":"大沢委員","kind":"質問","question":"職員の方たちも新聞等々で読めばおわかりのように、地域カードをやったり、電子マネーの間に入ったり、地域としての一つの役割ということで、コンビニないしチェーン店が入ってきているわけですから、そこのところの空き店舗対策という１点ではなくて、社会資源として捉えていただきながら、仕掛けられるところは行政が仕掛けていかないとまとまらないと思うので。","respondent":"福島ものづくり・経営支援課長","answer":"品川区の融資あっせんですけれども、今回、条例提案させていただきましたように、限度額を５００万円上げていく、そういうことも含めまして、より利用しやすいものをというふうに考えてあります。","id":"exchange-165"},{"speaker":"大沢委員","kind":"質問","question":"長計とか、区長のいろいろな資料に書いてある、品川区は中小企業のまちです、どうなのでしょうかね、これ。中小企業、商業、工業のまちだというふうに私たちは思っていますけれども、ただただこの６２ページの数字を見る限り、そこのところが十分に行き届いているのかという、ちょっと自分自身の考え、何かそれは覚えるのですけれども、そこのところはどのようにお考えになりますでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"そういった中で、銀行あるいは金融機関と連携をとりながら、融資あっせんは拡大しながら継続するよう検討してまいりたいと思います。","id":"exchange-166"},{"speaker":"大沢委員","kind":"質問","question":"これについては、いいとか悪いとか、十分品川区の事業の力の入れ方は十分感じていながらの話なので、いいとか悪いとかは論じません。ただ、ここの数字だけ見た場合に、この数字はどうなのですかというお話でお尋ねをさせていただきましたので、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-167"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/167818?Template=document&Id=990#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":125890,"voices":402}},{"id":"h25-20130312-3","meetingId":"h25-c-budget","date":"2013年3月12日","dateIso":"2013-03-12","committee":"予算特別委員会","time":"午前１０時００分～午後５時５２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を160件抜き出しています。","topics":[{"id":"topic-01","title":"平成２５年度品川区一般会計予算","agenda":"平成２５年度品川区一般会計予算","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"私は２９３ページ、２９５ページの街路灯の電気料についてお伺いします。それから、３１１ページのしながわ水族館運営費、３１３ページの子ども達のアイディアを活かした公園整備についてお伺いさせていただきたいと思います。前後しますけれども、まず３１１ページのしながわ水族館運営費についてお伺いさせていただきたいと思います。","respondent":"多並公園課長","answer":"その状況を踏まえまして、今年度につきましては、平成２４年度末で４２万８,０００人余の入館者と現時点では見込んです。この入館者につきましては、今までの傾向からしましてはもちろんかなり大幅な減だったという認識があります。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"さまざまな工夫をされておりまして、年間パスポートですとか、特に法人の方の法人サポーターということをやられたり、そういったことをやることによって、１社３年間で３０万円ということですけれども、既に８２社の会社が集まっているということです。こういった検討中であるとは思いますけれども、その辺のところのお考えというか、これからのお考えについてお伺いさせていただきたいと思います。","respondent":"多並公園課長","answer":"このしながわ水族館は、平成３年にオープンいたしまして、その当時、その運営方式について検討して、その当時も、今のような設置管理許可、都市公園法のやり方と、もう一つは、今の委員のご案内のあったような、土地を民間に貸して。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"２９３ページの街路灯の電気料のことでお伺いしたいんですけれども、平成２４年は、電気代が９,５００万円ということでした。これは東電のほうの値上げによるものかと思うんですけれども、そのあたりの、電気代が今後このように上がったことに対しての認識というか、節電というか、その辺のところはどのようにお考えでしょうか。","respondent":"稲田道路課長","answer":"これは年間約４００本、５００本を建て替えを進めておりまして、これは水銀灯よりも、消費電力、要するに定額料金なんですけれども、料金は安いというところで、それに現在進めている、建て替えを進めているという状況です。","id":"exchange-003"},{"speaker":"沢田委員","kind":"意見","question":"平成２４年は１７灯が平成２５年１９灯ということで、２灯しか増えていないということありますけれども、これ、場所によっては使える場所もあるという話だったかと思うんですが、また技術の進歩によってまたそういったことも今後考えていくという話だったと思うんですけれども、やはり３,０００万円も電気代が上がったというのはかなりの負担増ということだと思うんですが。","respondent":"稲田道路課長","answer":"その内容なんですけれども、やはり価格は大分下がってはきています。技術も大分進んではきているんですけれども、価格はまだ、省エネ型街路灯、私どもが進めています省エネ型街路灯のほうがまだ安いと。長期的な２０年スパンで考えますと、まだ安い。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"ぜひとも今後ともＬＥＤのほう、今後技術の進歩もあると思いますが、検討していっていただきたいと思います。それとあと、ちょっと時間がないんですけれども、３１３ページの子どもたちのアイディアを活かした公園整備についてお伺いさせていただきたいと思います。その中で、今回、この３つ目の子どものアイディアを活かした公園ということですけれども、今回も前回同様にそういった形でやっていくのかと。","respondent":"多並公園課長","answer":"これを今までの公園の中で、いろいろなバランスを見たり、またこの公園の中での特徴等を捉えながら、遊具については選定してまいりたい、そういうように考えてあります。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"ここ、もともと交通公園といって、ここでも私、昔小さいころよく遊んでいたんですが、ＳＬとか、船とか、いろいろ置いてあるんですが、こういったものは完全になくなるのかなということと、あと、ちょっとあれになっちゃうんですか、テニスコートが今回改修に入らなかった、この辺の理由とですね、あれば教えていただきたいと思います。","respondent":"多並公園課長","answer":"テニスコートはクレーコートということで、利用としてはまだ可能かなということで厳重に見ています。ＳＬ等も、設計の中で、全体的には今後、今の状況等も勘案しながら整備を考えていきたい。そのように整備したいと考えています。","id":"exchange-006"},{"speaker":"阿久津委員","kind":"質問","question":"私からは２９９ページ、道路バリアフリー事業、３１３ページ、子どもたちのアイディアを活かした公園整備、時間があれば、３１７ページ、品川駅南地域周辺まちづくり事業についてお伺いをいたします。お伺いをしたいのは、品川区の区有施設、また区関連施設での、もしおわかりであればなんですが、昨年の転倒事故の件数、また事故の状況等、簡単に教えてください。","respondent":"平澤経理課長","answer":"昨年度ですが、１件ですね、お１人、雨の日だったと思いますが、転ばれてけがをしたということがございました。","id":"exchange-007"},{"speaker":"阿久津委員","kind":"質問","question":"１件、把握をされているということでございました。それによりますと、平成２２年には７,５００人を超える方が転倒、転落でお亡くなりになっております。これは、交通事故死される方が大体７,０００人台ですので、ほぼ同じ数ということで、この数は年々増加傾向にあります。推奨値を示しました。品川区ではこのあたりをどの程度押さえられていらっしゃいますでしょうか。","respondent":"平澤経理課長、稲田道路課長","answer":"その辺を含めまして、対症的な方法ではありますが、例えば雨の日等につきましては、モップでふき取りの作業をするなど、そういった事故がないように努めているところです。建築物の滑りとはまた違うんですけれども、道路のほうでもすべり抵抗値の基準がございまして、濡れた状態で、たしか５５以上だったと思うんですけれども、そういう抵抗値の基準があります。","id":"exchange-008"},{"speaker":"阿久津委員","kind":"質問・要望","question":"建物の中の床の滑りと、また道路の滑りというところで、今回国のほうで言っているのは床の滑りのほうということなんですけれども、品川区においても、特に区有の施設、また区関連の施設、特に高齢者の施設ですね、あとは福祉施設、障害者の福祉施設、こういうことについても多くの方が利用されますので、推奨値ですから、努力義務ということだとは思うんですけれども。","respondent":"山崎マスタープラン担当課長","answer":"今回、区としましては、１つ、モデル地域的に大井町のエリアをそうした重点エリアにしまして、必要な道路の構造の基準に合致しているか、あるいは、建物のバリアフリーの構造に合致しているか、こうしたところを含めまして、面的整備の推進を図ってまいると。","id":"exchange-009"},{"speaker":"阿久津委員","kind":"質問・要望","question":"公園づくりのワークショップでアイディアを取り入れた３番目の公園ということで、先ほどありましたけれども、まず１点目にお伺いしたいのが、地域の方、先ほどありました交通公園という呼び名を使っているんですが、信号機とか道路コースが設置をされています。それを使っているというのは私自身余り見たことないんですけれども、まず交通公園という定義はまだこの公園には存在しているんでしょうか。","respondent":"多並公園課長","answer":"中の施設といたしましては、園路、いわゆる道路の形状をした園路、また信号機や交通標識等を備えていることがその中の１つの定義になっていまして、そういった意味では、東品川公園につきましても、交通公園の具体的な施設については備えた形となっている公園です。","id":"exchange-010"},{"speaker":"阿久津委員","kind":"質問","question":"そういったご意見を反映していただくことは可能なんでしょうか。あの公園は、毎朝、たくさんの方が、６時からですか、６時半からですか、ラジオ体操をやっているんですね。その方たちからも実はいろんなご意見をいただいています。こういった地域の方のご意見、こういったものも反映していただけるんでしょうか。","respondent":"多並公園課長","answer":"東品川公園につきましては、来年度、基本設計、実施設計、行ってまいります。","id":"exchange-011"},{"speaker":"阿久津委員","kind":"質問・要望","question":"最後にですけれども、ちょっと若干余談めいた話になるんですけれども、シンボリックな公園ということで、公園というのは本当に地域のランドマークというか、そういった形になるということで、近くの神明公園ですか、たこ公園、あそこも非常に皆様から愛されて、大きなたこがなくなるときはお別れの会をやったり、小さなたこができたときは、それを祝う会をやったりということで、実はこのたこの滑り台。","respondent":"溝口都市開発課長","answer":"重点地区なんですけれども、今のところ想定されるのは、やはり品川駅に近接しております北品川駅周辺、そういったところを重点地区に選定するとともに、そういった中でどのようなまちづくりが具体的に行えるのか。","id":"exchange-012"},{"speaker":"阿久津委員","kind":"質問・要望","question":"昨年地域のほうからもこういったまちづくりをしてほしいという要望が出され、それに対して区のほうも回答していく。まあ、キャッチボールをしながらだと思うんですけれども。それなりに便利で格好いい街並みがつくれてしまう。ですから、そういったところで、品川の再開発計画、これは練りに練っていただいて、ベストプランで臨んでいっていただきたいと思いますが、その辺についてご見解を伺います。","respondent":"溝口都市開発課長","answer":"品川駅南地域のまちづくりにつきましては、当然旧東海道の品川地区、また品川浦に代表される水辺空間、そういったものが地域の特徴としてありますので、そういったものを生かしながらまちづくりが進められるようなまちづくりの計画をつくっていきたいと考えているものです。","id":"exchange-013"},{"speaker":"阿久津委員","kind":"質問","question":"まあ、１人の方の主観ですから、何とも言えないんですが、私自身がやはり港南口とか汐留のほうに行って同じような印象を受けるものですから、ぜひそういったこと、これはゆっくり構えていてはだめなのかもしれませんが、国、また鉄道業者、そして都の動向をしっかりとらまえていただいて、ぜひしっかりとしたまちづくりをお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"２９７ページ、補助１６３号線整備、３０９ページ、マスタープラン、３１１ページ、公園整備、３２７ページ、区民住宅でお伺いしますが、まず１６３号線なんですけれども、昨年３月にきれいに抜けて非常に便利になりました。そこから中心部に向かって溝があるんですよ。それと、区民住宅なんですけれども、これ、滞納使用料と長期滞納者対応経費と出ていますけれども、この２つの違いについてお伺いします。","respondent":"稲田道路課長、山崎マスタープラン担当課長、多並公園課長、武藤河川下水道課長、大串住宅担当課長","answer":"１６３号線、昨年度末に一本橋区間開通しまして、しばらくの間、これはちょっと工事とは違うんですけれども、区役所の前の渋滞がありました。長期的な視点から健全なまちづくりを実施していくためには、今回、マスタープランのほうで、まちづくり各分野、７分野です。それにつきましては、我々区のほうで整備する際には、適切に排水計画をして埋める形で整備してまいる、そのように考えているところです。私からは西大井四丁目付近の下水道工事の件についてお答えいたします。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"じゃあ、橋桁の件について、お願いしたいんですけれども、課長、もしですけれども、東京都に帰られてしまうかもしれないんじゃないかという思いがあるんですけれども、それでもここはきっちりやっていただいて、東京都にお戻りになってもちゃんとやっていただきたいと考えています。","respondent":"武藤河川下水道課長","answer":"まだ内示をいただいておりませんので、個人的なコメントは控えしますが、本工事につきましては、下水道局も、当然我々品川区も、非常に重要な工事、浸水被害を解消するには大事だと認識しておりますので。","id":"exchange-016"},{"speaker":"木村委員","kind":"意見","question":"街路灯の中には、蛍光灯、そして水銀灯がほとんどです。この中にＬＥＤが１９灯あるということですけれども、どんなところにＬＥＤを使っているのか、お答えください。","respondent":"稲田道路課長","answer":"それを現在も点灯して、チェックしながら、動向を追跡調査しています。街路灯は１２灯、それとブリンカーライト、ＬＥＤ７灯というのがございまして、これは交通安全の交通島等についている黄色いランプのものです。","id":"exchange-017"},{"speaker":"木村委員","kind":"質問・要望","question":"本区は、今のところ、道路課長の今の答弁にありましたけれども、そういうことで、今のところかえる考えはないということでありますけれども、私たちから見れば、１億円もの経費削減ができるわけですから、ぜひそういう従来の方式ではなくて、ＬＥＤを導入していただきたいと思うんですけれども、まあ、ＬＥＤに欠点があるというわけではないということを先ほど言われました。","respondent":"稲田道路課長","answer":"途中ランプの交換等も省エネ型はあるんですけれども、その２０年スパンで検討しても、今のところ、私ども品川区が考えるには、１.４倍ほどまだＬＥＤのほうが高いという状況です。一番は、光の光源を見たときに、まぶしいんですね。","id":"exchange-018"},{"speaker":"木村委員","kind":"意見","question":"これから追跡調査をしながらということでありますけれども、今のところはそういう意味では考えはない。ですけれども、将来的に導入する可能性があるとすれば、追跡調査をしてという結果ですけれども、ＬＥＤのどこを追跡調査をしようとしているのか、そのお考えをお聞かせください。","respondent":"稲田道路課長","answer":"現状設置してあるＬＥＤの街路灯につきましては、光の落ちぐあいとか、そういうものが実際あるのかどうか、その辺も見ながらやっていきます。それとあとは、他区の状況ですね。","id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"まあ、私たちから考えれば、ＬＥＤは電球が長持ちをするということが私たちの観念というか、何ていうんですか、認識があるわけですけれども、普通のものよりも、この本区で使っている省エネ型、約３分の１ぐらいのキロワットということらしいですけれども、それよりも、私たちから見れば、ＬＥＤを使ったほうが安くなるのではないかということを思っておりました。もう一度再度お答えください。","respondent":"稲田道路課長","answer":"ということは、街路灯をつけるスパンが短くなるということで、個数等も増えてきますので、その辺は、その間隔と照明の明るさ、その辺も考える１つだというところでやっております。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"３０９ページの特定整備路線計画推進費について伺いたいと思います。最終補正で、特定整備路線沿道不燃化促進調査委託１,２００万円が計上されましたが、これとの違いが何なのか、改めて伺いたいと思います。それともう１点、２９号線について、芳水小学校の説明会では、３月から現況測量を始めると説明がありましたけれども、動いている様子が見えないんですけれども、現況がどうなのか伺いたいと思います。","respondent":"藤田都市計画課長","answer":"最終補正との違いですけれども、最終補正のほうでは、不燃化を進めていくための助成事業、こういった事業も考えているところですけれども、この辺について、どのように進めていくか、検討しているものです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"この道路計画には住民の理解が得られておりません。住民が反対する計画はごり押しすべきでないと思います。どういった計画を考えているのか。９月補正、最終補正、新年度予算のこれらの事業、住民説明会の日程がいつなのか、伺いたいと思います。あわせて２９号線沿道の用途地域、容積率の変更について、住民がどのようなまちを望んでいるのかのアンケート実施の有無や時期も伺います。","respondent":"品川防災整備担当課長","answer":"２９号線の沿道のまちづくりという件ですが、まず、これから木密地域不燃化１０年プロジェクトの中で、本格実施地区を決めていきながら、まちづくりを進めていく段階です。この沿道整備につきましては、そのあたりが決まりましてから進めていきたいと考えております。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"要するに沿道についても、もう決まったこと、ご理解をと、こういう説明会ではなくて、事業概要とともに、計画の是非、どんなまちがよいのか、区民の意見を聞く、こういう事業説明会をしっかり開くべきだと思いますが、日程を改めて伺いたいと思います。じゃあ、７年間でやろうと思ったら、乱暴な住民の追い出し。突破される延焼遮断帯が何の役に立つんだと私は思いますけれども、いかがでしょうか。","respondent":"品川防災整備担当課長","answer":"少し説明のほうをしたいと思うんですが、この道路については、当然２９号線、道路をつくるところについては、皆様に土地のほうをどいていただくような形になると思います。ただ、沿道のほうはあくまでも不燃化していこうというものです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"つまり、手法について、地区計画を使うのか、地区計画を定めず補助事業で不燃化建築物を誘導するのか、また、区の都市計画審議会を通さず、都の都市計画審議会決定で用途地域、容積率の変更をするのか、再開発による都市計画書を考えているのか、大体私、この４つぐらいしか思いつかないんですけれども、改めて手法が何なのか伺いたいと思います。","respondent":"品川防災整備担当課長、藤田都市計画課長","answer":"まだまだそこの段階まで現在いっていない状況ですし、道路のほうも、これ、今、住民説明会等、皆様に周知しまして、周辺の皆様もこれからどういうふうに自分たちがやっていこうかということを考えているような時期だと思います。一般の市町村では市町村が決めるというふうになってありますけれども、東京都の場合は都決定であるということで、東京都のほうで行うことになります。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"ということでは、２０２０年までには完成しないと、延焼遮断帯は完成しないんだと、そういう計画なのかということを改めて伺いたいと思います。あわせて伺いたいんですけれども、東京都はあと１年後に事業申請を目指しておりますけれども、この２９号線１本、３.５キロ、この距離で事業認可をとろうとしているのか。説明会は一応６カ所ということになっておりますけれども、その関係を伺いたいと思います。","respondent":"品川防災整備担当課長、藤田都市計画課長","answer":"再開発があるのか、ないのかというところは、先ほども説明しましたとおり、地域の方々の機運が高まっているとか、そういう部分があれば、区としても応援していくというような形になると考えております。その辺については今具体的に東京都のほうで検討しています。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"東京都は説明会で２０２０年に完成するという、延焼遮断帯を。でも、品川区は、いや、２０２０年には完成しないんだという。どっちが正しくて、どっちがうそをついているのか、改めて伺いたいと思います。２９号線について、防災対策だと言いますけれども、その根拠はありません。これでなぜ防災対策と言えるのか、改めて伺いたいと思います。","respondent":"品川防災整備担当課長","answer":"２０２０年までに、要するに道路をつくるだけで、まずこの２０メートルの道路をつくるだけで十分に延焼遮断帯になる。さらに、沿道を不燃化していくことでこの延焼遮断帯の効果が高まるですので、この辺のところをご理解いただければと思います。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は住民が反対をする２９号線計画はやめるべきだと思います。防災の根拠もありません。廃止を東京都に求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"渡部委員","kind":"質問・要望","question":"交通安全啓発費は、自転車のことでちょっとお話をさせていただきたいと思うんですが、わかれば教えてほしいんですけれども、品川区内の事故って、これも数云々じゃなくて、増えていますか、減っていますかという中で、その中で、自転車のかかわっている事故はどうでしょうか。自転車同士の事故とかがあるのか、ちょっとその辺、わかれば、概略で結構ですので、教えていただけますでしょうか。","respondent":"谷口交通安全担当課長","answer":"自転車事故の中に、やはり年代的に申しまして、２０代、３０代、４０代、やはり自転車を使う方、ふだん稼働する方たちの事故が多いと。中で、高齢者の方ですけれども、３９６件のうち、４９件、これが高齢者の事故になります。","id":"exchange-028"},{"speaker":"渡部委員","kind":"意見","question":"自転車単独のというか、自損的なものと、あと、自転車同士の、この２点の見解を。","respondent":"谷口交通安全担当課長","answer":"自転車単独ですけれども、ちょっと手持ち資料がないんですけれども、ちょっとお待ちください。単独だけだと全体の４件です。大変少ない数字です。自転車同士、これは全体のうちの３２件となっております。","id":"exchange-029"},{"speaker":"渡部委員","kind":"質問","question":"ちょっとお伺いしまして、普及啓発経費の中でさまざまな交通安全講習会とかなされている。子どもたちの交通安全というのは学校で頻繁にやっていまして、何度か見させていただきました。かなり見ていておっかないなと思うようなこともやっていました。これ、どのようにやっていけばいいですかね。品川区としては何かお考えありますでしょうか。","respondent":"谷口交通安全担当課長","answer":"これを年代を広げまして、２０代、３０代、４０代の方にもそのスタントマンのやるスケアードストレート等に参加していただきながら、事故防止対策を図っていきたいと考えているところです。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問・要望","question":"品川区だけの事業ではないと思うんですが、警察と協力して、そのような実証実験をして、また、成果をあらわして、交通安全に本腰を入れて、自転車の安全に取り組んでいるぞというようなのを見せていただきたいと思うんですが、何かそういうお考え、それがいいとかではなくて、何かお考えあれば教えてください。","respondent":"谷口交通安全担当課長","answer":"モデル地域とか、それも各警察署で決めながら、高齢者に対する横断歩行訓練だとか、事故防止対策、各警察署のほうで実施しておりますので、区のほうもタイアップしながら、高齢者の交通事故防止については対策を考えていきたいと考えております。","id":"exchange-031"},{"speaker":"渡部委員","kind":"質問・要望","question":"さまざまな方法をとって、この自転車の交通安全、まだまだ自転車、無謀な乗り方する人も多いと思いますので、いろんなケースにおいて注意をしていただきたいと思います。切符切っていました。３０９ページ。初めに、今回新規計上ということで始められるわけですが、そもそもどのような目的でこの地域公共交通会議というのを開催するに至ったのか、お話しいただけますでしょうか。","respondent":"藤田都市計画課長","answer":"地域公共交通会議を私どもが開催しようと思った目的ですけれども、この間、１６３号線ができ上がる、それから、２６号線の整備も着々と進んできているということで、地域公共交通会議、道路運送法の中で規定があるもので、バス等の事業者等と、会議体を持つことで情報を共有する。","id":"exchange-032"},{"speaker":"渡部委員","kind":"質問","question":"じゃあ、今、バス等の事業者ということですが、もし今の段階でお話しいただけるのであれば、どの辺の民間事業者にお声がけがされているのか、どのような感じの会議体になるのか、教えていただけますでしょうか。","respondent":"藤田都市計画課長","answer":"現段階ではまだお声かけをしているというものではございませんけれども、区内で運行している東急バス、京急バス、それから、東京都の都バスのほうも運行されておりますので、こういった事業者については声かけをしていきたいと考えています。","id":"exchange-033"},{"speaker":"渡部委員","kind":"質問","question":"バス事業者、わかりますけれども、ここにいわゆる私鉄、いわゆる電鉄自体はもう入ってこないんでしょうか。","respondent":"藤田都市計画課長","answer":"今回のもとになる法律が道路運送法ということで、道路の運送に限った部分の話ですので、この地域公共交通会議については、バス事業者ということになるものです。","id":"exchange-034"},{"speaker":"塚本委員","kind":"確認","question":"初めに２８９ページの交通安全啓発費なんですけれども、私がちょっとお聞きをしたいのは、いわゆる駐車監視員というふうに言ったらいいんでしょうか、民間の方ですかね、に委託をして駐車違反の取り締まりを今されているかと思います。","respondent":"谷口交通安全担当課長","answer":"区として何かできるかですけれども、区のほうでも、荷さばきの関係だと思いますけれども、路上パーキングメーターの設置等だとか、東京都道路整備保全公社に登録している民間駐車場においても整備されておる状況ですので。","id":"exchange-035"},{"speaker":"塚本委員","kind":"提案","question":"会議の構成メンバーですね、先ほどバス事業者というのは１つわかったんですけれども、法律によって決められている構成メンバーというのがあるかと思いますけれども、メンバーについてどういうふうに想定されているか、お伺いしたいと思います。","respondent":"藤田都市計画課長","answer":"地域公共交通会議のメンバーですけれども、まずは主催をする区長を中心に、バス事業者、住民または旅客、それから国の地方運輸局のほうですね、それから、バス事業者の運転手が組織する団体、こういった者を中心に、あと道路管理者、あるいは警察の関係。","id":"exchange-036"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。議題ですね、この会議にかける議題、どういったものを想定しているか、これをお伺いしたいと思います。","respondent":"藤田都市計画課長","answer":"法律といいますか、ガイドラインが、「地域公共交通会議の設置及び運営に関するガイドライン」というのが示されてありますけれども、その中では、地域の実情に応じた適切な乗合旅客運送、いわゆる路線バスですね、そういったものに関する事項、それから。","id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"それぞれの区民の方々の思いというのは千差万別であって、端的に言えば、自分のところにバスを走らせてほしいという思いをそれぞれの方が持ち寄ってこられても、なかなか今までの課題というのが解決されないのではないかと思うんですけれども、この辺の区民の意見の反映、この会議でうまく反映をし、意見について最大公約数的なものをまとめていくという方向とか、あるいは。","respondent":"藤田都市計画課長","answer":"既に１０の区が地域公共交通会議を持ってスタートしていますので、そういったところの先進の事例もいろいろ意見を聞かせていただきながら、検討を進めていきたいと考えています。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問・要望","question":"続きまして、３２５ページの新規事業となりますか、住宅耐震化促進協議会活動助成についてなんですけれども、まず今回区長の施政方針演説の中で、建築士事務所協会と建設４団体、これが一緒になって耐震化を進めていくんだということで、こういった協議会が発足し、活動するということでしたけれども、この活動助成の内容、これは具体的にどういったものになっているか、教えていただきたいと思います。","respondent":"大串住宅担当課長","answer":"住宅耐震化促進協議会への助成内容ということでご説明します。こちら、促進協議会につきましては、昨年の１０月に設立をしていただきました。具体的にはもう１１月から活動、個別訪問というのを行っていただいております。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"人件費ということで、基本的に建築士事務所協会の方と建設４団体の方が耐震診断されて、その後改修にまだ至らない方について、どうですかということで訪問をされるということだと思うんですけれども、今年に入ってからもう既に訪問が始まっているというふうに先ほど聞いたんですけれども、現状、まだ数カ月しかたっていないので何とも言えないところもあるかと思いますけれども、成果のほどというか。","respondent":"大串住宅担当課長","answer":"こちら、調査も含めてということで回っていただいておりまして、その中で実際に改修、あるいは建て替え等のこういった措置が終わっているのが８８件と、未実施のところが７１件、残念ながら不明ということで。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"どっちかというと、職人さんとかいう方の世界ではないかと思うので、そういった研修なんかも、営業的な活動助成の中で考えていくというのはどのようにお考えでしょうか。","respondent":"大串住宅担当課長","answer":"そうした中で、営業活動的な部分でというお話は確かにあろうかと思いますけれども、基本的に回っていただいて、工事の受注、発注につなげられれば一番よろしいんですけれども、その中で営業活動だけが先走るというわけにはちょっとまいりませんので。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。そうですね。やっぱり行政の中でやる活動としては、あまり営業、営業というわけにはいかないというのはよくわかるところかと思います。いずれにいたしましても、ことし建築物耐震化支援費というところでは、昨年の平成２４年度を大きく上回る２０億円を超える予算を計上して、これから区内の耐震化、しっかり進めなきゃいけないと。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"今の質疑を伺っていたんですが、１つは、この地域公共交通会議、公開をするのかどうかということ。必要だけれども、採算がとれない、そういう路線については、それは見落とす、見限るのではなく、きちんと検討していただき、区民の願いを受けとめる、そういう形で議論をしていただきたいと考えていますけれども、それについてはいかがでしょうか。","respondent":"藤田都市計画課長","answer":"今私どものほうで、先ほどガイドラインの中に書かれていることを申し上げましたけれども、その中でメーンで考えていますのは、やはり既存のバス路線網の充実がしてあるわけですから、もしほかにこういった路線についてバスの運行が可能ではないかというような話があれば。","id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"公開については、きちんと区の方針として公開をする、そういう立場で臨んでいただきたいと思います。そういうところをしっかりと検討していただいて、品川区自体が、どういうやり方かは別としても、品川区がしっかりとそういう方々の交通手段の確保ということをフォローする、そういう対策をとっていただきたいと考えていますけれども、その点についてはもう一度いかがでしょうか。","respondent":"藤田都市計画課長","answer":"既存のバス路線が区内にはいっぱいありますので、仮にコミュニティバスを動かすというようなことになると、その既存のバス路線のほうに影響が出てくる、場合によってはコミュニティバスがあるのだから、既存のバス路線について廃止してもいいんじゃないかとか。","id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、きちんと区が責任を持って路線を確保する、交通手段を確保する、その立場でやっていただきたいと思っていますが、その点について、いわゆるコミュニティバスという、こういう考え方でやっていただきたいと思っていますが、その点についていかがでしょうか。","respondent":"藤田都市計画課長","answer":"この間、請願等も出てきてあります。それに対していろいろ私どものほうでも答弁というか、見解を述べしています。コミュニティバス等についても含めて、これから設置される会議体の中でしっかりと議論していくべきと考えています。","id":"exchange-045"},{"speaker":"原委員","kind":"質問・要望","question":"私のほうからは２８９ページ、屋外広告物取締事務、これの取締状況を教えてください。それから飛びまして、３０９ページ、景観まちづくり推進事業の中から、これ、景観に関しましては、これはもう都市環境というんですかね、重要な１つのセグメントでありますので、基本的なお考えと、それからあと、環境重点地区の指定検討についての具体的なところをちょっとお教えいただきたい。","respondent":"小林土木管理課長、谷口交通安全担当課長、藤田都市計画課長","answer":"もちろんそれと同時に、定期的に区職員によるパトロール、除却等によって対応しています。あわせて、１３７台増設ということで実施をしたところです。利用率につきましては、その見直し等含めまして、全体で９８％です。景観重点地区の指定検討の状況ですけれども、現在、旧東海道品川地区、それが１つの地区として重点地区となっていますけれども、今、大崎。","id":"exchange-046"},{"speaker":"原委員","kind":"質問・要望","question":"屋外広告物については、これは要望ですので、お答え要らないですけれども、要するに、取り締まりをやってもまたすぐに、中心地域、またいろいろなところで出てしまいますので、その辺を撤去関係よろしくお願いをいたします。うるさいという表現がいいかどうかわかりませんが、厳しいと言ったほうがいいのかもわかりませんけれども、そういった面を有していると。その辺に関して、お考えを。","respondent":"藤田都市計画課長","answer":"景観のまちづくりを進める上で、先ほどお話がありました京都等については、やはり守るべきもの、こういったものがはっきりしているというようなことが１つ挙げられると思います。","id":"exchange-047"},{"speaker":"原委員","kind":"質問・要望","question":"実際の今のご答弁非常によくわかったんですけれども、マスタープラン、いろいろな図式というか、全体的な考え方、非常によくできていると思います。まちのバランスを持ってと。スピード、スピードと言うと、すぐ早くやるというふうに捉えるんですけれども、その辺は、それだけではなくて、タイミングを考えて行っていただきたいと思いますので、その辺についてお考えをいただければと思います。","respondent":"山崎マスタープラン担当課長","answer":"東京都の広域性においても、副都心の機能を負いつつ、委員もおっしゃられた、区民の皆様から見た便益性、利便性、こうしたところの快適性とか、よいまち、これからも目指してまいりたいと考えています。","id":"exchange-048"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、２８９ページの駅周辺等放置自転車対策にいろいろ関連して聞かせていただきたいのと、あと、以前質問をさせていただいた武蔵小山の駅前のバス停、それから３１７ページの武蔵小山駅周辺地域整備事業に関連してということになると思いますが、聞かせていただければと思います。武蔵小山のほうですが、バス停が２カ所ありまして、以前、屋根のないバス停があるというお話をさせていただきました。","respondent":"小林土木管理課長、谷口交通安全担当課長","answer":"引き続き粘り強く対応してまいりたいと思います。放置自転車の多い駅ですけれども、一番多いのはやはり大井町、五反田、あと武蔵小山等が多くあります。これにつきましても、段階的に撤去活動、広報啓発活動を実施しておりますので、年々減少しています。","id":"exchange-049"},{"speaker":"大倉委員","kind":"質問・要望","question":"次に放置自転車ですが、数字、ありがとうございました。やっぱり自転車駐輪場をつくっていくことがこうやってさまざま問題解決につながっていっているのかな。放置自転車の解消に伴う、例えば道路交通の安全性の向上であったり、環境の美化、あとは駐輪場を利用する税外収入とか、そういった部分のさまざまな複合的な区の考え方をどのように考えているのか、教えていただきたいと思います。","respondent":"谷口交通安全担当課長","answer":"ことし、大井町につきましては、陸橋下に移設だとか、そういった意味でどんどん整備を進めておるところです。附置義務等を活用しまして、阪急等も附置義務で３００台を超える駐車場を設置していただけるですので、効果としては絶大だと考えています。","id":"exchange-050"},{"speaker":"大倉委員","kind":"質問","question":"駐輪場、自転車駐車場使用料についてちょっとお伺いします。歳入歳出を見ると、経費がほとんどを占めているということなんですが、行政サービス上、収入に重点を置くというよりも、サービスのために経費を使っているということだと思うんですが、この経費の中身を教えていただければと思います。","respondent":"谷口交通安全担当課長","answer":"駅周辺等放置自転車対策事業ですけれども、この中で、全体の占める割合が４億７,６００万円になるんですけれども、ことし新たに陸橋下の関係がありますので、１億１,０００万円の予算を計上しています。","id":"exchange-051"},{"speaker":"大倉委員","kind":"質問","question":"ちょっと説明が不足していてすみません。有料自転車駐車場運営費のほうの収支についてお伺いしたかったので、そこの経費の内容をちょっと教えていただければと思います。","respondent":"谷口交通安全担当課長","answer":"有料自転車駐車場運営費の関係ですけれども、２億３,５００万円余の計上をしております。中身ですけれども、区営自転車等駐車場の指定管理委託、これに１億９,５００万円、あとは、大崎の自転車駐車場の運営委託ということで、３,８００万円余の予算を計上しております。","id":"exchange-052"},{"speaker":"山内委員","kind":"質問","question":"工事に対するいろいろな意見とか、そういったことも、この地域の皆様からいろいろとあるとは思うんですけれども、商店街と、いわゆる事業をしている業者、それからこの品川区という行政、こういったところがどのような連携をし合いながら、地域の皆様に、例えば説得をするところ、話し合いをして理解をしてもらうところもあると思うんですけれども、そのあたりを少し伺いたいと思います。","respondent":"稲田道路課長","answer":"いつ完成かというところですが、現在私どもの目標としましては、平成２７年度完成の予定で進めております。","id":"exchange-053"},{"speaker":"山内委員","kind":"質問","question":"わかりました。３１７ページの都市防災まちづくり事業費の中で、密集住宅市街地整備促進事業に関する、これ、木密地域不燃化１０年プロジェクトですけれども、これのいわゆる代替地と言っていいのかな、種地と言ったらいいのかな、そのあたりをちょっと伺いたいと考えています。地元品川区は、非常に情報がある、いわゆる地元自治体は品川区といったこともあります。","respondent":"品川防災整備担当課長","answer":"木密地域不燃化１０年プロジェクトに関する用地の取得に関してのご質問です。これから木密地域不燃化１０年プロジェクト、先行実施地区、４月から行っていきたいと考えています。平成２５年度以降、本格実施地区の選定も今現在行っているところであります。","id":"exchange-054"},{"speaker":"山内委員","kind":"質問","question":"３段階で今代替地を購入をしていくというような形で理解をしましたけれども、これ、今、品川区は購入をしていくという言い方を今、防災整備担当課長がしました。これはどういう、その辺のどっちが、どっちの自治体、品川区なのか、東京都なのか、そのどちらの自治体がその土地を、その３段階ある、３つ種類があるその土地の購入をしていくのか。","respondent":"品川防災整備担当課長","answer":"整理しますと、３つの方法ということで、まず１つ目、これは木密地域不燃化１０年プロジェクトの不燃化特区の中です。これ、事業を行うのは、区が行います。","id":"exchange-055"},{"speaker":"山内委員","kind":"質問","question":"しかしながら、地元自治体は品川区といったこともありますよね。そうすると、意見交換みたいなものというのは、やはりどうしても、その地域の人と東京都との間にやはり品川区という自治体が、私は非常に大きな大きな意味合いがあると思うんですね。１月１４日に大変な雪が降りました。そういったところはなかなか除雪ができない。そういったところで、雪害に対する考え方といったものを伺いたいと思います。","respondent":"稲田道路課長","answer":"１月１４日の雪の状況を少しお話ししますと、大雪注意報が１０時４１分に発令されまして、我々、関係部課長と協議しまして、品川区、１９名の監視体制対応というところでやってまいりました。建設防災協議会にも協力を依頼しまして、５社ほど対応してきました。","id":"exchange-056"},{"speaker":"山元委員","kind":"質問・要望","question":"私は２９９ページの道路バリアフリー事業、プレス発表９４ページに八潮団地内道路のバリアフリー化と、ここ、ちょっと教えていただきたいことがあります。これ、どういうことなのか、ちょっと教えていただきたいなと思います。それから、主な工事内容として、最後の部分、車道部の舗装改修等という、この「等」、これはどういうことを指しているのか、ちょっと教えていただきたいと思います。","respondent":"稲田道路課長","answer":"その後で、７００メートルの詳細設計を実施というふうに書いてあるんですが、これは延長が長いものですから、４カ年計画で工事をやっていこうというところでございまして、その前年度に当たる、まあ、その一区画に当たる７００メートル。","id":"exchange-057"},{"speaker":"山元委員","kind":"意見","question":"もう一つ、工事内容のこの車道部の舗装改修等という、この「等」というのはどういうことなのかということなんですけど。","respondent":"稲田道路課長","answer":"八潮地区、高齢化が非常に進んでおりまして、当初の団地計画とだいぶ利用形態が変わってきましたものですから、高齢者にもやさしいバリアフリーの歩道をつくっていこうというところで、このような形で考えております。","id":"exchange-058"},{"speaker":"山元委員","kind":"質問","question":"実はある方が、この話をしましたら、歩道が広くなるのはとてもうれしいんだけれども、車道が狭くなる、常時ではないんですが、車がたまたまとまっていたりして、自分が自転車で車道を走ろうとしたときに、対向車と危ない思いをして、今、９メートルの半分だから４.５メートルですかね、その道路ですらちょっと怖いのに、狭くなったらどうなっちゃうのかしら、そんなようなことを言われたんですが、その辺。","respondent":"稲田道路課長","answer":"こういう中におきまして、駐車して、自転車の通行の方が危険な目に遭うとかですが、今後警視庁との協議とか、そういうのをまた進めていく段階ですので、その辺も頭に入れながら、基本設計、詳細設計等考えていきたいと思います。","id":"exchange-059"},{"speaker":"山元委員","kind":"質問・要望","question":"地元の人の声、また自治会長の声等を聞いていただいて、進めていただきたいと思います。では、次に新浜川公園改修工事実施設計についてお伺いしたいと思います。昨年から基本設計委託をされて、１年間たちました。いよいよこの工事、実施設計ということでありますけれども、実際実施計画というんでしょうか、そういうのがおわかりになれば教えていただきたいと思います。","respondent":"多並公園課長","answer":"バリアフリーも、公園の中、なかなかまだ今整備されていない状況です。これらを踏まえまして、一体的に整備することで、より魅力ある公園として整備していきたいという目的で実施計画を考えたものです。","id":"exchange-060"},{"speaker":"山元委員","kind":"質問・要望","question":"本当にもっと広くなるのかなと思いますが、実はあそこにはトイレがあります。もうちょっと先に小さな公園といいますか、雑草がたくさん生えておりますが、そちらの公園も、今おっしゃったように、花海道と一緒の高さというか、続きといいますかね、そういう形になるんでしょうか。","respondent":"多並公園課長","answer":"そこにつきましても、花海道と一体的に、本体のほうの公園がやるところですが、そこの花海道の方が例えば休める空間だとか、そこら辺もこれから最終的には取りまとめて、地元の方々とも協議をしながら、特に近隣の方が一番大きいかと思いますので。","id":"exchange-061"},{"speaker":"山元委員","kind":"質問・要望","question":"今公園課長からもお話がありましたが、ある意味でとても住宅街の中にある新浜川公園ですので、本当に住民の方のご意見を聞いていただきたいと思いますが、また一方、ここは龍馬の砲台が近くにもあります。そういう意味ではこの公園、やりがいによっては、観光というか、人を呼ぶような公園にならないかなと思うんですが、その辺のお考え、いかがでしょうか。","respondent":"多並公園課長","answer":"公園の整備に当たりましては、もちろん今までの施設よりは花海道を一体的に整備するところで、観光というのはどうもあれですけれども、地元の方々のお話もよくお聞きして、可能なことがあれば、その中でも検討していきたいと、そう考えてあります。","id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは３０９ページのやさしいまちづくり整備費、それに関連して、２９９ページの視覚障害者用誘導ブロック設置についてお聞きしたいと思います。やさしいまちづくりというのは、どういう考えのもとで進められているのか。やさしいまちづくり推進協議会というのがあると思うんですけれども、どんな方々で構成されているのか。障害者団体の方は入っているのかをお聞かせください。","respondent":"山崎マスタープラン担当課長","answer":"区としましても、そうした考え方を基本に添えまして、全ての人にとってできる限り利用しやすいまちづくりを進めていくために、ハード整備と同時に、心のバリアフリーを含むソフト施策を一体的に推進するために、計画を策定して、これのもとに施策を展開してきたです。","id":"exchange-063"},{"speaker":"石田（ち）委員","kind":"質問","question":"視覚障害者の方々というのは、この団体の中に、推進協議会の中にも入っているということなんでしょうか。それから、３０９ページに、大井町駅周辺バリアフリー計画策定検討委託というのも書いてあるんですけれども、これは大井町のどの辺に主に何をするのかというのは、もう決められているのかどうか。","respondent":"山崎マスタープラン担当課長","answer":"今回予算に計上させていただいている委託というものは、いわゆるまちの現状を、いろいろ施設間の経路も含めまして、どんな状況になっているのかというようなことも区として把握する必要もあるというようなこともあって、そうした調査をさせていただいたり、あるいは、来年度。","id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それとも、７団体の中の代表ということなんでしょうか。そこをもう一度確認したいのと、あと、プレス発表などでも、やさしいまちづくりとして区内の４０駅、バリアフリー化完了とあります。エレベーターやスロープが整備されたと。特に一番要望の多い旗の台駅、心身障害者福祉会館もありますので、そこを検討して、こういったやさしいまちづくりの中で検討していただけるのかどうかということをお願いします。","respondent":"山崎マスタープラン担当課長","answer":"基本的にはホームの安全対策については、本来事業者が行うべきものというような認識のもとに、誘導させていただいているところです。","id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ旗の台駅のほうのホームドアを早急に進めていただきたいと思います。それから、視覚障害者の方々を推進協議会にやはり一緒に入れ込んでいただいて、当事者の声として進めていただきたいなと思います。この大井町周辺バリアフリーの計画にこのエスコートゾーンは入れていただけているんでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"エスコートゾーンにつきましては、大井町周辺の、今社会福祉協議会の前などを検討しておりますけれども、そうしたところも含めて包括的に面的な整備に努めてまいると、このように考えてあります。","id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ当事者の声を聞いて、積極的にスピードアップして進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"向委員","kind":"質問","question":"ちょっとお尋ねしたいことが幾つかあるので、まとめてさくさくとお尋ねいたします。１年ぐらいたって、何も変わっていない。いろいろ電車の線路が高架であるのに、態勢はそれなりにされていると思うんですけれども、線路がもし両方とも最悪崩れてしまった場合に、あまり避難所として避難ルートの確保がどうなのかな、ちょっと区のお考えをお伺いしたいです。","respondent":"小林土木管理課長、谷口交通安全担当課長、山崎マスタープラン担当課長、多並公園課長、大串住宅担当課長","answer":"平たく言えば、客が少ないということで、確かにそれであれば、路線を廃止して。委員ご質問の有料自転車駐車場運営費の中の人件費の割合ですが、おおむね７割と聞いておるところです。多機能トイレの新設を平成２９年度中に行いまして、順次供用開始していく予定ということです。先ほど新幹線のところと電車とございましたが、今も鉄道事業者が新幹線含めて耐震工事等を含めまして、安全確保という部分であり。来年度、平成２５年度につきましても、この品目についてはある程度の変更を考えているといったところです。","id":"exchange-068"},{"speaker":"向委員","kind":"質問・要望","question":"ＪＴ跡地に関しては、線路の耐震化を事業者側とともにしっかり進めていただきたいという、その願い１つなんですけれども、これ、今後の使い方ですね、ＪＴ側に売却依頼文書を出したときには、防災上の役割を一段と高めることとなり、本区全体の防災力向上の観点からも極めて大きな意義を有するものと考えております云々ということで、防災を目的に今回売却していただいて。","respondent":"多並公園課長、山崎マスタープラン担当課長","answer":"そういった意味では、広場を、またＪＴのもともとのご意向を踏まえて、防災目的でお売りいただいたことも鑑みて、空地を確保する観点からも都市計画決定というところに担保していって、今後も防災に資する公園として開放していく。事前にその辺、いろいろ通行されていた方々もいますので、十分説明を行って、近隣の方々にはご納得をいただいているということで、現在工事中につきましてのそういった意味の苦情は来てございません。そんなような状況です。","id":"exchange-069"},{"speaker":"本多委員","kind":"質問","question":"２９２ページの道路維持費など、道路全般について質問します。初めに、本会議の一般質問のこの間の答弁で、道路ふれあい月間という言葉があったんですが、まずその意義についてお聞かせください。","respondent":"小林土木管理課長","answer":"これにあわせて、区においても、地域と連携して、可能な限り、道路についてふれ合う機会を多くし、その用途を一緒に考えていきたいという機会にしてまいりたいと考えております。","id":"exchange-070"},{"speaker":"本多委員","kind":"質問・要望","question":"これ、平成２６年度の完成まで２年間という歳月がありますが、対策として、西品川一丁目地区再開発の敷地を使って迂回させてはいかがでしょうか。この西品川一丁目再開発の着工が、早くて順調に行って平成２６年度だと思いますので、それまでの間、この敷地を使って百反通りのほうに迂回するようなことをぜひ活用していただければと思いますが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"私のほうから百反歩道橋の工事に関してご説明をします。委員ご指摘のとおり、年明けより本格的に道路を閉鎖する形での工事に入っております。当初、車線を、相互通行のところをとめて工事をしている関係上、どうしても渋滞長が長くなるという関係がありました。","id":"exchange-071"},{"speaker":"本多委員","kind":"質問・要望","question":"渋滞対策、いろいろ考えてください。その前後に駐停車台数が常に多いことから、通行車両からは死角が多く、歩行者は歩きづらい、危ない、そんな状態でしたので、信号機の設置をとの地域の声を地元町会長と自民党、公明党、民主党で品川警察へ要望、区へ要望、または区政協力委員で取り上げたり、いろいろな角度から区の協力、ご理解を得て、まもなく実現いたします。","respondent":"谷口交通安全担当課長","answer":"だから、２年というよりは、若干かかっていると思います。警察のほうで、交通量だとか、付近の交通状況を全部調査しまして、その必要性を認めて、設置になったです。今年度中には、もう工事が終わっておりますので、３月中には点灯するというふうに聞いております。","id":"exchange-072"},{"speaker":"本多委員","kind":"意見","question":"それで、新設されることは本当にすばらしいことなんですが、この坂を１５０メートルぐらい下ったところに既存の信号機がありまして、これを実は点滅にしたほうがいいんじゃないかというふうにも思うんですが、その既存の信号機をかえるという、そのまたご苦労というか、その辺の困難さというか、その辺についてお聞かせいただければと思います。","respondent":"谷口交通安全担当課長","answer":"信号については、いろいろご意見がありますので、１００人いれば１００通りの考え方があります。点滅したほうがいいというご意見もあろうかと思いますし、通常のままがいいというご意見もあると思います。","id":"exchange-073"},{"speaker":"本多委員","kind":"質問・要望","question":"生活の動線で不便がある場合、設置の要望などあった際、郵便局長会では心あるご理解をいただいておりますが、本局が決裁をするものですから、その決裁が長年出てこないケースがありまして、こうしたものを区の道路所管課のほうから、または区の総務課なりから、そういう働きかけというのはできないものかという、その働きかけについてお聞かせいただきたいと思います。","respondent":"武内総務課長","answer":"郵便局、民営化になりまして、そのような状況の中で難しい部分もあるかなと思うんですけれども、日ごろから郵便局の皆さんと情報交換等、連携をとっておりますので、そういった中で話をさせていただいて、協力要請と、区民の強い要望だということを伝えながら。","id":"exchange-074"},{"speaker":"本多委員","kind":"質問・要望","question":"余り郵便事業のことでくどくやるつもりないんですが、働きかけをぜひお願いします。こんな事例がありまして、健常者でない方が、やはり生活動線上にどうしても郵便ポストがないと。一般の人が入れないところにあるようなことを説明されたものですから、なかなか地域住民の方が理解をしないというようなところがありましたので、今後できるだけ働きかけていただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"高橋委員","kind":"質問・要望","question":"ほかの委員からも幾つか質疑があって、根拠法令や目的、構成メンバーなどのご答弁をいただきました。それらのお話をちょっと確認したいんですけれども、ご答弁の中に将来の公共交通ネットワークを幅広い視野に立って検討すると。既存のバス路線があると。既存のバス事業者に新たにルートを要望していく。その中でも、既存のバス事業者に新たなルートをというような点で確認してよろしいでしょうか。","respondent":"藤田都市計画課長","answer":"地域公共交通会議ですけれども、ただいま委員のほうからお話がありましたとおり、将来にわたって広い視野を持って地域の公共交通のネットワークを構築すべく会議体の中でしっかり皆さんと議論しながら進めていく、こうした考えです。","id":"exchange-076"},{"speaker":"高橋委員","kind":"質問・要望","question":"今、バスの路線の話が出たんですが、現在、区が課題あるいは要望としてお考えになっているルートは幾つかあると思うんですが、特に補助２６号線の計画等の関係で、どのようなルートについて区はお考えでしょうか。","respondent":"藤田都市計画課長","answer":"東急バスのほうからは、２６号線の進捗に合わせて、改めてお答えをしていきたいと。どちらかというと前向きなお話の中での具体的なものについてはそこの中でというような回答を得ているところです。","id":"exchange-077"},{"speaker":"高橋委員","kind":"質問・要望","question":"今お話にあったように、特に大井町から武蔵小山のルート、この会議の場で区のほうが要望していただけるということで、東急のほうも前向きということで、今お話あった整備が進められている補助２６号線なども含めて、将来の道路ネットワーク、これを見据えてバス路線の充実が図られることを期待します。区内には鉄道網が発達しております。この点について区の見解を伺います。","respondent":"山崎マスタープラン担当課長","answer":"今後の抜本的な解消には、やはり改札を出てすぐ踏切があります補助２９号線との交差部、これの検討に当たりまして、鉄道高架による抜本的な踏切の除却も含めまして、事業主体です東京都、あるいは鉄道事業者と連携し、地元の方々のご意見なども踏まえまして。","id":"exchange-078"},{"speaker":"高橋委員","kind":"質問","question":"この２９号線の整備に合わせて、踏切の解消、そして、防災性の向上が図られますことを強く期待しております。そして、今、東急のお話が出ましたので、次に京急の関係でお伺いしたいと思います。昨年１０月には京急蒲田駅付近の連続立体交差事業、これが進展しまして、またダイヤ改正が行われました。日中です。こうした状況を踏まえて、改善に向けて区の見解はどのようなものでしょうか。","respondent":"藤田都市計画課長","answer":"今回の１０月に行われました京急のほうのダイヤ改正の関係ですけれども、事前に京急のほうから私どもにも説明がございまして、その中で委員がお話しされたようなエアポート急行が快特になるというようなことでの説明を受けてあります。","id":"exchange-079"},{"speaker":"高橋委員","kind":"質問","question":"今、都市計画課長のほうはこういった状況だというお話ありましたけれども、改善を働きかけるということなどはしていただけないのでしょうか。","respondent":"藤田都市計画課長","answer":"いろんな動きを捉える中で、必要なことについてはしっかり相手方にも伝えていきたいと考えています。","id":"exchange-080"},{"speaker":"高橋委員","kind":"質問・要望","question":"京急蒲田駅との事情はちょっと違うんですが、ぜひ区民の皆さんのご要望を、今お話あったように、京急のほうに伝えて、少しでも事態が進展するように強く働きかけていただきたいと思います。まちづくりマスタープランにも触れられていましたが、改めて併用化についての区の基本的な考え方、そして、この構想の概略をご説明いただき、そして、とりわけ八潮地区への今後の影響などについてお伺いします。","respondent":"山崎マスタープラン担当課長","answer":"ただ、一方で、例えば八潮団地からのアクセスなどを考えますと、地図上はそんなに大した距離はないのですが、間に首都高の湾岸線、あるいは新幹線の貨物の車両基地などがあって、少し回遊性という意味ではまだまだ多くの課題があるなというような認識です。","id":"exchange-081"},{"speaker":"高橋委員","kind":"質問・要望","question":"これで公共交通については終わらせていただいて、次に、ちょっと順番があれですが、３１０ページの公園管理費でよろしいかと思うんですが、先ほども大雪の話が出ていましたが、大雪による被害、いろんなところでありましたが、特に公園におけるさまざまな被害があったと思うんですが、それについてご説明いただいて、今後の修理というんでしょうか、その予定についてお伺いします。","respondent":"多並公園課長","answer":"今後の予定といたしましては、地元の町会の皆様などのご意見をお聞きしながら、地元でお使いになる時期を調整しながら、早急な対応ということで工事を来年度実施したい、そのように考えてあります。","id":"exchange-082"},{"speaker":"高橋委員","kind":"質問・要望","question":"最後になりますが、これ、道路安全施設費なのかちょっとわからないんですが、南大井五丁目と大井六丁目をつないでＪＲを潜るところの道があるんですが、あそこは自転車を降りなければいけないんですが、ちょうど坂になっていて、スピードが出るというか、そういう形で自転車で通行する方がいらっしゃるんですが、あそこの扱いはどのようになっているんでしょうか。","respondent":"稲田道路課長","answer":"ということで、今後もちょっとよく現場を見て対応していきたいと思います。","id":"exchange-083"},{"speaker":"浅野委員","kind":"質問","question":"２９５ページ、路面維持管理費、そこから道路下空洞・雨水管修繕について、３０１ページの下水道管改修事業、耐震化推進事業と老朽化対策事業、時間があれば３１３ページの仮称小山６丁目児童遊園整備工事について質問します。区道の緊急啓開道路だけでもたしか１５キロほどあったかと思います。それで３年間でどの程度実施をするのか。１５キロ掛ける３なのかどうか、その点についてもお願いします。","respondent":"稲田道路課長","answer":"緊急啓開道路等、あと、避難所等の周辺を今考えておるんですが、年間１５キロをまずやっていきたい。それから、３年間ですから、１５キロ掛ける３、全体では４５キロを調査して、防災上必要な道路については調査をしていきたいと考えております。","id":"exchange-084"},{"speaker":"浅野委員","kind":"確認","question":"国道とか都道、こちらについては、国または都がそれぞれこの空洞調査を実施していると、そのように伺っておりますけれども、こちらの調査結果というものは確認をされているのかどうかということと、あと国道と都道と区道の道路のネットワークという考え方は多分あるかと思うんですけれども、状況によっては空洞調査する区道の優先順位も、これも発生するのかなと考えますけれども、この点いかがでしょうか。","respondent":"稲田道路課長","answer":"国道、都道、区道との連携というところになりますが、緊急啓開道路、国道も都道も、私ども区道も、そういう中ではつながっております。そういうところにおきましては、都道の状況、国道の状況等もできる限り連携をとりながら、調査等も図っていきたいと考えています。","id":"exchange-085"},{"speaker":"浅野委員","kind":"質問","question":"下水道管の老朽化によっての水漏れによる空洞というのが結構多いと聞いておりますけれども、下水道管の老朽化対策事業、これは都から受託をしているかと思いますが、区内の下水道管の老朽化の全貌というんでしょうか、これは把握をされているのかどうかということと、区内の対策、下水道管ですね、こちらが一巡するまでにどのぐらいの期間がかかるのか、教えてください。","respondent":"稲田道路課長、武藤河川下水道課長","answer":"その原因が、下水道だけではないので、例えば下水道であれば、その管理者の下水道局と調整する、また、水道であれば、水道局とも調整し、その原因者と連携を図りながら、発見した場合は早急に対応したいと考えております。ですが、特に品川区で一番古い下水道管、北側の目黒川の左岸地区を今中心に進めておりまして、目黒川より南側の地区につきましては、まだ昭和４０年代に敷設した管が多いことから、今後順次改修を進めていくと聞いております。","id":"exchange-086"},{"speaker":"浅野委員","kind":"質問","question":"今回区のほうで道路下の空洞調査をやるのに、今回３年ということで、４５キロということでありますけれども、区道も本来からするともっと長いのかなと思って、全部ではないだろうなと感じているところでありますが、この下水道の老朽化が一巡する間に、やはり相当な年数たつと思いますね。この二面性を持って道路を守るための取り組みをされているかと思いますが、この考え方はいかがでしょうか。","respondent":"武藤河川下水道課長","answer":"ですので、今回、平成２５年度におきましては、東京都からそうした古い老朽化した下水道管の改修を受託することで、未然防止を進めていくということで対応を予定しております。","id":"exchange-087"},{"speaker":"浅野委員","kind":"意見","question":"粛々と、事故の起こらないように、陥没が起こらないように対策をとっていただければと思います。大きな震動が発生をしたということですが、平らにするときの震動かなとも思いますが、この状況と、あと、土地の借用が１０年間というふうに聞いておるんですけれども、１０年たったら返してしまうのか、それともお願いをしてさらに延長する、今からは早いかと思いますけれども、お考えをお聞かせください。","respondent":"多並公園課長","answer":"この公園を来年度に向けて工事を進めてまいりたいと考えています。ただ、防災目的ですので、例えば貯水槽を設置するなど、そのような防災に資するような、また広場を中心に考えてあります。","id":"exchange-088"},{"speaker":"浅野委員","kind":"意見","question":"この地域というのは住宅街で、あいているスペースというのはコインパーキングぐらいしかないので、区民の皆様、地域の皆様にとって重要な公園だと思いますので、ぜひとも継続できるように取り組んでいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-089"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"じゃあ、あと、２面どうするんだという話があったときに、いろいろ頑張りますという話があって、０.５は、今のしながわ区民公園で対応します、ナイターを含めて、という話があったと思うんだけれども、そうすると、その後の、それもずっと後になるというと、後の２はどうしちゃったのって、どういう頑張り方があるのというのを教えていただきたいと思います。","respondent":"多並公園課長","answer":"もう一つ、野球場ですが、もちろん前にお話させていただいたとおり、ナイター設備等ということで、最終的にはそのような進め方で、いまだに大きな点では変わってございませんが、またその後の２面等というところにつきましては、いろいろな、今後も。","id":"exchange-090"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると、品川区には、海というか、港はたくさんあるんですよね。ところが、阪神・淡路大震災を受けて第４次港湾計画が決められて、横浜市、川崎市、大田区、品川区。品川区は相当港はあるんだけれども、そう考えると、青空球場を返しました。それに対する動きがかかっているのかということも含めてちょっと答弁をいただきたい。","respondent":"多並公園課長、藤田都市計画課長","answer":"やはりこの全体的な計画の中で、今後港湾計画、大きな臨海部も含めて行っていますが、そこについてはよく動きを注視しつつ、可能であれば今のような、公園の立場からしましたら、そういう広場があれば。そういうような観点から、まだまだ港湾局としては施設が足りないと考えていますので、委員ご提案のことについてはなかなか厳しいかなと考えています。","id":"exchange-091"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本当にそう、厳しいんだけれども、これは政権もかわったので、我々ももう一度再度政権与党として国に言っていくべきかなと。品川区は修了証。これは多分品川区のほうがよくやっていますよ。品川区のほうがよくやっている。修了証なんだけれども。それを品川区から発信して、免許証つくって、こういうのを付加してやっていこうというような形がとれないのかどうかというのを答弁いただきたい。","respondent":"谷口交通安全担当課長","answer":"そこでやっぱり場所だとか、時間だとか、その調整も必要になってこようかと思うんですけれども、導入の可否につきましては、各区から情報収集しながら、実施の可否について研究、検討していきたいと思います。","id":"exchange-092"},{"speaker":"稲川委員","kind":"質問","question":"私からは２９３ページ、道路維持費、２９５ページ、道路安全施設費、全般にかかわってくると思うので、お伺いしていきます。歩道の整備や改良、そして区道や区道の付属物の破損における原因者負担というんでしょうかね、それについてお伺いをしていきます。最初に歩道の整備や改良の考え方についてお伺いしていきたいと思います。東急大井町線が開通したのが昭和２年。","respondent":"稲田道路課長","answer":"三間通りの歩道設置についてお答えいたします。委員お話のとおり、三間通りは、旗の台五丁目、中原街道から二葉一丁目の区役所の前まで続く約３,０００メートルの通りです。","id":"exchange-093"},{"speaker":"稲川委員","kind":"質問","question":"通行が多い道路においては、３メートル以上ですか、少ない道路は２.５メートル以上でということでありました。実際、こういった地域というのが、品川区全体を俯瞰をすると、多くこういった歩道幅のところが、安全が担保されていないというんですかね、そういったところがあると思うんですが、品川区としては、今後そういった歩道をどうとらえて、どう整備をしていくのかということをお知らせください。","respondent":"稲田道路課長","answer":"今後の防災上のお話もされましたところですが、限られた道路幅の中においては、今後、いろいろな形で検討していくですが、防災上有効な電線類地中化という話もあります。いろんな手法も考えながら、今後は検討していきたいなです。","id":"exchange-094"},{"speaker":"稲川委員","kind":"質問・要望","question":"これは要するに一方では交通安全協議会などで、やっぱり交通安全協会の皆様も一緒になって旗振りをして、子どもたち、そして高齢者、若い人たちの安全を守るために、地域は地域で頑張っておりますけれども、一方ではそういったハード面がそうであり、一方で頑張っていても、なかなかうまくいかないと思いますので、１回ちょっと交通安全担当課長のご見解をいただきたいと思います。","respondent":"谷口交通安全担当課長","answer":"交通事故の発生状況について、所轄署にちょっと聞いてみたんですけれども、昨年１年間で７件と、交通事故自体は少のうあります。規定速度も３０キロということで、制限速度を守っていただければ、事故ももっと減るのかなと思います。","id":"exchange-095"},{"speaker":"稲川委員","kind":"質問","question":"原因者負担という言い方がいいかあれですけれども、それについてお伺いします。この原因者負担というのが、先ほど申し上げまして、正しいかどうかは別にいたしましても、この辺について区はどのようにお考えなのか。原因者が特定できた場合、できない場合、どういった動きというか、アクションがあるのか教えてください。","respondent":"稲田道路課長","answer":"一般的な利用をしていない、例えば過積載の車が乗り入れたりとか、工事現場等で予想以上の車が入ってきて、そこのところは判断が難しいところではあるんですが、そこはよく現場を見ながら、一般的な利用を超えておったりする場合は、原因者と現場の状況等を確認し合いながら。","id":"exchange-096"},{"speaker":"稲川委員","kind":"質問・要望","question":"それは、まあ、恐らく現場を道路課長も見たと思います。これはもう早急にやっていただきたいと思います。総重量でいくと１３トンから１７トンあるので、真夏、もしバス停にとめておいたら、ただでさえ多分アスファルトが変形して轍ができると思いますので、そういった部分をしっかり行政としても、指導というんですか、請求ができたらやっていただきたいと思うんですが、それについてご答弁お願いします。","respondent":"稲田道路課長","answer":"アスファルトとコンクリートが混ざった舗装で強度を持たせているです。ただ、東急バスの今おっしゃられたところに関しましては、建設した経緯とか、それから現状の使い方、その辺、もう一度現場をよく調査しまして、適正に対応したいと考えています。","id":"exchange-097"},{"speaker":"稲川委員","kind":"質問・要望","question":"そういった中で、それも原因者が明確であるわけですから、しっかりとそれは請求していただきたいというのもあるんですが、そうなる前に、例えば品川区の建築課、もしくは民間の確認審査機関というんですかね、そこで建築確認を出す前に、こういったことをしっかりやってくださいという指導をして、極力そういったことがないようにしていかなければいけないと思うんですが、建築課長。","respondent":"中村建築課長、小林土木管理課長","answer":"今お話をいただきまして、これからも一層そういった働きかけを強く行ってまいりたいと考えています。今の工事等の関係ですけれども、区道もしくは歩道を通過するために、使うだけでは占用なり何なりの必要性は生まれてきませんが、その結果、今ご指摘がございましたように、破損等をしているという場合には、道路管理者として。","id":"exchange-098"},{"speaker":"稲川委員","kind":"質問・要望","question":"時間があまりないので、先ほど自民党の石田委員のほうから港湾関係の話が出ましたので、１点だけ、情報ということでお伺いをしたいんですが、品川ふ頭が今あります。品川ふ頭が、あそこをなくして、青海南ふ頭というんですかね、埋め立てしているところに移るやにも聞いているんですが、その辺の情報はとられているかどうかお知らせください。","respondent":"藤田都市計画課長","answer":"今のお話ですけれども、現在のところ私のほうではつかんでおりません。改めまして、港湾局のほうともお話を聞いてみたいと考えています。","id":"exchange-099"},{"speaker":"稲川委員","kind":"意見","question":"よろしくお願いします。これ、港で働いている人の情報の中でなので、ただ、本当にそれがそうであれば、早目に情報をつかんでいただいて、品川ふ頭もそれなりに広さがありますので、今後東京都がまたそこに単独で何かをやってしまうというのではなく、しっかりと品川区も絡んで、グラウンドなり何かを整備していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこでお伺いしたいのが、木造住宅で言えば、旧耐震が１万３,３０５棟、９５％達成するためには５,０８０棟の耐震化が必要で、年間５６０棟を耐震化していくという計画が出されたわけですけれども、これ、平成２４年度から年間５６０棟ということなんですが、９年間でどういうふうに達成していくのかという、その考え方を聞かせてください。","respondent":"品川防災整備担当課長","answer":"この目標に向かいまして、現在やっております耐震診断、耐震補強設計、耐震改修、それから耐震化建替、建物除却等を活用いたしまして、この目標の９５％に向けて達成していきたいと考えております。","id":"exchange-101"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だから、わりと私は診断の中でかなりそういう耐震化のほうにつながっているなと、この割合を計算すると大体６割ぐらいになるんですけれども、そういう点では、診断を抜本的に増やすということが耐震化にもつながっていくんじゃないかなと思うんですけれども、そこの考え方についてもお聞かせください。","respondent":"品川防災整備担当課長","answer":"すみません。答弁漏れがありました。申しわけございません。耐震化の防災対策上の考え方ということですけれども、当然この耐震対策というのは、阪神・淡路大震災でも、８割の方が、家が倒壊して亡くなったように、非常にこの部分は充実していかなければいけないところです。","id":"exchange-102"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はこの予算そのものはやっぱり去年の実績を、せめてね、５６０棟毎年やっていこうという目標が掲げられているわけですから、それでこれだけの実績が出ているわけですから、それを上回るような予算をぜひ組んでいただきたいし、また、この予算を超えても、実際に希望する方にはやっていただきたいということで要望したいと思います。これはすごくよかったなと評価をしたいと思います。","respondent":"品川防災整備担当課長","answer":"そういった意味では、地区でまちづくり相談会等をやっておりまして、そういう中で耐震の相談なんかもやってあります。それから、ＰＲにつきましては、今後も引き続きいろいろなところで説明してまいりたいと思います。","id":"exchange-103"},{"speaker":"松澤委員","kind":"質問","question":"３２１ページの住宅・建築物耐震化支援事業と、３２５ページ、親元近居支援事業、この２点を聞きたいと思います。耐震のほうは、今出たばかりですので、ちょっと時間をおきまして、親元近居支援事業、４５件、４４３万４,０００円、これの内容についてお聞きしたいと思います。","respondent":"大串住宅担当課長","answer":"親元近居支援事業についてのお尋ねです。こちら、４５件というのが、４５世帯に対してポイント交換を行うという意味での４５件です。","id":"exchange-104"},{"speaker":"松澤委員","kind":"質問・要望","question":"３世帯、親のそばに子どもたちが近所に住んでということなんでしょうけれども、これは昨年は３５件なんですね。こういうふうに立派なパンフレットもあるんですけれども。私はこれがどうしても考えられない。予算が足らなかったら、流用したり、あるいは補正を組んだりするべきだと思うんですけれども、何でこれを打ち切りにして、また改めて今年度始めているのか、その辺しっかりと教えていただきたい。","respondent":"大串住宅担当課長","answer":"残念ながら、平成２４年度につきましては終了という形になりましたけれども、平成２５年度につきましては、この実績を踏まえまして、１０件、予算額的には１００万円分増やしておりますし、また、交付のやり方についても、抽選方式を導入するなど。","id":"exchange-105"},{"speaker":"松澤委員","kind":"質問","question":"今、抽選方式と言いましたけれども、抽選方式、おかしいよね。これ、やっている理事者、おかしいと思いませんか。えっ、そんなことないでしょう。１０月ですよ。まあ、やらないと言うんだから、ごめんなさいねという話をしたんですけれども、予算書でまた４５件やっている。じゃあ、その人どうしたらいいの。今年申し込めばいいんですか。そんなことができるんですか。ちょっとお考え聞かせてください。","respondent":"大串住宅担当課長","answer":"平成２５年度も同様の形、規模を拡大した形でやらせていただきますけれども、なるべく先着順とか、そういったことではなくて、広く公平に助成を行っていければと考えておりますので、その辺、執行方法については工夫をしていきたいと考えておるところです。","id":"exchange-106"},{"speaker":"松澤委員","kind":"質問","question":"答弁、全くおかしいですよ。先着順で、３５名で打ち切っちゃった。じゃあ、３６、３７、３８、３９、４０人目の人はどうするんですか。資格があってもやれない。しかも、だって、今年また始めているんですよ。じゃあ、予算をどういうふうに組むんですか。全て数終わっちゃったらもう打ち切りですよというのは、これが全てなんですか。私はこれはどうも納得いかないんですよ。その点もう一度お答えください。","respondent":"大串住宅担当課長","answer":"そういった意味で、平成２４年度、途中で終わってしまったというのはまことに申しわけないところですけれども、そういったことを踏まえまして、平成２５年度、予算額の増額、こういったことをやって事業の有効な展開を図ってまいりたいと考えております。","id":"exchange-107"},{"speaker":"松澤委員","kind":"質問","question":"今担当課長からお話を伺いました。これでやめたいと思いますが、企画財政課長、この件をどう思いますか。","respondent":"本城企画財政課長","answer":"事業の目的ですとか、あるいは、申し込みを受け付けるときに、お客様のほうにどのようなアナウンスをしていたかも含めて、全体を考えて、補正してでも全ての方に対応するか、それはケース・バイ・ケースによって考えていかなければいけないことだと考えています。","id":"exchange-108"},{"speaker":"松澤委員","kind":"質問","question":"もう一言。だから、今の本当に納得いかないということだけ述べておきたいと思います。耐震診断、先ほどお話を伺いました。無料の簡易診断から耐震診断助成金を受けて、それから建替えと言うんですけれども、先ほど６０％超えているとか言いましたけれども、どうしてこれ、１２万円のところ、半額６万円払ってまで耐震診断して、それから改修に進まないのか、その辺をちょっとお聞きしたいと思います。","respondent":"品川防災整備担当課長","answer":"これはいろいろそのご家庭によって事情があるかと思います。１つ大きく言えることについては、やはり費用の面ということがあるかと考えられます。それから、あとは、相続ですとか、そういった家庭内の事情というのもあります。","id":"exchange-109"},{"speaker":"松澤委員","kind":"質問","question":"そのことは十分にわかります。それで、この耐震診断をして、あと、耐震改修、あるいは除去、建替えしますけれども、これ、建築基準法に違反しているもの、例えば４２条２項道路に出っ張っているとか、増築しちゃったとか、もともと接道していない、そういう建物に関してはどういう措置をとっているんでしょうか。","respondent":"品川防災整備担当課長","answer":"ただ、改修の段階において、区としてもなるべくその辺は改善するようにというふうには指導のほうはしております。建替えにつきましては、当然建築基準法の範囲内で建て替わりますので、こういうセットバックの部分についてはきれいに解消されると考えております。","id":"exchange-110"},{"speaker":"松澤委員","kind":"質問","question":"建て替える場合はちょっと違反があろうと何だろうと、みんななくなって、新たにするんですから、助成を十分にすべきだと思うんですけれども、答えは、まあ、次に、はい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"金野委員","kind":"質問・要望","question":"公園整備についてですけれども、この公園の、特にトイレの設置についてお伺いしたいと思います。設置するには何か条件とか基準があるのか、教えていただきたいんですけれども、例えば面積から見た場合、１,０００m2以下の場合は、例えば９００m2で未設置のところもあれば、３００m2でも設置をされているところもあるという、こういう状況があります。","respondent":"中村建築課長、武藤河川下水道課長、多並公園課長","answer":"私道整備事業ですけれども、こちらは平成２２年に例年の申請件数の倍以上の申請をいただいたということで、これが翌年度も継続して申請が増えたです。そういった面も勘案しながら、見直しを検討する必要があると認識しております。配置基準等の決まったものはございませんが、実際に設置する際は、そこの利用状況、また周りの施設の状況などを勘案しながら設置を検討するものです。","id":"exchange-112"},{"speaker":"金野委員","kind":"提案","question":"それぞれご答弁ありがとうございました。例えば帰宅困難者対策というところでも、また、避難所としても使う場所も、そういうことも考えられるといったところでは、地域の方のお声、ご意見などをいただきながら、今後トイレの必要な場所というか、一時（いっとき）集合場所みたいなところにはつけていくという考えを提案したいのですが、いかがでしょうか。","respondent":"多並公園課長","answer":"今のイベント等々に、いわゆる一時（いっとき）集合場所に必要なもの、また、ところですが、そこら辺は、いわゆる本当のトイレの設置については、維持管理のメンテナンス上の費用の面等勘案して、全体的に検討が必要なものと考えています。","id":"exchange-113"},{"speaker":"阿部委員","kind":"質問・要望","question":"これ、何とかしてほしいというご要望を以前も区民の方のお声としてお伝えしたことがあると思うんですけれども、その後大田区との協議がどうなっているか、教えてください。いつまでもその１回のワークショップの流れを、５年も１０年も使い続けるというのは、当初の考え方にちょっと合わなくなってきているのではないかと思いますが、お考えを伺いたいと思います。お考えをお伺いしたいと思います。","respondent":"山崎マスタープラン担当課長、多並公園課長","answer":"大田区のほうも、面的整備で、大森駅周辺、これ、品川区域も入るんですけれども、その辺の面整備の検討を今ちょうど行っているというような状況というふうに伺っております。そういった面でいいますと、いわゆるランナーであれば、今より走りやすいというところで、もちろんそこら辺も、きょうのアイディアをいただきまして、１つ念頭に置きながら、計画を練る際には考えてまいりたいと考えています。","id":"exchange-114"},{"speaker":"阿部委員","kind":"質問・要望","question":"それで、特に小関橋の信号設置については、暫定道路の間は難しいということだったんですけれども、昨年末つけていただいて、大変ありがたかったんですが、まだほかにもいろいろ地元の、特にＰＴＡから要望が出ております御殿山小学校脇の交差点の信号、それから、拡幅された道路の４０キロ制限をもう少しゆっくりできないか、そういったことをまだ引き続きご検討いただきたいと思っているのですが。","respondent":"多並公園課長、溝口都市開発課長","answer":"これについては、その中で、今までなかったものを実現していくということで、ここの公園も考えていきたいと、そのように考えてあります。百反歩道橋が完成すれば、百反歩道橋には自転車も対応できるエレベーターも設置しておりますので、大崎の西口から東口へ自転車を百反歩道橋のエレベーターを使っていただき、安全に渡っていただけるような。","id":"exchange-115"},{"speaker":"伊藤委員","kind":"提案","question":"初めに、要望といいましょうか、触れるだけですけれども、八潮団地内道路バリアフリー化が入りました。これは私ども自民党が前々から提案してきた内容ですので、改めて感謝すると同時に、早期の完成をよろしくお願いいたします。これは先ほど我が会派の沢田委員も指摘をさせていただきましたが、私がさらにお伺いしたいのは、この水族館のあり方検討会が今開かれているはずですよね。","respondent":"多並公園課長","answer":"あり方検討会につきましては、平成２３年度、あり方検討委員会を設置いたしまして、５年先、１０年先の水族館のあり方について検討してきたところです。ただ、これは外部の委員の方からの目線ということで、３回ほど外部の専門委員との懇談会を開かせていただいています。","id":"exchange-116"},{"speaker":"伊藤委員","kind":"意見","question":"沢田委員も指摘をしていましたけれども、京都水族館に品川区議会自民党で行ってきました。そうであるならば、これも、そんなに長いことすみだ水族館の意向を見ていくのではなくて、例えば今年の秋ぐらいまでに１つの方向性を出していくとか。しながわ水族館あり方検討会のほうですけどね。","respondent":"多並公園課長","answer":"ただ、やはりこの水族館をはじめとしたような、このような業態は、なかなか先が読みにくいというところもあって、また、ほかの民間水族館のいろいろな展示等の動きもありまして、なかなか読みにくいというのが一番大きなところでして、今回大きいのが、新たにまたできた水族館。","id":"exchange-117"},{"speaker":"伊藤委員","kind":"質問・要望","question":"津波・高潮対策であります。私が言いたいのは、将来予想されるであろう首都直下地震のときに、今行っている地域の避難マップ作成はいいんだけれども、こういうもっと内陸部にある標高の低いところでそういう避難マップをつくるお考えは、つくるべきだと思うんですが、そこまでやはり準備をしていかないと、想定外のことに対処できないと思うんですが、いかがでしょう。","respondent":"武藤河川下水道課長","answer":"ですので、先般公表しました津波自主避難マップ作成マニュアルを引き続き普及して、こういった想定外の津波にも万全な対応をとってまいりたいと考えています。","id":"exchange-118"},{"speaker":"伊藤委員","kind":"確認","question":"今のお答えは、そうすると、海抜を見ればすぐにわかりますよね、低い地域が。海沿いでないところでありますけれども。そこの当該の町会、自治会等と協力をして、そういう自主避難マップをつくっていく方向性であるということで確認してよろしいんでしょうか。その辺をお願いいたします。","respondent":"武藤河川下水道課長","answer":"委員ご指摘のとおり、来年度につきましては、今回作成いたしましたマップの普及ということで、引き続き地域のほう、町会の方々のご協力等いただきながら、そのような低い地域、海沿いだけでなくて低い地域につきましても万全な対策をとってまいりたいと考えています。","id":"exchange-119"},{"speaker":"西本委員","kind":"確認","question":"３つまとめてお聞きします。これは確認ですけれども、道路下空洞、これ、ちょっと前なんですけれども、指摘をさせていただいて、２００９年だったでしょうか、国道１５号線ですね、北品川に空洞が見つかったということがありました。これを踏まえて、品川区でこの調査をするときに、どういう業者を使って調査を進めていくのかということについてお聞きします。","respondent":"稲田道路課長、多並公園課長、大串住宅担当課長","answer":"私ども、レーダーを搭載した車というんですかね、そういうので路面を走っていくというところの形で今は考えておりますが、今後その辺は、仕様等。私からは公園維持の中の借地料についてお答えします。それと、現在品川区の住宅のほうに入っていらっしゃる方ですが、建設型の区民住宅のほうに全部で７世帯、それと。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問・要望","question":"道路下空洞の調査なんですけれども、これ、よく調べてください。もう一度状況をお聞きします。ちょっと款が違うかもしれないんですけれども、この２０世帯の方々の交流というんですかね、品川区で被災者のためにいろいろな事業を展開して、それに参加をしていただいているという方が一部いらっしゃるんですけれども、２０世帯の方が何らかで品川区とのつながりがあるのかどうかについてお知らせください。","respondent":"松代防災まちづくり事業部長、大串住宅担当課長、稲田道路課長、武内危機管理室長","answer":"掘割構造ということは、線路の上がそのままあきますので、そういう中にあって、品川区のほうから。３年ということですので、平成２６年の４月５日まで、今現在のところでは入居をいただけるという状況です。ただ、技術も随分進んできて、精度も上がってきたということも聞いておりまして、よりしっかりと私どもも研究しまして。避難者の区内で受け入れている方は、区民住宅以外に５９所帯１１５名の方がいらっしゃるんですけれども、その方たちに。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問・要望","question":"３年間という期限がついておりますので、そこはいろいろと相談しながら進めていただきたいと思います。丁寧にその現状に合わせて、いろいろとできる限りしていただきたいと思います。次に、特定整備路線計画推進費、これはいろいろと今まで質問がありました。不燃化特区と、それから特定整備路線の２つあると思うんですけれども、それぞれについてお答えをいただきたいと思います。","respondent":"藤田都市計画課長、品川防災整備担当課長","answer":"特定整備路線のほうの関係ですけれども、今回４回ほど説明会をやらせていただいてあります。その中で、特定整備路線の大きな進め方、スケジュール感というものが説明をされてあります。予算の時期等もありますので、ここの９月で大方決まるのではないかなと思っていますが、東京都からの書面上では、正式には平成２６年３月に不燃化特区の本格実施地区が公表されるというような予定になってあります。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問","question":"流れが少し見えてきたなというところですが、ただ、平成３２年度までに、道路を整備するという完全な状況に平成３２年までにするよということの理解でよろしいんでしょうか、あわせてお聞きします。","respondent":"藤田都市計画課長","answer":"木密地域不燃化１０年プロジェクトでいうところの特定整備路線の関係ですけれども、こちらにつきましては、委員今お話がありましたとおり、延焼遮断帯の形成を促進するということで、その主要な都市計画道路の整備を２０２０年。","id":"exchange-123"},{"speaker":"西本委員","kind":"意見","question":"今目標とありましたね。開発道路とか、いろいろありますけれども、これでできるのかなと思うんですね。先ほどもいろいろ午前中もありましたけれども、やはりこの平成３２年までにどこまで現実的なところがあるのかな、相当な動きをしないとこれは難しいだろうと思いますが、その辺の現実的なところをどう考えていられるのか、言える範囲で結構ですので、お答えください。","respondent":"松代防災まちづくり事業部長、藤田都市計画課長","answer":"そういったことから、今回東京都は、２０２０年ということを１つの目標としまして、この道路整備の計画を進めると、こういったように理解しています。少しでも早く完成ができるように区のほうとしても支援をしながら進めていきたいと考えています。","id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"それが具体的に上がってきた。ですから、今いろいろな動きが出てきていて、今説明会が始まっております。しかしながら、建設的な意見だったらいいんですよ。そこら辺の住民との、住民の方々とのこれからの協働の仕方、まさに今濱野区長が出している協働というのは、そういう意味でいうと、地域を協働でつくっていくという大きな事例になるかと思いますので、その辺の考え方をお聞きします。","respondent":"藤田都市計画課長","answer":"東京都に対しても、そういったようなことを私どもから伝え、必要であれば、説明会のほうも、やり方もいろいろあろうかとは思いますけれども、現在開かれた説明会の中でも、東京都のほうからも要請があれば。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"これから盛んに説明会等々が始まると思うんですね。やはり急激に始めなきゃいけない、まあ、進んでいくだろうというふうになっておりますので、やはり建設的な意見を通しながら、情報もきっちりと出しながら、いろいろけんけんごうごうあると思いますけれども、住民と密な関係を持って、いい方向にいいまちをつくっていただきたいという要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-126"},{"speaker":"武内委員","kind":"質問","question":"横断歩道になっちゃっているというところがあるんですが、これはいつごろから始まって、今、何カ所ぐらい整備されていて、あと、その意味するところというのは何か、どういうことなのかというのを１つお聞きしたいのと、それから、公園・児童遊園のほうは、児童遊園について、児童遊園が来年度からいろんな防災性の向上の目的だとかで、いろんな角度で遊具の再配置とか。","respondent":"谷口交通安全担当課長、多並公園課長","answer":"委員ご質問の自転車横断帯ですけれども、これにつきましては、３５年ぐらい前に道交法が改正されまして、都内に約１万５,０００カ所以上の設置がされたところです。来年度につきましては、公園管理費の中で９４０万円ほど、５カ所を整備する予定です。","id":"exchange-127"},{"speaker":"武内委員","kind":"質問","question":"あれは区道ですか。それから、児童遊園については、そうすると５カ所ということで、防災性を考えていくということなので、それは、じゃあ、例えば遊具が真ん中にあるようなところを端っこに移設していくとか、もしくは遊具自体をなくしてしまうとか、そういうことにつながるのかなと思うんですけれども、その考え方とその５カ所を、もし予定がもう出ているんだったら、どこか教えてください。","respondent":"谷口交通安全担当課長、多並公園課長","answer":"委員ご質問の区役所前の交差点の自転車横断帯がなくなったですけれども、本来は幹線道路から進めているところですけれども。５カ所につきましては、ある程度の部分は現場を確認しておりますが、まだ来年度、地元の町会とか、利用の状況とか、ご意見をお伺いしながら、その５カ所については選定してまいりたい、そのように考えてあります。","id":"exchange-128"},{"speaker":"武内委員","kind":"質問・要望","question":"わかりました。多分私の、これ、間違っていたら指摘してほしいんですが、あれがなくなると、あの横断歩道に来たときには、自転車は１回おりて押していかなきゃいけないわけですよね、多分。その上で、防災性を付加するというのであれば、何かこう、さっきのトイレの話もありましたけれども、こういうものを例えば設置していくんだよとかというのもあれば、教えてください。","respondent":"谷口交通安全担当課長、多並公園課長","answer":"安全対策ですが、なかなか区民に対して周知が図られていないですので、これは関係機関、警察を含めて、関係団体と、自転車教室だとか各種キャンペーンで、広報、周知を図っていきたいと考えております。児童遊園の整備ですが、先ほどお話ししましたとおり、地元とこれから利用実態をよく踏まえた上で、お聞きしながら、整備内容について検討します。","id":"exchange-129"},{"speaker":"須藤委員","kind":"質問","question":"遠くのほうから商店街の流れがとまっちゃうんじゃないかと反対するような人もいるようですけれども、商店街の人がやっているので、しっかりとした商店街を中心にした再開発という形でつくられてきたと思うんですが、簡単で結構ですので、今後の流れについて教えてください。","respondent":"品川防災整備担当課長","answer":"今月末から４月にかけてぐらいになるかと思います。本組合のほうを結成しようと考えております。順調に本組合のほうを結成しますと、平成２５年７月ごろから秋ごろぐらいにかけてになると思います、権利変換のほうの認可のほうをしていこうと考えております。","id":"exchange-130"},{"speaker":"須藤委員","kind":"質問","question":"住宅改善というのは、内容的には高齢者用にフラットにするとか、そういう意味ですか。それとも、環境による改善とか、その辺、どっちなんだろう。","respondent":"大串住宅担当課長","answer":"工事の内容ですが、今委員おっしゃっていただいたように、エコ＆バリアフリーということで、環境ですとか、あるいはバリアフリーということで、今おっしゃっていただいたような床のフラット化、段差解消ですとか、あるいは手すり設置、こういった工事を対象にしているものです。","id":"exchange-131"},{"speaker":"須藤委員","kind":"質問・要望","question":"これもさっき松澤委員が言ったように、やはり住宅、高齢者の方がバリアフリーにしようとしたら、もう今年切れていますということで、だめですというような話をされてきた。新しい装置なので、各自治体で出している自治体もあるんだけれども、品川区はまだ入っていないと思うんだけれども、そのあたりは、それで申請した場合はどうなるか、お答えをいただきたいと思います。","respondent":"品川防災整備担当課長","answer":"制震ですので、また新たな技術というところで、区としましても、このようなところは、情報を入手しまして、研究していき、助成できるかどうかについても、今後研究していきたいと考えております。","id":"exchange-132"},{"speaker":"須藤委員","kind":"質問","question":"１基１０万円ぐらいで、数万円か１０万円って、まあ、企業によって違うんだけれども、それを１点、２点という形で、非常に安く密集地なんかでは補強をしてくるということができると思うので、そのあたりの研究、これから研究するということなんだけれども、もしいいものであるならば、そのことについてもできるんだということを区民に知らせて、できるだけ震災、倒れたり何かするのが少ないように。","respondent":"片田都市環境事業部長","answer":"そうした中で、区内業者という中で耐震の補強を行ってきたところなんですけれども、いろんな角度から研究して、本当に安全な建物ということでの一定の評価ができるものであれば、要綱の見直し等々含めた中で、前向きな対応を考えていきたいと考えています。","id":"exchange-133"},{"speaker":"飯沼委員","kind":"質問","question":"３１２ページ、都市開発費、市街地整備事業費についてお伺いをします。地区再開発事業ですけれども、新年度でも予算だけでも、大崎、大井町、目黒、五反田地域など、１００億円弱の税金投入が見込まれていますけれども、国、都の補助金と一般財源を充ててのことをお伺いします。開発のこの間どのくらいあったのか。事業の数と税金投入の総額を教えてください。","respondent":"溝口都市開発課長","answer":"これまで品川区内で行われている組合による再開発事業ですけれども、全体で１３地区になります。うち、３地区が事業中ということになっております。区のほうで出している補助金の額といたしましては、１３地区全体で約９２１億円が、今までの補助金の額という形になっております。","id":"exchange-134"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この間も大崎駅前のソニービルが売却をされたとか、あと、オフィスも、新しいところができると、どんどん周りのところ、中古がスラム化をしてしまっている状況が生まれていると思うんですが、ぜひその辺はつかんでいただきたいと思います。多額な税金が投入をされている再開発事業なんですが、メリットとデメリットを端的に教えてください。","respondent":"溝口都市開発課長","answer":"再開発事業を行うことによりまして、やはり都市基盤の整備ですとか、快適な広場空間、また、近年でありますと、防災備蓄倉庫、そういったものが整備されることによって、再開発事業をやった地域だけでなく、周辺市街地を含めて、よりよいまちづくりが進められると考えております。","id":"exchange-135"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川駅南地域の周辺まちづくり事業についてちょっとお伺いしますけれども、この事業での区の役割、何なのか、教えていただきたいのが１点。たびたび町会長たちが参加していますということで、地域の代表という扱いをされていますけれども、各組織の説明とか意見を反映される立場で参加をされているかどうか、その辺も教えてください。４つある都営住宅からの参加、あるのかどうかも教えてください。","respondent":"溝口都市開発課長","answer":"品川駅南地域における区のかかわりですけれども、区におきましては、平成２５年度予算にも計上していますように、品川駅南地域のまちづくりをどのように進めていくのか、そういったものをしっかり計画を示していきたいと考えていますし。","id":"exchange-136"},{"speaker":"飯沼委員","kind":"質問","question":"私は、今品川区が進めている再開発、デメリットのほうが大きいと受けとめています。特にオフィス、空室状況をつかんでいないということなので、新しいビルができることでどうまちに影響していくのかというのをしっかりつかむべきであると思います。こういった感想を述べられているそうです。このような開発に税金を投入するのは間違いであると思いますが、いかがでしょうか。","respondent":"溝口都市開発課長、山崎マスタープラン担当課長","answer":"再開発事業の件で、地域がなくなって、また地域のつながりがというお話がありましたが、私ども、そういうふうには思っておりませんで、これまでも再開発事業というのは、権利者、関係地権者の方がお話し合いを進めて。したがって、そうした特性を生かしながら、区としていろいろなまちづくりを誘導していく観点というのは、それぞれの区部、エリアで、全く考え方が違うと、こういった認識です。","id":"exchange-137"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川駅南地域なんですけれども、まちづくりビジョン、去年中間のまとめが出されましたけれども、今後どのように具体化をされるのか、スケジュールもあわせて教えてください。都営住宅、区民の要求が非常に高く、入るのに倍率が大変な中、不足していますけれども、北品川、東品川、都営が４つありますね、なくならないように、存続をして耐震化の立場で進めていただきたいと思いますが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"まちづくりビジョンだけじゃなく、これまでの再開発等の中での説明をということなんですが、これまでも十分説明、事業につきましては事業計画段階から事業者による説明、また都市計画段階の説明、また、計画につきましては。","id":"exchange-138"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私が求めたのは、計画立案の段階から、でき上がったものを説明するんじゃなくて、立案の段階からぜひ地域の方の意見を聞いて、計画を立てていただきたいということです。緑とか空間を求めていらっしゃるんですよ。５番目なんですね。開発をすればするほど、区民は開発を求めていない。この乖離というところからは、私は区民の意向を酌んで、再開発をやめるべきであると思いますが、いかがでしょうか。","respondent":"溝口都市開発課長","answer":"品川区のまちづくりについての考えですが、これまでも拠点開発、適時適切に進めてきております。先ほどの緑ですとか、空間、そういったものも生み出しながら再開発事業進めてきたものですので、引き続き拠点開発というのは品川区として進めていきたいと考えております。","id":"exchange-139"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今紹介したのは、区が行った世論調査です。ぜひ区民に寄り添ったまちづくり、進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"石田（慎）委員","kind":"質問","question":"私からは３１５ページ、百反歩道橋について、３１３ページ、西品川一丁目地区再開発について、２９９ページ、３０９ページ、バリアフリー事業について、それと３１５ページの大崎、五反田地区コーディネート業務委託についてお伺いします。初めに、百反歩道橋についてなんですが、これ、プレス発表ですね、ＪＲと施行協定を締結をしたというふうに出ていました。","respondent":"藤田都市計画課長、溝口都市開発課長","answer":"大崎短絡線の関係ですけれども、この間、ＪＲのほうから聞いている情報としては、今のところ大きな状況の変化はないと聞いてあります。西品川一丁目地区再開発における防災の観点での広場の整備ということですが、この国際自動車跡地を中心に、後背地を含め、２棟の建物を建てる計画をしておりまして、その間に約６,０００m2の広場を設け、その広場につきましては。","id":"exchange-141"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"西品川一丁目地区の防災活動の拠点の部分ですが、災害時にということですが、ぜひ地元の消防団の練習のスペース、専用のでなくてもいいので、そういった部分もぜひご検討をしていただきたいと思います。続きまして、道路バリアフリー化ですが、これ、あくまで事業としては、要はハード面の事業だと思いますが、ぜひソフト面の部分も行っていただきたいと思います。","respondent":"山崎マスタープラン担当課長、溝口都市開発課長","answer":"やっぱりなかなか到達点というのは難しいわけですので、繰り返し改善を続けながら、スパイラルアップをしていくというようなことで臨んでまいりたいと考えています。ですから、一定、大崎につきましては、これまで再開発事業を円滑に進めてきたというのはありますが、今後まちづくりの再開発事業がある程度収束に向かうということもありますので、大崎駅につきましては、来年度にかけて。","id":"exchange-142"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"バリアフリーはぜひ、さまざまなところから声を聞いていると思いますが、さらなるバリアフリー化に取り組んでいただければと思います。コーディネート業務委託なんですが、事務事業評価では重点的に見直す事業でＢの継続ということになっていますが、これ、事業実績が、まちづくり連絡会等開催が２回で１,８００万円、それは大崎のほうですね。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"３１７ページ、都市防災まちづくり事業費についてお聞きしたいと思います。この中で木造住宅密集地域についてですが、山手線外周部を中心に存在する木密地域では、建替え時期を迎えている老朽化した木造建築物が多く存在しているとありますが、これはまずなぜこういうふうになっているのか。そして、その特性についてちょっとお聞かせください。","respondent":"品川防災整備担当課長","answer":"それで、戦後、そこの部分に建替えをしたということで、１つの、何と言ったらいいんですかね、ますと言ったらよろしいんでしょうか、そのますが非常に広いために、そのますの中の部分に家が建ってしまっていると、道路がくっつかないところ、接道しない部分ができてしまって。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"今お話をお聞きしましたが、じゃあ、この木密地域に対して、現在建築基準法では、実際既存不適格というふうに判断されますよね。その建物というのは、この品川区に一体どのぐらい実際あるんでしょうか。おおよそで結構です。そして、その不適格とは大体どのような内容が多いんでしょうか、お聞かせください。","respondent":"中村建築課長","answer":"不適格建築物ですけれども、実際に接道、道路に接していない敷地というのは、もともと建築ができない状況ということで、ただ、昔からの経緯もあって建っているですけれども、そうしますと、今確認申請が出てきていないような現状でいきますと、現状。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"それはやはり大地震が起きて、大火災が起きて、延焼して、その地域一体が延焼されたら困る、燃えたら困るということだと思うんですが、もちろん中には建替えをしたいという方もいらっしゃると思うし、中には、経済的、そして、年齢的にも高齢化して、難しいというふうに思うんですが、その建替えをしたいという、経済的にも大丈夫だということで、経済的にも問題ない方でも、やはり建替えができない。","respondent":"品川防災整備担当課長","answer":"なかなか建替えができない理由というところですけれども、委員おっしゃったとおり、１つ大きなところとしては、資金の問題が一番なんですが、こういった密集事業地区の中というのは、ちょっと言い方悪いかもしれないですけれども。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"どこに住んでいた。ただ、その中で、例えば権利関係とか、そういう問題はクリアされて、経済的理由や、それから高齢化等の理由の方には、比較的、住替え誘導という形で、区でもこれからやっていくのかなと思うんですが、その辺についてどうなんでしょうか。でも、そういう方に対して、改善策として、規制・誘導手法というのも取り入れていると思うんですが、その辺についてちょっとお聞かせください。","respondent":"品川防災整備担当課長","answer":"建替えがいかないというところで、先ほど私のほうからも相続等のお話をしましたが、今回木密地域不燃化１０年プロジェクト、先行実施地区、これからやっていくんですけれども、その中で、例えば相続の問題ですと、弁護士とかを雇って、そういう問題を解消していただくとか。","id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"今ちょっとお聞きしただけでも、途方もない事業なのかなと。民間のゼネコンでも、再開発するとき、相当足を運ぶという話を聞いております。それで、個々に折衝する。でも、やはり進まないということもあるんですよね。できればそういう方でも、率先して、できる範囲で区としては支援をしていかないといけないと思うんですが、そういう方たちはどういうことで進まないんでしょうか。","respondent":"品川防災整備担当課長","answer":"例えば引っ越しについても、全部丸ごと、今だったら引っ越しの業者も丸ごとサービスというのがあると思うんですけれども、ああいったものがありますよとか、そういったことを、細かく高齢者の方に説明をしていくことによって、建替え等を促していきたいと考えております。","id":"exchange-148"},{"speaker":"須貝委員","kind":"質問","question":"だから、それで今粛々と進んでいる。ならば、そういう特例法というものを、まあ、区では無理だと思うんですが、都なり国にお願いしない限り、申しわけないですけれども、２０年たっても、３０年たっても、いや、下手すりゃ５０年たっても、権利がずっと続きますからね、相続すれば。孫、曾孫、恐らくこれ無理じゃないかと思うんですが、そういう法的な動きってあるんですか。","respondent":"品川防災整備担当課長、山崎マスタープラン担当課長","answer":"１つには、今木密地域不燃化１０年プロジェクトの先行実施地区で、コア事業と呼んでいます中延小学校の真南側にある、旧同潤会が建てた住宅地区があるんですけれども、そこで、防災街区整備事業というものを行っています。それで、おおむねそのエリアを平成３２年、２０２０年までにおおむね解消する方向を国のほうも打ち出しておりますので、そうしたもろもろの情報も重ね合わせて対応していく必要があるかなと考えています。","id":"exchange-149"},{"speaker":"須貝委員","kind":"質問・要望","question":"よろしく頑張ってやっていただきたいと思います。そこで、ちょっと今の話と別でお聞きしたいんですが、今品川区内で、前回もちょっとお話ししたかと思うんですが、空き地ができると。３階建て木造が建ってきます。そうすると、お隣とのすき間は３０センチメートル、４０センチメートルで建っているんですね。それで大丈夫なんですかという、逆にちょっと思うんですが、その辺についてもう１回お答えください。","respondent":"品川防災整備担当課長","answer":"戸越一丁目では、６０m2を最低敷地制限という形でやっております。こういう対策をとりながら、地区計画等進めていって、押さえていければと考えています。","id":"exchange-150"},{"speaker":"須貝委員","kind":"確認","question":"そこでちょっと１点だけ確認なんですが、今言った外壁なんかを燃えにくいものにしていますよね。ただ、ガラスは入っていますよね。ガラスは熱が加われば割れて、中に火が入りますよね。それの規制ってないわけですよね、実際。その辺についてどうなんですか、最後それだけお答えください。","respondent":"中村建築課長","answer":"隣地間の建物の関係ですが、窓は網入りガラスというものが義務づけられております。","id":"exchange-151"},{"speaker":"若林委員","kind":"質問・要望","question":"２点です。３０３ページの橋梁改修事業、これについて、いわゆる点検について確認をさせていただきたいと思います。いわゆる公営住宅の今の入居の倍率というのはどういう状況になっているのかというのを確認をするのと、一方、民間住宅、これは持家とか賃貸とかありますけれども、いわゆる空き家、空き室の状況が今どういうふうになっているのかと、これを教えていただきたいと思います。","respondent":"稲田道路課長、大串住宅担当課長","answer":"今度、５年に一度ということで、また点検をやっていくところですが、これも基本的にはやはり目視なんですが、目視で見まして、異常があるようなところ、そういうのは目視でわかってきますので、そこは打音、たたきをやったり、それから。民間の賃貸住宅ですが、空き室の関係につきましては、２万５,０００戸ほどの空き家があるということで、これは数字上では把握しているといったところです。","id":"exchange-152"},{"speaker":"若林委員","kind":"提案","question":"今後のいわゆる橋梁の長寿命化計画の中で、５年、１０年、２０年、３０年というスパンで計画的に橋梁の改修を行っていくんですけれども、３０５ページに載っておりますけれども、水辺利活用事業、これとリンクをさせられないかなというふうに、これ提案になるんですかね。住宅のほうは、区営住宅の倍率が、これは２倍というふうに読むんですかね、９９％。足りないのかな。１００％未満だ。","respondent":"武藤河川下水道課長、大串住宅担当課長","answer":"来年度につきましては、この予算につきましては、桟橋および船の維持管理を適切にやっていくということで、実際に船を所有した後は、やはり災害時の舟運だとか、平常時におきましても。住宅困窮者に対して空き家を活用していくというところで、区のほうといたしましても、やはり不動産業界の方ですとか、そういった方と連携をしながら、この２万５,０００戸ある空き家、これをどのような形で活用していけるかどうか。","id":"exchange-153"},{"speaker":"若林委員","kind":"質問・要望","question":"じゃあ、水辺活用についてはぜひ研究、検討していただきたいと思います。住宅のほうについては、不動産とも連携をしてというご答弁がありました。お話を聞いております。これはやっぱり行政品川区が一定力を貸し、手を差し伸べていかないと、これは民民の話では、どうにもならないということはずっと感じていますので、ぜひお力を貸していただきたい、区民の方にお力を貸していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-154"},{"speaker":"大沢委員","kind":"質問・要望","question":"３０５ページ、目黒川、そして、３１７ページの避難道路機能強化事業と武蔵小山ということで聞きます。最初に武蔵小山のほうから伺いしますけれども、前回の決算特別委員会で、武蔵小山って何ぞやということで、都市開発課長に伺いました。アーケードがあるのはもうわかっていますから。お願いします。","respondent":"溝口都市開発課長","answer":"武蔵小山のまちですが、商店街がある活気あるまちというふうに感じております。ですから、そういった活気を継続できるまちづくりを進めていきたいと考えております。","id":"exchange-155"},{"speaker":"大沢委員","kind":"質問","question":"昭和３１年当時の武蔵小山駅が載っていたりということで、いろんな武蔵小山の位置づけというか、武蔵小山のまちの絵というものがここのところに引かれているわけですけれども、そこのところ、どういうふうに武蔵小山って考えていらっしゃるのか、すみません、改めて教えてください。","respondent":"山崎マスタープラン担当課長","answer":"いろんな、まあ、確かに商店街もそうですけれども、いろいろそこには当然まちがあって、人の生活があって、なりわいという経済活動があって、そうした中で、いろんな意味で、何というか、いろいろ映画館があったり、そうした、マスタープラン上。","id":"exchange-156"},{"speaker":"大沢委員","kind":"質問・要望","question":"武蔵小山はアーケードだけではないのでありますから、あそこらのところ、もう１回どういうふうにとらえていくのか、絵をどういうふうに引いていくのかということを改めてやはり考えていただきたいのが１つですし、やはりまちというのは、４０年、５０年の間にスパンで変わってまいります。古くは開拓団行ったんですよ、商店街の人たちが。ですから、まちというのは、１０年や１５年でできるわけがない。","respondent":"溝口都市開発課長","answer":"委員ご指摘のとおり、西の玄関口にふさわしいまちづくりを進めていきたいと考えております。","id":"exchange-157"},{"speaker":"大沢委員","kind":"質問・要望","question":"本当に西の玄関口、開発のいろんなありようはあります。まちがよくなれば私たちはいいわけですから、そこのところ、十分ご斟酌いただきながら、武蔵小山のまちづくりをしっかりとやっていただきたいと思いますし、商店街におきましても、２３０店舗あるうち、残っているのは４０店舗だけです。感じているだけなのか、そこのところちょっと説明いただきたいと思うんですけれども。","respondent":"武藤河川下水道課長","answer":"そういった形で、一定の対策は進みましたけれども、やはりまだまだ抜本的な対策が必要だということで、区としては強く認識しておりますので、引き続き東京都のほうにはそういった要望を続けていきたいと考えています。","id":"exchange-158"},{"speaker":"大沢委員","kind":"質問・要望","question":"やはり都と連携をしながら、本当に実現をすべく、アユが住める川でしょうか、しっかりと継続しながらこの事業を行っていただきたいと思うんですけれども、ここの事業のいろんな、これを浄化するに当たっての手法なり、いろんな部分で限界というのは感じられている部分はあるんでしょうか、どうなんですか。","respondent":"武藤河川下水道課長","answer":"いずれにしましても、一定の費用がかかるとともに、こういった事業につきましては、本来、管理者である東京都が進めるべきものと考えておりますので、区としてもできることは今後も進めてまいりますけれども、引き続き東京都とそういった要望を続けながら。","id":"exchange-159"},{"speaker":"大沢委員","kind":"質問・要望","question":"海水導入については莫大な費用がかかるということは私どもも聞いておりますので、ぜひとも、費用がかかるのは十分承知ですけれども、やはり先ほどのまちづくりと一緒に、将来を見据えた目黒川づくりを行っていただきたいなと。大変なのは十分承知の上でこのお話をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-160"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/167818?Template=document&Id=992#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":127416,"voices":394}}]);
